css:
/* Three-pane inbox. Re-theme with --apm-panes-paper, -ink, -accent (and -h). */
.apm-panes {
  --apm-panes-paper: oklch(0.984 0.008 85);
  --apm-panes-ink: oklch(0.26 0.022 55);
  --apm-panes-accent: oklch(0.62 0.185 38);
  --apm-panes-list: 360px;

  --apm-panes-side: color-mix(in oklch, var(--apm-panes-paper) 95%, var(--apm-panes-ink));
  --apm-panes-line: color-mix(in oklch, var(--apm-panes-ink) 11%, transparent);
  --apm-panes-muted: color-mix(in oklch, var(--apm-panes-ink) 58%, var(--apm-panes-paper));
  --apm-panes-faint: color-mix(in oklch, var(--apm-panes-ink) 38%, var(--apm-panes-paper));
  --apm-panes-hover: color-mix(in oklch, var(--apm-panes-ink) 5%, transparent);
  --apm-panes-tint: color-mix(in oklch, var(--apm-panes-accent) 11%, var(--apm-panes-paper));
  --apm-panes-ring: color-mix(in oklch, var(--apm-panes-accent) 70%, transparent);
  --apm-panes-ease: cubic-bezier(.2, .8, .2, 1);
  --apm-panes-spring: linear(0, 0.06 3%, 0.24 7%, 0.6 14%, 0.86 21%, 1.01 29%, 1.06 35%, 1.05 42%, 1.01 55%, 0.995 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apm-panes-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 14px;
  background: var(--apm-panes-paper);
  color: var(--apm-panes-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  outline: none;
  box-shadow: 0 0 0 1px var(--apm-panes-line), 0 24px 60px -30px color-mix(in oklch, var(--apm-panes-ink) 40%, transparent);
}
:where(.apm-panes) *, :where(.apm-panes) *::before, :where(.apm-panes) *::after { box-sizing: border-box; }
:where(.apm-panes) :is(button, input, textarea) { font: inherit; color: inherit; }
:where(.apm-panes) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apm-panes) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apm-panes) kbd {
  font: 500 10.5px/1 ui-monospace, Menlo, monospace;
  padding: 3px 5px 2px; border-radius: 4px; min-width: 18px; text-align: center; display: inline-block;
  background: color-mix(in oklch, var(--apm-panes-ink) 6%, var(--apm-panes-paper));
  box-shadow: inset 0 -1px 0 var(--apm-panes-line), 0 0 0 1px var(--apm-panes-line);
  color: var(--apm-panes-muted);
}
:where(.apm-panes) :focus-visible { outline: 2px solid var(--apm-panes-ring); outline-offset: 2px; }

/* ---------- shell ---------- */
.apm-panes__app {
  display: grid;
  height: 100%;
  grid-template-columns: 220px var(--apm-panes-list) minmax(0, 1fr);
  grid-template-areas: "nav list reader";
}
.apm-panes__nav { grid-area: nav; }
.apm-panes__list { grid-area: list; }
.apm-panes__reader { grid-area: reader; }

/* ---------- nav ---------- */
.apm-panes__nav {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  gap: 10px;
  padding: 16px 12px 14px;
  background: var(--apm-panes-side);
  border-right: 1px solid var(--apm-panes-line);
  min-height: 0;
}
.apm-panes__brand { display: flex; align-items: center; gap: 9px; padding: 2px 8px 6px; font-weight: 650; letter-spacing: -0.01em; }
.apm-panes__brand svg { width: 22px; height: 22px; color: var(--apm-panes-accent); }
.apm-panes__compose {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: 10px;
  background: var(--apm-panes-ink); color: var(--apm-panes-paper);
  font-weight: 600;
  box-shadow: 0 1px 0 color-mix(in oklch, white 18%, transparent) inset, 0 6px 16px -8px var(--apm-panes-ink);
  transition: transform .25s var(--apm-panes-spring), box-shadow .25s var(--apm-panes-ease);
}
.apm-panes__compose:hover { transform: translateY(-1px); }
.apm-panes__compose:active { transform: translateY(1px) scale(.98); }
.apm-panes__compose kbd { margin-left: auto; background: color-mix(in oklch, var(--apm-panes-paper) 14%, transparent); color: inherit; box-shadow: none; }
.apm-panes__navscroll { position: relative; overflow: auto; min-height: 0; padding: 2px; scrollbar-width: none; }
.apm-panes__folders, .apm-panes__labels { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; }
.apm-panes__navlabel {
  margin: 16px 10px 6px; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apm-panes-faint);
}
.apm-panes__pill {
  position: absolute; left: 2px; right: 2px; top: 0; height: 34px;
  border-radius: 8px; background: var(--apm-panes-paper);
  box-shadow: 0 0 0 1px var(--apm-panes-line), 0 2px 6px -3px color-mix(in oklch, var(--apm-panes-ink) 30%, transparent);
  translate: 0 var(--y, 0px);
  transition: translate .5s var(--apm-panes-spring), opacity .2s;
  pointer-events: none;
}
.apm-panes__fold {
  position: relative; z-index: 1;
  width: 100%; display: flex; align-items: center; gap: 11px;
  height: 34px; padding: 0 10px; border-radius: 8px;
  color: var(--apm-panes-muted); font-weight: 500; text-align: left;
  transition: color .2s, background-color .2s;
}
.apm-panes__fold:hover { color: var(--apm-panes-ink); }
.apm-panes__fold[aria-current="true"] { color: var(--apm-panes-ink); font-weight: 600; }
.apm-panes__fold[aria-current="true"] svg { color: var(--apm-panes-accent); }
.apm-panes__fold .apm-panes__n { margin-left: auto; font-size: 12px; font-variant-numeric: tabular-nums; color: var(--apm-panes-faint); }
.apm-panes__fold .apm-panes__n[data-hot] { color: var(--apm-panes-accent); font-weight: 650; }
.apm-panes__fold.is-drop {
  background: var(--apm-panes-tint); color: var(--apm-panes-ink);
  box-shadow: inset 0 0 0 1.5px var(--apm-panes-accent);
  animation: apm-panes-throb .9s var(--apm-panes-ease) infinite alternate;
}
.apm-panes__dot { width: 9px; height: 9px; margin: 0 4.5px; border-radius: 3px; background: oklch(0.64 0.14 var(--h)); flex: none; }
.apm-panes__storage { display: grid; gap: 6px; padding: 10px 10px 0; font-size: 12px; color: var(--apm-panes-muted); font-variant-numeric: tabular-nums; }
.apm-panes__storage b { color: var(--apm-panes-ink); font-weight: 600; }
.apm-panes__meter { height: 4px; border-radius: 4px; background: var(--apm-panes-line); overflow: hidden; }
.apm-panes__meter i { display: block; height: 100%; width: 100%; background: var(--apm-panes-ink); transform-origin: left; scale: var(--v) 1; }

/* ---------- list ---------- */
.apm-panes__list {
  position: relative;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  min-height: 0;
  border-right: 1px solid var(--apm-panes-line);
}
.apm-panes__listhead { display: flex; align-items: center; gap: 10px; padding: 16px 16px 10px; }
.apm-panes__titlewrap { display: grid; min-width: 0; }
.apm-panes__title { margin: 0; font-size: clamp(1.05rem, .9rem + .6cqi, 1.3rem); font-weight: 680; letter-spacing: -0.02em; line-height: 1.15; text-wrap: balance; }
.apm-panes__count { font-size: 12px; color: var(--apm-panes-muted); font-variant-numeric: tabular-nums; }
.apm-panes__filter {
  margin-left: auto; display: flex; align-items: center; gap: 6px;
  height: 32px; padding: 0 6px 0 9px; border-radius: 8px; width: min(170px, 46%);
  background: color-mix(in oklch, var(--apm-panes-ink) 4.5%, transparent);
  color: var(--apm-panes-muted);
  transition: box-shadow .2s, background-color .2s;
}
.apm-panes__filter:has(input:focus) { background: var(--apm-panes-paper); box-shadow: 0 0 0 1.5px var(--apm-panes-accent); }
.apm-panes__filter svg { width: 15px; height: 15px; }
.apm-panes__filter input { border: 0; background: none; outline: none; min-width: 0; width: 100%; font-size: 13px; color: var(--apm-panes-ink); }
.apm-panes__filter:has(input:focus) kbd, .apm-panes__filter:has(input:not(:placeholder-shown)) kbd { opacity: 0; }

.apm-panes__icon { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 8px; color: var(--apm-panes-muted); transition: background-color .15s, color .15s; flex: none; }
.apm-panes__icon:hover { background: var(--apm-panes-hover); color: var(--apm-panes-ink); }
.apm-panes__menu { display: none; }

.apm-panes__bulk {
  display: flex; align-items: center; gap: 2px;
  padding: 4px 10px 8px 16px; min-height: 42px;
  border-bottom: 1px solid var(--apm-panes-line);
}
.apm-panes__all { width: 18px; height: 18px; border-radius: 5px; box-shadow: inset 0 0 0 1.5px var(--apm-panes-faint); display: grid; place-items: center; margin-right: 10px; transition: background-color .15s, box-shadow .15s; }
.apm-panes__all i { width: 8px; height: 2px; border-radius: 2px; background: var(--apm-panes-paper); scale: 0; transition: scale .2s var(--apm-panes-spring); }
.apm-panes__all[aria-checked="true"], .apm-panes__all[aria-checked="mixed"] { background: var(--apm-panes-accent); box-shadow: none; }
.apm-panes__all[aria-checked="true"] i { height: 8px; width: 8px; border-radius: 2px; scale: 1; }
.apm-panes__all[aria-checked="mixed"] i { scale: 1; }
.apm-panes__bulkcount { font-size: 12px; color: var(--apm-panes-muted); font-variant-numeric: tabular-nums; margin-right: auto; white-space: nowrap; }
.apm-panes__tool {
  display: flex; align-items: center; gap: 6px; height: 30px; padding: 0 9px; border-radius: 7px;
  font-size: 12.5px; color: var(--apm-panes-muted);
  transition: background-color .15s, color .15s, opacity .2s, translate .3s var(--apm-panes-ease);
}
.apm-panes__tool svg { width: 16px; height: 16px; }
.apm-panes__tool:hover { background: var(--apm-panes-hover); color: var(--apm-panes-ink); }
.apm-panes__bulk:not([data-on]) .apm-panes__tool { opacity: .38; }
.apm-panes__bulk:not([data-on]) .apm-panes__tool span { display: none; }
.apm-panes__bulk[data-on] .apm-panes__tool { color: var(--apm-panes-ink); }
@container (width < 1100px) { .apm-panes__tool span { display: none; } }

.apm-panes__rows { list-style: none; margin: 0; padding: 4px 0 10px; overflow: auto; min-height: 0; outline: none; overscroll-behavior: contain; scrollbar-width: thin; }
.apm-panes__row {
  --pad: 16px;
  position: relative;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  gap: 2px 12px;
  padding: 11px 12px 11px var(--pad);
  cursor: default;
  user-select: none;
  transition: background-color .18s;
}
.apm-panes__row + .apm-panes__row::after { content: ""; position: absolute; left: 62px; right: 12px; top: 0; height: 1px; background: var(--apm-panes-line); }
.apm-panes__row:hover { background: var(--apm-panes-hover); }
.apm-panes__row::before {
  content: ""; position: absolute; left: 0; top: 8px; bottom: 8px; width: 3px; border-radius: 0 3px 3px 0;
  background: var(--apm-panes-accent); scale: 1 0; transition: scale .35s var(--apm-panes-spring);
}
.apm-panes__row[data-current] { background: var(--apm-panes-tint); }
.apm-panes__row[data-current]::before { scale: 1 1; }
.apm-panes__row[data-current] + .apm-panes__row::after, .apm-panes__row[data-current]::after { opacity: 0; }
.apm-panes__row[aria-selected="true"] { background: color-mix(in oklch, var(--apm-panes-accent) 7%, var(--apm-panes-paper)); }
.apm-panes__rows:focus-visible .apm-panes__row[data-current] { box-shadow: inset 0 0 0 2px var(--apm-panes-ring); }
.apm-panes__row.is-dragging { opacity: .45; }
.apm-panes__rows[data-enter] .apm-panes__row { animation: apm-panes-rise .5s var(--apm-panes-ease) both; animation-delay: calc(var(--i) * 26ms); }

/* avatar flips to a checkbox on hover or in selection mode */
.apm-panes__pick { position: relative; width: 34px; height: 34px; perspective: 300px; grid-row: span 3; }
.apm-panes__av, .apm-panes__check {
  position: absolute; inset: 0; border-radius: 50%; display: grid; place-items: center;
  backface-visibility: hidden; transition: transform .42s var(--apm-panes-spring);
}
.apm-panes__av {
  font-size: 12px; font-weight: 650; letter-spacing: .02em;
  background: oklch(0.9 0.05 var(--h)); color: oklch(0.38 0.09 var(--h));
}
.apm-panes__check { transform: rotateY(180deg); background: var(--apm-panes-paper); box-shadow: inset 0 0 0 1.5px var(--apm-panes-faint); border-radius: 9px; }
.apm-panes__check svg { width: 16px; height: 16px; stroke-width: 2.4; stroke-dasharray: 22; stroke-dashoffset: 22; transition: stroke-dashoffset .3s var(--apm-panes-ease) .05s; }
.apm-panes__row:hover .apm-panes__av,
.apm-panes__rows:has([aria-selected="true"]) .apm-panes__av { transform: rotateY(-180deg); }
.apm-panes__row:hover .apm-panes__check,
.apm-panes__rows:has([aria-selected="true"]) .apm-panes__check { transform: rotateY(0); }
.apm-panes__row[aria-selected="true"] .apm-panes__check { background: var(--apm-panes-accent); box-shadow: none; color: var(--apm-panes-paper); }
.apm-panes__row[aria-selected="true"] .apm-panes__check svg { stroke-dashoffset: 0; }

.apm-panes__top { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.apm-panes__from { font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.apm-panes__time { margin-left: auto; font-size: 12px; color: var(--apm-panes-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.apm-panes__subj { font-size: 13.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-panes__snip { font-size: 12.5px; color: var(--apm-panes-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-panes__row[data-unread] .apm-panes__from, .apm-panes__row[data-unread] .apm-panes__subj { font-weight: 680; }
.apm-panes__row[data-unread] .apm-panes__time { color: var(--apm-panes-accent); font-weight: 600; }
.apm-panes__unread { width: 7px; height: 7px; border-radius: 50%; background: var(--apm-panes-accent); align-self: center; flex: none; }
.apm-panes__side { grid-column: 3; grid-row: 1 / span 3; display: grid; align-content: space-between; justify-items: end; gap: 6px; }
.apm-panes__star { color: var(--apm-panes-faint); padding: 2px; border-radius: 6px; transition: color .2s, transform .35s var(--apm-panes-spring); }
.apm-panes__star:hover { color: var(--apm-panes-ink); }
.apm-panes__star[data-on] { color: oklch(0.75 0.16 75); }
.apm-panes__star[data-on] svg { fill: currentColor; }
.apm-panes__star:active { transform: scale(.8); }
.apm-panes__star svg { width: 16px; height: 16px; }
.apm-panes__clip svg { width: 14px; height: 14px; color: var(--apm-panes-faint); }
.apm-panes__chips { display: flex; gap: 4px; flex-wrap: wrap; margin-top: 3px; }
.apm-panes__chip { display: inline-flex; align-items: center; gap: 5px; height: 18px; padding: 0 7px 0 6px; border-radius: 5px; font-size: 11px; font-weight: 550; background: oklch(0.94 0.035 var(--h)); color: oklch(0.42 0.1 var(--h)); }
.apm-panes__chip::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: currentColor; }

.apm-panes__keys { display: flex; flex-wrap: wrap; gap: 4px 14px; padding: 9px 16px; border-top: 1px solid var(--apm-panes-line); font-size: 11.5px; color: var(--apm-panes-faint); }
.apm-panes__keys kbd { margin-right: 2px; }

.apm-panes__split {
  position: absolute; z-index: 3; top: 0; bottom: 0; right: -5px; width: 9px; cursor: col-resize; touch-action: none;
}
.apm-panes__split::after {
  content: ""; position: absolute; left: 4px; top: 0; bottom: 0; width: 1px; background: transparent;
  transition: background-color .2s, box-shadow .2s;
}
.apm-panes__split:hover::after, .apm-panes__split.is-active::after, .apm-panes__split:focus-visible::after { background: var(--apm-panes-accent); box-shadow: 0 0 0 1px var(--apm-panes-accent); }
.apm-panes__split:focus-visible { outline: none; }

.apm-panes__empty { display: grid; place-items: center; align-content: center; gap: 10px; height: 100%; padding: 30px; text-align: center; color: var(--apm-panes-muted); }
.apm-panes__empty svg { width: 64px; height: 64px; stroke-width: 1.2; color: var(--apm-panes-faint); }
.apm-panes__empty svg path { stroke-dasharray: 120; animation: apm-panes-draw 1.1s var(--apm-panes-ease) both; }
.apm-panes__empty b { color: var(--apm-panes-ink); font-size: 15px; font-weight: 620; text-wrap: balance; }
.apm-panes__empty p { margin: 0; max-width: 32ch; text-wrap: pretty; font-size: 13px; }

/* ---------- reader ---------- */
.apm-panes__reader { display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; min-width: 0; background: var(--apm-panes-paper); }
.apm-panes__rhead { display: flex; align-items: center; gap: 2px; padding: 12px 14px 10px 18px; border-bottom: 1px solid var(--apm-panes-line); }
.apm-panes__back { display: none; }
.apm-panes__pos { margin-left: auto; margin-right: 6px; font-size: 12px; color: var(--apm-panes-muted); font-variant-numeric: tabular-nums; }
.apm-panes__icon[aria-pressed="true"] { color: oklch(0.72 0.16 75); }
.apm-panes__icon[aria-pressed="true"] svg { fill: currentColor; }
.apm-panes__rscroll { overflow: auto; min-height: 0; padding: clamp(18px, 3cqi, 34px) clamp(18px, 4cqi, 48px) 40px; overscroll-behavior: contain; scrollbar-width: thin; }
.apm-panes__doc { max-width: 68ch; }
.apm-panes__doc > * {
  transition: opacity .45s var(--apm-panes-ease), translate .55s var(--apm-panes-ease), filter .45s var(--apm-panes-ease);
  transition-delay: calc(var(--i, 0) * 40ms);
  @starting-style { opacity: 0; translate: 0 10px; filter: blur(3px); }
}
.apm-panes__rsubj { margin: 0 0 10px; font-size: clamp(1.2rem, .95rem + 1.1cqi, 1.65rem); line-height: 1.2; font-weight: 680; letter-spacing: -0.022em; text-wrap: balance; }
.apm-panes__sender { display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; gap: 0 12px; align-items: center; margin: 18px 0 22px; }
.apm-panes__sender .apm-panes__av { position: static; width: 40px; height: 40px; font-size: 13px; }
.apm-panes__sender b { font-weight: 640; }
.apm-panes__sender small { display: block; color: var(--apm-panes-muted); font-size: 12.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-panes__sender time { font-size: 12.5px; color: var(--apm-panes-muted); font-variant-numeric: tabular-nums; align-self: start; padding-top: 2px; }
.apm-panes__body p { margin: 0 0 1em; text-wrap: pretty; font-size: 14.5px; line-height: 1.62; }
.apm-panes__body table { border-collapse: collapse; margin: 4px 0 18px; font-size: 13px; font-variant-numeric: tabular-nums; min-width: min(100%, 360px); }
.apm-panes__body td { padding: 6px 18px 6px 0; border-bottom: 1px solid var(--apm-panes-line); }
.apm-panes__body td:last-child { text-align: right; padding-right: 0; }
.apm-panes__body tr:last-child td { border-bottom: 0; }
.apm-panes__body table.is-total tr:last-child td { font-weight: 650; border-top: 1.5px solid var(--apm-panes-ink); }
.apm-panes__files { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0 24px; }
.apm-panes__file { display: grid; grid-template-columns: 34px auto; grid-template-rows: auto auto; column-gap: 10px; align-items: center; padding: 8px 14px 8px 8px; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--apm-panes-line); font-size: 12.5px; transition: box-shadow .2s, translate .3s var(--apm-panes-spring); }
.apm-panes__file:hover { translate: 0 -2px; box-shadow: inset 0 0 0 1px var(--apm-panes-faint); }
.apm-panes__file i { grid-row: span 2; width: 34px; height: 34px; border-radius: 7px; display: grid; place-items: center; font: 700 9px/1 ui-monospace, Menlo, monospace; letter-spacing: .04em; background: oklch(0.93 0.04 var(--h)); color: oklch(0.42 0.11 var(--h)); font-style: normal; }
.apm-panes__file small { color: var(--apm-panes-muted); font-variant-numeric: tabular-nums; }
.apm-panes__reply { display: flex; gap: 8px; flex-wrap: wrap; }
.apm-panes__btn { display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 14px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--apm-panes-line); font-weight: 550; font-size: 13px; transition: background-color .15s, box-shadow .15s; }
.apm-panes__btn:hover { background: var(--apm-panes-hover); box-shadow: inset 0 0 0 1px var(--apm-panes-faint); }
.apm-panes__btn kbd { margin-left: 2px; }
.apm-panes__btn svg { width: 16px; height: 16px; }
.apm-panes__box { display: grid; gap: 10px; padding: 14px; border-radius: 12px; box-shadow: inset 0 0 0 1px var(--apm-panes-line), 0 10px 30px -18px color-mix(in oklch, var(--apm-panes-ink) 50%, transparent); }
.apm-panes__box small { color: var(--apm-panes-muted); font-size: 12px; }
.apm-panes__box textarea { width: 100%; min-height: 96px; resize: vertical; border: 0; outline: none; background: none; line-height: 1.55; font-size: 14px; }
.apm-panes__box footer { display: flex; gap: 8px; align-items: center; }
.apm-panes__send { display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 14px; border-radius: 9px; background: var(--apm-panes-accent); color: oklch(0.99 0.01 85); font-weight: 620; font-size: 13px; transition: transform .25s var(--apm-panes-spring), filter .2s; }
.apm-panes__send:hover { filter: brightness(1.06); }
.apm-panes__send:active { transform: scale(.97); }
.apm-panes__send kbd { background: color-mix(in oklch, white 20%, transparent); color: inherit; box-shadow: none; }
.apm-panes__sent { margin: 0 0 18px; padding: 12px 14px; border-radius: 10px; background: color-mix(in oklch, var(--apm-panes-accent) 6%, var(--apm-panes-paper)); border-left: 3px solid var(--apm-panes-accent); font-size: 13.5px; white-space: pre-wrap; text-wrap: pretty;
  transition: opacity .4s var(--apm-panes-ease), translate .5s var(--apm-panes-spring);
  @starting-style { opacity: 0; translate: 0 12px; }
}
.apm-panes__sent small { display: block; color: var(--apm-panes-muted); font-size: 11.5px; margin-bottom: 4px; }

/* ---------- overlays ---------- */
.apm-panes__scrim { position: absolute; inset: 0; z-index: 8; background: color-mix(in oklch, var(--apm-panes-ink) 28%, transparent); opacity: 0; pointer-events: none; transition: opacity .3s; }
.apm-panes__menu-pop {
  position: absolute; z-index: 20; min-width: 200px; padding: 6px; border-radius: 12px;
  background: var(--apm-panes-paper);
  box-shadow: 0 0 0 1px var(--apm-panes-line), 0 18px 40px -16px color-mix(in oklch, var(--apm-panes-ink) 55%, transparent);
  display: grid; gap: 1px; transform-origin: top left;
  transition: opacity .18s, scale .3s var(--apm-panes-spring), display .3s allow-discrete;
  @starting-style { opacity: 0; scale: .94; }
}
.apm-panes__menu-pop[hidden] { display: none; opacity: 0; scale: .96; }
.apm-panes__menu-pop p { margin: 4px 8px 4px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--apm-panes-faint); }
.apm-panes__opt { display: flex; align-items: center; gap: 10px; height: 32px; padding: 0 10px; border-radius: 7px; font-size: 13px; }
.apm-panes__opt svg { width: 16px; height: 16px; color: var(--apm-panes-muted); }
.apm-panes__opt[data-active] { background: var(--apm-panes-tint); }
.apm-panes__opt[aria-checked="true"]::after { content: "✓"; margin-left: auto; color: var(--apm-panes-accent); font-weight: 700; }

.apm-panes__sheet {
  position: absolute; z-index: 15; right: 18px; bottom: 18px; width: min(440px, calc(100% - 36px));
  display: grid; gap: 0; border-radius: 14px; overflow: hidden;
  background: var(--apm-panes-paper);
  box-shadow: 0 0 0 1px var(--apm-panes-line), 0 30px 70px -24px color-mix(in oklch, var(--apm-panes-ink) 60%, transparent);
  transform-origin: bottom right;
  transition: opacity .25s var(--apm-panes-ease), translate .45s var(--apm-panes-spring), scale .45s var(--apm-panes-spring), display .45s allow-discrete;
  @starting-style { opacity: 0; translate: 0 24px; scale: .96; }
}
.apm-panes__sheet[hidden] { display: none; opacity: 0; translate: 0 16px; scale: .98; }
.apm-panes__sheet header { display: flex; align-items: center; justify-content: space-between; padding: 8px 8px 8px 16px; background: var(--apm-panes-ink); color: var(--apm-panes-paper); }
.apm-panes__sheet header .apm-panes__icon { color: inherit; }
.apm-panes__sheet header .apm-panes__icon:hover { background: color-mix(in oklch, var(--apm-panes-paper) 14%, transparent); }
.apm-panes__sheet label { display: flex; gap: 10px; align-items: center; padding: 0 16px; border-bottom: 1px solid var(--apm-panes-line); }
.apm-panes__sheet label span { font-size: 12.5px; color: var(--apm-panes-muted); width: 52px; }
.apm-panes__sheet input { flex: 1; min-width: 0; height: 40px; border: 0; outline: none; background: none; font-size: 13.5px; }
.apm-panes__sheet textarea { border: 0; outline: none; background: none; resize: none; padding: 14px 16px; font-size: 14px; line-height: 1.55; }
.apm-panes__sheet footer { display: flex; gap: 8px; padding: 10px 12px 12px 16px; }
.apm-panes__ghostbtn { height: 34px; padding: 0 12px; border-radius: 9px; color: var(--apm-panes-muted); font-size: 13px; }
.apm-panes__ghostbtn:hover { background: var(--apm-panes-hover); color: var(--apm-panes-ink); }

.apm-panes__toast {
  position: absolute; z-index: 30; left: 50%; bottom: 18px;
  display: flex; align-items: center; gap: 14px;
  padding: 8px 8px 8px 16px; border-radius: 12px;
  background: var(--apm-panes-ink); color: var(--apm-panes-paper);
  font-size: 13px; white-space: nowrap;
  box-shadow: 0 16px 40px -14px color-mix(in oklch, var(--apm-panes-ink) 70%, transparent);
  translate: -50% 140%; opacity: 0; pointer-events: none;
  transition: translate .5s var(--apm-panes-spring), opacity .25s;
}
.apm-panes__toast[data-show] { translate: -50% 0; opacity: 1; pointer-events: auto; }
.apm-panes__toast button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px 0 10px; border-radius: 7px; font-weight: 620; color: oklch(0.85 0.12 50); }
.apm-panes__toast button:hover { background: color-mix(in oklch, var(--apm-panes-paper) 12%, transparent); }
.apm-panes__toast button[hidden] { display: none; }
.apm-panes__toast kbd { background: color-mix(in oklch, var(--apm-panes-paper) 14%, transparent); color: inherit; box-shadow: none; }

.apm-panes__dragimg {
  position: absolute; z-index: -1; left: 0; top: 0;
  display: flex; align-items: center; gap: 8px; padding: 8px 12px 8px 10px; border-radius: 10px;
  background: var(--apm-panes-ink); color: var(--apm-panes-paper); font-size: 13px; font-weight: 600; white-space: nowrap;
  visibility: hidden;
}
.apm-panes__dragimg b { display: grid; place-items: center; min-width: 22px; height: 22px; padding: 0 6px; border-radius: 11px; background: var(--apm-panes-accent); font-size: 12px; }

/* ---------- keyframes ---------- */
@keyframes apm-panes-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes apm-panes-draw { from { stroke-dashoffset: 120; } to { stroke-dashoffset: 0; } }
@keyframes apm-panes-throb { to { box-shadow: inset 0 0 0 1.5px var(--apm-panes-accent), 0 0 0 4px color-mix(in oklch, var(--apm-panes-accent) 18%, transparent); } }

/* ---------- container: rail ---------- */
@container (width < 960px) {
  .apm-panes__app { grid-template-columns: 64px minmax(260px, var(--apm-panes-list)) minmax(0, 1fr); }
  .apm-panes__nav { padding: 14px 8px; }
  .apm-panes__brand span, .apm-panes__compose span, .apm-panes__compose kbd, .apm-panes__navlabel, .apm-panes__storage, .apm-panes__fold > span:not(.apm-panes__n) { display: none; }
  .apm-panes__brand { justify-content: center; padding: 2px 0 6px; }
  .apm-panes__compose { justify-content: center; padding: 10px 0; }
  .apm-panes__fold { justify-content: center; padding: 0; }
  .apm-panes__fold .apm-panes__n { position: absolute; top: 2px; right: 4px; font-size: 10px; }
  .apm-panes__fold .apm-panes__n:not([data-hot]) { display: none; }
  .apm-panes__labels { margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--apm-panes-line); }
  .apm-panes__keys { display: none; }
  .apm-panes__list { grid-template-rows: auto auto minmax(0, 1fr); }
}

/* ---------- container: single pane ---------- */
@container (width < 760px) {
  .apm-panes__app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .apm-panes__list, .apm-panes__reader { grid-area: main; border: 0; }
  .apm-panes__split { display: none; }
  .apm-panes[data-view="list"] .apm-panes__reader { display: none; }
  .apm-panes[data-view="reader"] .apm-panes__list { display: none; }
  .apm-panes__menu, .apm-panes__back { display: grid; }
  .apm-panes__listhead { padding: 12px 12px 8px; }
  .apm-panes__filter { width: min(150px, 44%); }
  .apm-panes__bulk { padding-left: 14px; }
  .apm-panes__rhead { padding: 8px 8px 8px 6px; }
  .apm-panes__reader { animation: apm-panes-push .45s var(--apm-panes-ease) both; }
  .apm-panes__nav {
    position: absolute; z-index: 9; inset: 0 auto 0 0; width: min(280px, 82%);
    grid-template-rows: auto auto minmax(0, 1fr) auto; padding: 16px 12px 14px;
    translate: -105% 0; visibility: hidden;
    transition: translate .45s var(--apm-panes-spring), visibility 0s .45s, box-shadow .3s;
  }
  .apm-panes__brand span, .apm-panes__compose span, .apm-panes__compose kbd, .apm-panes__navlabel, .apm-panes__storage, .apm-panes__fold > span:not(.apm-panes__n) { display: revert; }
  .apm-panes__brand, .apm-panes__compose, .apm-panes__fold { justify-content: flex-start; }
  .apm-panes__compose { padding: 10px 12px; }
  .apm-panes__fold { padding: 0 10px; }
  .apm-panes__fold .apm-panes__n { position: static; font-size: 12px; }
  .apm-panes__fold .apm-panes__n:not([data-hot]) { display: revert; }
  .apm-panes__storage { display: grid; }
  .apm-panes__labels { margin: 0; padding: 0; border: 0; }
  .apm-panes[data-nav] .apm-panes__nav { translate: 0 0; visibility: visible; transition-delay: 0s; box-shadow: 20px 0 50px -20px color-mix(in oklch, var(--apm-panes-ink) 50%, transparent); }
  .apm-panes[data-nav] .apm-panes__scrim { opacity: 1; pointer-events: auto; }
  .apm-panes__sheet { inset: 0; width: auto; border-radius: 0; grid-template-rows: auto auto auto minmax(0, 1fr) auto; }
  .apm-panes__pos { display: none; }
}
@container (width < 440px) {
  .apm-panes__filter { width: 40px; padding: 0; justify-content: center; }
  .apm-panes__filter:has(input:focus), .apm-panes__filter:has(input:not(:placeholder-shown)) { width: 58%; padding: 0 6px 0 9px; justify-content: flex-start; }
  .apm-panes__filter input { width: 0; }
  .apm-panes__filter:has(input:focus) input, .apm-panes__filter:has(input:not(:placeholder-shown)) input { width: 100%; }
  .apm-panes__filter kbd { display: none; }
  .apm-panes__row { --pad: 12px; gap: 2px 10px; }
  .apm-panes__chips { display: none; }
}
@keyframes apm-panes-push { from { opacity: 0; translate: 24px 0; } }

/* ---------- reduced motion: same states, no travel ---------- */
@media (prefers-reduced-motion: reduce) {
  .apm-panes *, .apm-panes *::before, .apm-panes *::after {
    animation-duration: .01ms !important; animation-iteration-count: 1 !important;
    transition-duration: .01ms !important; transition-delay: 0s !important;
  }
  .apm-panes__fold.is-drop { animation: none; }
  .apm-panes__av, .apm-panes__check { transition: none; }
}

