let MSG = [
  { id: 1, box: 'inbox', name: 'Priya Raman', email: 'priya.raman@kestrelhaulage.co', subject: 'Revised pickup window for PO 44817', at: '2026-10-02T09:42', time: '9:42 AM', unread: true, star: false, labels: ['ops'],
    files: [['PO-44817-revised.pdf', '212 KB']],
    body: ['Hi Noor,', 'Our Rotterdam crew can’t make Wednesday after all — the Botlek terminal moved our slot. We can do Thursday 06:00–09:00 instead: same trailer, same driver (Joris).', 'If that works on your side I’ll lock it in and send the signed CMR by noon tomorrow. The revised PO is attached; only the collection window changed.', 'Thanks, Priya'] },
  { id: 2, box: 'inbox', name: 'Ostara Analytics', email: 'billing@ostara-analytics.io', subject: 'Invoice INV-2291 for September — €4,860.00', at: '2026-10-02T09:05', time: '9:05 AM', unread: true, star: false, labels: ['finance'],
    files: [['INV-2291.pdf', '88 KB']],
    body: ['Your September invoice is ready. Payment will be collected by direct debit on 16 October.', { total: true, rows: [['Platform seats (18 × €210)', '€3,780.00'], ['Data retention add-on', '€720.00'], ['Priority support', '€360.00'], ['Total due 16 Oct', '€4,860.00']] }, 'Seat count is taken from active users on 30 September. Reply to this email to query a line.'] },
  { id: 3, box: 'inbox', name: 'Lucas Brandt', email: 'lucas@fernhill.co', subject: 'Dock 3 scanner keeps dropping off Wi-Fi', at: '2026-10-02T08:31', time: '8:31 AM', unread: true, star: true, labels: ['ops'],
    files: [['dock3-ap-spot.jpg', '1.8 MB']],
    body: ['Third time this week. The handheld on Dock 3 loses the network whenever the roller door is fully open — I think the motor housing is shadowing the access point.', 'Logged 41 failed scans between 06:10 and 07:55 this morning. All of them retried fine once the door came down.', 'Can we get Umbra’s technician to move the AP to the column by bay 12? I’ve marked the spot in the photo.'] },
  { id: 4, box: 'inbox', name: 'Ada Okafor', email: 'ada.okafor@fernhill.co', subject: 'Interview loop for Senior Planner — Thursday', at: '2026-10-01T17:12', time: 'Yesterday', unread: false, star: false, labels: ['hiring'],
    body: ['Rafael’s loop is set for Thursday. Each slot is 45 minutes with 15 to write notes before the next one.', { rows: [['10:00', 'Ops walkthrough — Ada'], ['11:00', 'Systems & data — Lucas'], ['13:30', 'Budgeting case — Mei'], ['14:30', 'Debrief — everyone']] }, 'Please submit scorecards before the debrief so we are not anchoring on whoever speaks first.'] },
  { id: 5, box: 'inbox', name: 'Mei Tanaka', email: 'mei.tanaka@fernhill.co', subject: 'Q3 freight spend — draft for review', at: '2026-10-01T15:20', time: 'Yesterday', unread: true, star: false, labels: ['finance'],
    files: [['Q3-freight-spend.xlsx', '1.4 MB']],
