  { id: 6, box: 'inbox', name: 'Brightwater Hotels', email: 'stay@brightwaterhotels.eu', subject: 'Confirmed: Gdańsk, 14–16 Oct · BW-77310', at: '2026-10-01T11:04', time: 'Yesterday', unread: false, star: false, labels: ['travel'],
    body: ['Your booking at Brightwater Granary, Gdańsk is confirmed.', { total: true, rows: [['2 nights × €128', '€256.00'], ['City tax (2 × €3.00)', '€6.00'], ['Charged at check-out', '€262.00']] }, 'Check-in from 15:00. Free cancellation until 12 October, 18:00 local time.'] },
