function paintMenu() {
  $$('.apm-panes__opt', menuEl).forEach((b, i) => {
    b.toggleAttribute('data-active', i === S.menuIdx);
    if (i === S.menuIdx) b.focus({ preventScroll: true });
  });
}
function closeMenu(refocus = true) {
  if (!S.menu) return;
  S.menu = null; menuEl.hidden = true;
  if (refocus) rowsEl.focus({ preventScroll: true });
}
function pickMenu(i) {
  const { ids, opts } = S.menu; const o = opts[i];
  closeMenu();
  if (o.kind === 'box') { if (o.id === 'archive') moveTo(ids, 'archive', 'Archived'); else moveTo(ids, o.id, `Moved to ${o.name}:`); }
  else applyLabel(ids, o.id);
}
menuEl.addEventListener('click', (e) => { const b = e.target.closest('.apm-panes__opt'); if (b) pickMenu(+b.dataset.i); });

/* ---------- compose sheet ---------- */
function openCompose(prefill = {}) {
  sheet.hidden = false;
  sheet.to.value = prefill.to || ''; sheet.subject.value = prefill.subject || ''; sheet.body.value = prefill.body || '';
  (prefill.to ? sheet.body : sheet.to).focus();
}
function closeCompose(save) {
  if (sheet.hidden) return;
  const has = sheet.to.value.trim() || sheet.subject.value.trim() || sheet.body.value.trim();
  if (save && has) {
    snapshot();
    MSG.push({ id: nextId++, box: 'drafts', name: sheet.to.value.trim() || '(no recipient)', email: sheet.to.value.trim(), subject: sheet.subject.value.trim() || '(no subject)', at: '2026-10-02T10:00', time: 'Now', unread: false, star: false, labels: [], body: [sheet.body.value.trim() || ' '] });
    render({ flip: S.box === 'drafts' });
    showToast('Saved to Drafts', true);
  } else if (has) showToast('Draft discarded', false);
  sheet.hidden = true; sheet.reset();
  root.focus({ preventScroll: true });
}
sheet.addEventListener('submit', (e) => {
  e.preventDefault();
  const to = sheet.to.value.trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) {
    sheet.to.focus();
    sheet.to.animate([{ transform: 'translateX(0)' }, { transform: 'translateX(-6px)' }, { transform: 'translateX(5px)' }, { transform: 'translateX(-3px)' }, { transform: 'none' }], { duration: RM.matches ? 1 : 360, easing: 'ease-out' });
    sheet.to.placeholder = 'Add a valid address first';
    return;
  }
  snapshot();
  MSG.push({ id: nextId++, box: 'sent', name: to.split('@')[0].replace(/[._]/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase()), email: to, subject: sheet.subject.value.trim() || '(no subject)', at: '2026-10-02T10:01', time: 'Now', unread: false, star: false, labels: [], body: [sheet.body.value.trim() || ' '] });
  sheet.hidden = true; sheet.reset();
  render({ flip: S.box === 'sent' });
  showToast('Message sent', true);
  root.focus({ preventScroll: true });
});

/* ---------- events ---------- */
nav.addEventListener('click', (e) => {
  const b = e.target.closest('.apm-panes__fold'); if (!b) return;
  if (b.dataset.label) setFolder(S.box, b.dataset.label); else setFolder(b.dataset.box);
});
rowsEl.addEventListener('click', (e) => {
  const row = e.target.closest('.apm-panes__row'); if (!row) return;
  const id = +row.dataset.id;
  if (e.target.closest('[data-act="star"]')) { toggleStar([id]); return; }
  if (e.shiftKey && S.anchor != null) { rangeSel(S.anchor, id); return; }
  if (e.target.closest('.apm-panes__pick') || e.metaKey || e.ctrlKey) { toggleSel(id); return; }
  open(id);
});
root.addEventListener('click', (e) => {
  if (S.menu && !e.target.closest('.apm-panes__menu-pop')) closeMenu(false);
  const a = e.target.closest('[data-act]'); if (!a || a.closest('.apm-panes__rows')) return;
  const act = a.dataset.act;
  const m = byId(S.cur);
  if (act === 'compose') openCompose();
  else if (act === 'nav') root.dataset.nav = '';
  else if (act === 'scrim') delete root.dataset.nav;
  else if (act === 'all') { const list = visible(); const all = list.every((x) => S.sel.has(x.id)); S.sel.clear(); if (!all) list.forEach((x) => S.sel.add(x.id)); renderList(); }
  else if (act === 'archive') archive();
  else if (act === 'trash') trash();
  else if (act === 'read') toggleRead();
  else if (act === 'star') toggleStar();
  else if (act === 'move') openMenu(a);
  else if (act === 'undo') undo();
  else if (act === 'back') { root.dataset.view = 'list'; S.reply = null; rowsEl.focus({ preventScroll: true }); }
  else if (act === 'prev') step(-1);
  else if (act === 'next') step(1);
  else if (act === 'reply' && m) { S.reply = m.id; renderReader(); }
  else if (act === 'cancel-reply') { S.reply = null; renderReader(); }
  else if (act === 'forward' && m) openCompose({ subject: 'Fwd: ' + m.subject, body: '\n\n— Forwarded message from ' + m.name + ' —\n' + m.body.filter((b) => typeof b === 'string').join('\n') });
  else if (act === 'close-compose') closeCompose(true);
  else if (act === 'discard') closeCompose(false);
});
root.addEventListener('submit', (e) => {
  const f = e.target.closest('[data-form="reply"]'); if (!f) return;
  e.preventDefault();
  const text = f.text.value.trim(); if (!text) { f.text.focus(); return; }
  const m = byId(S.cur);
  (m.replies = m.replies || []).forEach((r) => { r.fresh = false; });
  m.replies.push({ text, time: 'just now', fresh: true });
  MSG.push({ id: nextId++, box: 'sent', name: m.name, email: m.email, subject: 'Re: ' + m.subject.replace(/^Re:\s*/, ''), at: '2026-10-02T10:02', time: 'Now', unread: false, star: false, labels: [...m.labels], body: [text] });
  S.reply = null;
  render();
  showToast('Reply sent to ' + m.name.split(' ')[0], false);
  rowsEl.focus({ preventScroll: true });
});
filterIn.addEventListener('input', () => { S.filter = filterIn.value; S.sel.clear(); renderList(); renderReader(); });

/* HTML5 drag and drop: rows onto folders and labels, with a counted drag image. */
let dragIds = null;
rowsEl.addEventListener('dragstart', (e) => {
  const row = e.target.closest('.apm-panes__row'); if (!row) return;
  const id = +row.dataset.id;
  dragIds = S.sel.has(id) ? [...S.sel] : [id];
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', dragIds.map((x) => byId(x).subject).join('\n'));
  dragImg.innerHTML = `<b>${dragIds.length}</b>${dragIds.length === 1 ? esc(byId(id).subject.slice(0, 38)) : dragIds.length + ' conversations'}`;
  dragImg.style.visibility = 'visible';
  e.dataTransfer.setDragImage(dragImg, 16, 18);
  setTimeout(() => { dragImg.style.visibility = 'hidden'; });
  dragIds.forEach((x) => { const r = root.querySelector('#' + oid(x)); if (r) r.classList.add('is-dragging'); });
});
rowsEl.addEventListener('dragend', () => { dragIds = null; $$('.is-dragging, .is-drop').forEach((el) => el.classList.remove('is-dragging', 'is-drop')); });
const dropOK = (b) => b && dragIds && (b.dataset.label || ['inbox', 'archive', 'trash', 'starred'].includes(b.dataset.box)) && b.getAttribute('aria-current') !== 'true';
nav.addEventListener('dragover', (e) => {
  const b = e.target.closest('.apm-panes__fold');
  if (!dropOK(b)) return;
  e.preventDefault(); e.dataTransfer.dropEffect = 'move';
  $$('.is-drop', nav).forEach((x) => x !== b && x.classList.remove('is-drop'));
  b.classList.add('is-drop');
});
nav.addEventListener('dragleave', (e) => { const b = e.target.closest('.apm-panes__fold'); if (b && !b.contains(e.relatedTarget)) b.classList.remove('is-drop'); });
nav.addEventListener('drop', (e) => {
  const b = e.target.closest('.apm-panes__fold');
  if (!dropOK(b)) return;
  e.preventDefault();
  const ids = dragIds; dragIds = null;
  if (b.dataset.label) applyLabel(ids, b.dataset.label);
  else if (b.dataset.box === 'starred') { snapshot(); ids.forEach((id) => { byId(id).star = true; }); render(); showToast(`Starred ${ids.length}`, true); }
  else if (b.dataset.box === 'archive') moveTo(ids, 'archive', 'Archived');
  else moveTo(ids, b.dataset.box, `Moved to ${b.dataset.box[0].toUpperCase() + b.dataset.box.slice(1)}:`);
});

/* Resizable list pane: pointer drag, arrow keys, double-click to reset. */
function setListW(w) {
  const max = Math.max(300, Math.min(520, root.clientWidth - 220 - 340));
  w = Math.round(Math.max(280, Math.min(max, w)));
  root.style.setProperty('--apm-panes-list', w + 'px');
  split.setAttribute('aria-valuenow', w);
  split.setAttribute('aria-valuemax', max);
}
split.addEventListener('pointerdown', (e) => {
  e.preventDefault();
  split.setPointerCapture(e.pointerId);
  split.classList.add('is-active');
  const left = listEl.getBoundingClientRect().left;
  const mv = (ev) => setListW(ev.clientX - left);
  const up = () => { split.classList.remove('is-active'); split.removeEventListener('pointermove', mv); split.removeEventListener('pointerup', up); split.removeEventListener('pointercancel', up); };
  split.addEventListener('pointermove', mv);
  split.addEventListener('pointerup', up);
  split.addEventListener('pointercancel', up);
});
split.addEventListener('dblclick', () => setListW(360));
split.addEventListener('keydown', (e) => {
  const w = listEl.getBoundingClientRect().width;
  const d = { ArrowLeft: -16, ArrowRight: 16 }[e.key];
  if (d) setListW(w + d * (e.shiftKey ? 3 : 1));
  else if (e.key === 'Home') setListW(280);
  else if (e.key === 'End') setListW(9999);
  else return;
  e.preventDefault(); e.stopPropagation();
});

/* Keyboard: the same verbs as the toolbar, shown in titles and the footer. */
root.addEventListener('keydown', (e) => {
  if (e.defaultPrevented) return;
  const t = e.target;
  const typing = t.closest('input, textarea, [contenteditable="true"]');
  if (S.menu) {
    const n = S.menu.opts.length;
    if (e.key === 'ArrowDown') { S.menuIdx = (S.menuIdx + 1) % n; paintMenu(); }
    else if (e.key === 'ArrowUp') { S.menuIdx = (S.menuIdx - 1 + n) % n; paintMenu(); }
    else if (e.key === 'Home') { S.menuIdx = 0; paintMenu(); }
    else if (e.key === 'End') { S.menuIdx = n - 1; paintMenu(); }
    else if (e.key === 'Enter' || e.key === ' ') pickMenu(S.menuIdx);
    else if (e.key === 'Escape' || e.key === 'Tab') closeMenu();
    else return;
    e.preventDefault(); return;
  }
  if (e.key === 'Escape') {
    if (!sheet.hidden) closeCompose(true);
    else if (root.dataset.nav != null) delete root.dataset.nav;
    else if (S.reply != null) { S.reply = null; renderReader(); rowsEl.focus({ preventScroll: true }); }
    else if (typing === filterIn && filterIn.value) { filterIn.value = ''; S.filter = ''; renderList(); renderReader(); }
    else if (narrow() && root.dataset.view === 'reader') { root.dataset.view = 'list'; rowsEl.focus({ preventScroll: true }); }
    else if (S.sel.size) { S.sel.clear(); renderList(); }
    else return;
    e.preventDefault(); return;
  }
  if (typing) {
    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { const f = t.closest('form'); if (f) { e.preventDefault(); f.requestSubmit(); } }
    else if (t === filterIn && (e.key === 'ArrowDown' || e.key === 'Enter')) { e.preventDefault(); rowsEl.focus(); if (S.cur == null) step(0); }
    return;
  }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key;
  if ((k === 'Enter' || k === ' ') && t !== rowsEl && t !== root) return;
  const act = {
    j: () => step(1), ArrowDown: () => step(1), k: () => step(-1), ArrowUp: () => step(-1),
    o: () => S.cur != null && open(S.cur), Enter: () => S.cur != null && open(S.cur),
    x: () => S.cur != null && toggleSel(S.cur), s: () => toggleStar(), e: () => archive(), '#': () => trash(),
    U: () => toggleRead(), v: () => openMenu(), z: () => undo(), c: () => openCompose(), '/': () => filterIn.focus(),
    r: () => { if (S.cur != null) { if (narrow()) root.dataset.view = 'reader'; S.reply = S.cur; renderReader(); } },
    f: () => { const m = byId(S.cur); if (m) $('[data-act="forward"]', reader)?.click(); },
  }[k];
  if (!act) return;
  e.preventDefault();
  act();
});

new ResizeObserver(() => { if (!root.isConnected) return; movePill(); if (!narrow()) root.dataset.view = 'list'; }).observe(root);

render();
enterList();

