/* Collapsing conversation reader. Re-theme with --apm-convo-bg, -ink, -accent (and -h). */
.apm-convo {
  --apm-convo-bg: oklch(0.2 0.022 172);
  --apm-convo-ink: oklch(0.94 0.014 95);
  --apm-convo-accent: oklch(0.82 0.12 82);

  --apm-convo-side: color-mix(in oklch, var(--apm-convo-bg) 88%, black);
  --apm-convo-card: color-mix(in oklch, var(--apm-convo-ink) 5%, var(--apm-convo-bg));
  --apm-convo-line: color-mix(in oklch, var(--apm-convo-ink) 10%, transparent);
  --apm-convo-line2: color-mix(in oklch, var(--apm-convo-ink) 18%, transparent);
  --apm-convo-muted: color-mix(in oklch, var(--apm-convo-ink) 60%, var(--apm-convo-bg));
  --apm-convo-faint: color-mix(in oklch, var(--apm-convo-ink) 38%, var(--apm-convo-bg));
  --apm-convo-hover: color-mix(in oklch, var(--apm-convo-ink) 6%, transparent);
  --apm-convo-glow: color-mix(in oklch, var(--apm-convo-accent) 16%, transparent);
  --apm-convo-ease: cubic-bezier(.22, .9, .24, 1);
  --apm-convo-out: cubic-bezier(.5, 0, .75, 0);
  --apm-convo-spring: linear(0, 0.05 3%, 0.22 7%, 0.58 14%, 0.85 21%, 1.01 29%, 1.05 35%, 1.04 43%, 1.01 56%, 0.996 72%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apm-convo-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--apm-convo-bg);
  color: var(--apm-convo-ink);
  font: 400 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  outline: none;
}
:where(.apm-convo) *, :where(.apm-convo) *::before, :where(.apm-convo) *::after { box-sizing: border-box; }
:where(.apm-convo) :is(button, textarea, input) { font: inherit; color: inherit; }
:where(.apm-convo) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apm-convo) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.apm-convo [hidden] { display: none !important; }
:where(.apm-convo) :focus-visible { outline: 2px solid var(--apm-convo-accent); outline-offset: 2px; }
:where(.apm-convo) kbd {
  display: inline-block; min-width: 18px; padding: 3px 5px 2px; border-radius: 4px; text-align: center;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace;
  background: color-mix(in oklch, var(--apm-convo-ink) 8%, transparent);
  box-shadow: inset 0 -1px 0 var(--apm-convo-line);
  color: var(--apm-convo-muted);
}

.apm-convo__app {
  display: grid;
  height: 100%;
  grid-template-columns: minmax(280px, 330px) minmax(0, 1fr);
  grid-template-areas: "side pane";
}
.apm-convo__side { grid-area: side; }
.apm-convo__pane { grid-area: pane; }

/* ---------- thread list ---------- */
.apm-convo__side {
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0;
  background: var(--apm-convo-side);
  border-right: 1px solid var(--apm-convo-line);
}
.apm-convo__sidehead { display: grid; gap: 14px; padding: 18px 16px 12px; }
.apm-convo__brand { display: flex; align-items: center; gap: 9px; }
.apm-convo__brand svg { width: 22px; height: 22px; color: var(--apm-convo-accent); }
.apm-convo__brand b { font-weight: 680; letter-spacing: -0.01em; }
.apm-convo__brand span { font-size: 12px; color: var(--apm-convo-faint); margin-left: auto; letter-spacing: .02em; }
.apm-convo__seg {
  position: relative; display: grid; grid-template-columns: repeat(3, 1fr);
  padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--apm-convo-ink) 6%, transparent);
}
.apm-convo__seg button { position: relative; z-index: 1; height: 28px; border-radius: 7px; font-size: 12.5px; font-weight: 550; color: var(--apm-convo-muted); transition: color .2s; }
.apm-convo__seg button[aria-selected="true"] { color: var(--apm-convo-bg); }
.apm-convo__segpill {
  position: absolute; top: 3px; bottom: 3px; left: 3px; width: calc((100% - 6px) / 3);
  border-radius: 7px; background: var(--apm-convo-accent);
  translate: calc(var(--seg, 0) * 100%) 0;
  transition: translate .5s var(--apm-convo-spring);
  box-shadow: 0 4px 14px -6px var(--apm-convo-accent);
}
.apm-convo__threads { list-style: none; margin: 0; padding: 4px 8px 10px; overflow: auto; min-height: 0; outline: none; scrollbar-width: thin; overscroll-behavior: contain; }
.apm-convo__thread {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 10px;
  padding: 12px 12px 12px 14px; border-radius: 12px; cursor: pointer;
  transition: background-color .2s;
}
.apm-convo__thread:hover { background: var(--apm-convo-hover); }
.apm-convo__thread[data-current] { background: color-mix(in oklch, var(--apm-convo-ink) 9%, transparent); }
.apm-convo__threads:focus-visible .apm-convo__thread[data-current] { box-shadow: inset 0 0 0 2px var(--apm-convo-accent); }
.apm-convo__thread[data-unread]::before {
  content: ""; position: absolute; left: 4px; top: 18px; width: 6px; height: 6px; border-radius: 50%;
  background: var(--apm-convo-accent); box-shadow: 0 0 0 3px var(--apm-convo-glow);
}
.apm-convo__tpeople { font-size: 12.5px; color: var(--apm-convo-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-convo__tmeta { display: flex; align-items: center; gap: 7px; font-size: 11.5px; color: var(--apm-convo-faint); font-variant-numeric: tabular-nums; white-space: nowrap; }
.apm-convo__tcount { min-width: 20px; height: 18px; padding: 0 6px; display: grid; place-items: center; border-radius: 9px; font-size: 11px; font-weight: 650; background: color-mix(in oklch, var(--apm-convo-ink) 9%, transparent); color: var(--apm-convo-muted); }
.apm-convo__tsubj { grid-column: 1 / -1; font-weight: 600; font-size: 14px; letter-spacing: -0.005em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-convo__tsnip { grid-column: 1 / -1; font-size: 12.5px; color: var(--apm-convo-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-convo__thread[data-unread] .apm-convo__tsubj { color: var(--apm-convo-ink); font-weight: 700; }
.apm-convo__thread[data-unread] .apm-convo__tpeople { color: var(--apm-convo-ink); }
.apm-convo__thread[data-unread] .apm-convo__tcount { background: var(--apm-convo-accent); color: var(--apm-convo-bg); }
.apm-convo__threads[data-enter] .apm-convo__thread { animation: apm-convo-in .55s var(--apm-convo-ease) both; animation-delay: calc(var(--i) * 40ms); }
.apm-convo__none { padding: 40px 18px; text-align: center; color: var(--apm-convo-faint); font-size: 13px; text-wrap: balance; }
.apm-convo__legend { display: flex; flex-wrap: wrap; gap: 6px 12px; padding: 10px 16px 12px; border-top: 1px solid var(--apm-convo-line); font-size: 11.5px; color: var(--apm-convo-faint); }
.apm-convo__legend kbd { margin-right: 2px; }

/* ---------- conversation ---------- */
.apm-convo__pane { position: relative; min-width: 0; min-height: 0; view-transition-name: apm-convo-pane; }
.apm-convo__scroll { position: absolute; inset: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scroll-padding-top: 64px; }
.apm-convo__mini { position: sticky; top: 0; height: 0; z-index: 5; }
.apm-convo__minibar {
  position: absolute; inset: 0 0 auto 0; height: 54px;
  display: flex; align-items: center; gap: 12px; padding: 0 clamp(16px, 3cqi, 36px);
  background: color-mix(in oklch, var(--apm-convo-bg) 82%, transparent);
  backdrop-filter: blur(14px) saturate(1.3);
  border-bottom: 1px solid var(--apm-convo-line);
  opacity: 0; translate: 0 -8px; pointer-events: none;
  transition: opacity .25s, translate .35s var(--apm-convo-ease);
}
.apm-convo__minibar b { font-weight: 640; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.apm-convo__minibar span { font-size: 12px; color: var(--apm-convo-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }
.apm-convo__scroll[data-scrolled] .apm-convo__minibar { opacity: 1; translate: 0 0; pointer-events: auto; }
@supports (animation-timeline: scroll()) {
  .apm-convo__minibar {
    transition: none;
    animation: apm-convo-condense linear both;
    animation-timeline: scroll(nearest block);
    animation-range: 90px 150px;
  }
  .apm-convo__head { animation: apm-convo-recede linear both; animation-timeline: scroll(nearest block); animation-range: 0 150px; }
}

.apm-convo__head { padding: clamp(20px, 4cqi, 40px) clamp(16px, 4cqi, 48px) 14px; display: grid; gap: 12px; transform-origin: 0 0; }
.apm-convo__back { display: none; align-items: center; gap: 6px; width: fit-content; height: 30px; padding: 0 10px 0 4px; margin-left: -6px; border-radius: 8px; font-size: 13px; color: var(--apm-convo-muted); }
.apm-convo__back:hover { background: var(--apm-convo-hover); color: var(--apm-convo-ink); }
.apm-convo__eyebrow { margin: 0; display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--apm-convo-accent); font-variant-numeric: tabular-nums; }
.apm-convo__eyebrow span + span { color: var(--apm-convo-faint); }
.apm-convo__subject { margin: 0; font-size: clamp(1.35rem, .95rem + 1.7cqi, 2.15rem); line-height: 1.12; font-weight: 660; letter-spacing: -0.028em; text-wrap: balance; max-width: 26ch; }
.apm-convo__people { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.apm-convo__stack { display: flex; }
.apm-convo__stack .apm-convo__av { width: 28px; height: 28px; font-size: 10.5px; box-shadow: 0 0 0 2.5px var(--apm-convo-bg); }
.apm-convo__stack .apm-convo__av + .apm-convo__av { margin-left: -7px; }
.apm-convo__names { font-size: 13px; color: var(--apm-convo-muted); text-wrap: pretty; }
.apm-convo__tools { display: flex; gap: 6px; flex-wrap: wrap; }
.apm-convo__tool {
  display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 10px; border-radius: 8px;
  font-size: 12.5px; color: var(--apm-convo-muted);
  box-shadow: inset 0 0 0 1px var(--apm-convo-line);
  transition: background-color .15s, color .15s, box-shadow .15s;
}
.apm-convo__tool:hover { background: var(--apm-convo-hover); color: var(--apm-convo-ink); box-shadow: inset 0 0 0 1px var(--apm-convo-line2); }
.apm-convo__tool svg { width: 15px; height: 15px; }

/* the rail */
.apm-convo__msgs { position: relative; list-style: none; margin: 0; padding: 10px clamp(16px, 4cqi, 48px) 18px; display: grid; gap: 8px; }
.apm-convo__msgs::before {
  content: ""; position: absolute; top: 28px; bottom: 40px; left: calc(clamp(16px, 4cqi, 48px) + 17px); width: 1.5px;
  background: linear-gradient(to bottom, var(--apm-convo-line2), var(--apm-convo-line) 80%, transparent);
  transform-origin: top; animation: apm-convo-rail .9s var(--apm-convo-ease) both;
}
.apm-convo__msg { position: relative; display: grid; grid-template-columns: 36px minmax(0, 1fr); gap: 14px; align-items: start; }
.apm-convo__av {
  width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; flex: none;
  font-size: 12px; font-weight: 700; letter-spacing: .02em;
  background: oklch(0.42 0.09 var(--h)); color: oklch(0.95 0.04 var(--h));
  box-shadow: 0 0 0 4px var(--apm-convo-bg);
  position: relative; z-index: 1;
}
.apm-convo__msg > .apm-convo__av { cursor: pointer; transition: scale .4s var(--apm-convo-spring); }
.apm-convo__msg:not([data-open]) > .apm-convo__av { scale: .78; }
.apm-convo__card {
  min-width: 0; border-radius: 14px;
  background: transparent; box-shadow: inset 0 0 0 1px transparent;
  transition: background-color .35s var(--apm-convo-ease), box-shadow .35s var(--apm-convo-ease);
}
.apm-convo__msg[data-open] .apm-convo__card { background: var(--apm-convo-card); box-shadow: inset 0 0 0 1px var(--apm-convo-line); }
.apm-convo__msg[data-open][data-latest] .apm-convo__card { box-shadow: inset 0 0 0 1px var(--apm-convo-line2), inset 3px 0 0 var(--apm-convo-accent); }
.apm-convo__mhead {
  width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 10px;
  padding: 7px 14px; border-radius: 12px; text-align: left; min-height: 36px;
  transition: background-color .2s, padding .35s var(--apm-convo-ease);
}
.apm-convo__msg:not([data-open]) .apm-convo__mhead:hover { background: var(--apm-convo-hover); }
.apm-convo__msg[data-open] .apm-convo__mhead { padding: 14px 18px 4px; }
.apm-convo__mhead b { font-weight: 640; white-space: nowrap; }
.apm-convo__msg[data-unread] .apm-convo__mhead b::after { content: ""; display: inline-block; width: 6px; height: 6px; margin-left: 8px; border-radius: 50%; background: var(--apm-convo-accent); vertical-align: middle; }
.apm-convo__swap { display: grid; min-width: 0; }
.apm-convo__swap > * { grid-area: 1 / 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; transition: opacity .3s var(--apm-convo-ease), translate .4s var(--apm-convo-ease); }
.apm-convo__peek { color: var(--apm-convo-faint); }
.apm-convo__to { color: var(--apm-convo-faint); opacity: 0; translate: 0 4px; }
.apm-convo__msg[data-open] .apm-convo__peek { opacity: 0; translate: 0 -4px; }
.apm-convo__msg[data-open] .apm-convo__to { opacity: 1; translate: 0 0; }
.apm-convo__mhead time { font-size: 12px; color: var(--apm-convo-faint); font-variant-numeric: tabular-nums; white-space: nowrap; }

.apm-convo__fold { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .5s var(--apm-convo-ease); }
.apm-convo__msg[data-open] .apm-convo__fold { grid-template-rows: 1fr; }
.apm-convo__inner { min-height: 0; overflow: hidden; }
.apm-convo__body {
  padding: 6px 18px 16px; opacity: 0; translate: 0 -6px;
  transition: opacity .3s var(--apm-convo-ease), translate .45s var(--apm-convo-ease);
}
.apm-convo__msg[data-open] .apm-convo__body { opacity: 1; translate: 0 0; transition-delay: .08s; }
.apm-convo__body p { margin: 0 0 .8em; max-width: 66ch; text-wrap: pretty; font-size: 14.5px; line-height: 1.62; }
.apm-convo__body p:last-of-type { margin-bottom: 0; }
.apm-convo__qtoggle {
  margin-top: 10px; display: inline-grid; place-items: center; width: 30px; height: 18px; border-radius: 9px;
  background: color-mix(in oklch, var(--apm-convo-ink) 10%, transparent); color: var(--apm-convo-muted);
  font: 700 12px/1 ui-monospace, Menlo, monospace; letter-spacing: .1em;
  transition: background-color .15s;
}
.apm-convo__qtoggle:hover { background: color-mix(in oklch, var(--apm-convo-ink) 18%, transparent); }
.apm-convo__quote { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--apm-convo-ease); }
.apm-convo__quote > div { min-height: 0; overflow: hidden; }
.apm-convo__quote blockquote { margin: 10px 0 0; padding: 2px 0 2px 14px; border-left: 2px solid var(--apm-convo-line2); color: var(--apm-convo-faint); font-size: 13px; line-height: 1.55; }
.apm-convo__quote blockquote small { display: block; margin-bottom: 2px; font-size: 11.5px; }
.apm-convo__msg[data-quote] .apm-convo__quote { grid-template-rows: 1fr; }
.apm-convo__files { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; }
.apm-convo__file { display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 12px 0 8px; border-radius: 9px; font-size: 12.5px; box-shadow: inset 0 0 0 1px var(--apm-convo-line2); }
.apm-convo__file i { font: 700 9px/1 ui-monospace, Menlo, monospace; font-style: normal; padding: 4px 5px; border-radius: 4px; background: color-mix(in oklch, var(--apm-convo-accent) 22%, transparent); color: var(--apm-convo-accent); }
.apm-convo__file small { color: var(--apm-convo-faint); font-variant-numeric: tabular-nums; }
.apm-convo__macts { display: flex; gap: 6px; margin-top: 14px; }

/* the fold-away stack of older messages */
.apm-convo__more { position: relative; display: grid; grid-template-columns: 36px minmax(0, 1fr); grid-template-rows: 36px auto; column-gap: 14px; row-gap: 0; transition: grid-template-rows .5s var(--apm-convo-ease); }
.apm-convo__more[data-open] { grid-template-rows: 0px auto; }
.apm-convo__more > .apm-convo__knot {
  grid-row: 1; width: 36px; height: 36px; display: grid; place-items: center; border-radius: 50%;
  background: var(--apm-convo-bg); box-shadow: inset 0 0 0 1.5px var(--apm-convo-line2), 0 0 0 4px var(--apm-convo-bg);
  font-size: 11.5px; font-weight: 700; color: var(--apm-convo-muted); font-variant-numeric: tabular-nums;
  position: relative; z-index: 1;
  transition: scale .45s var(--apm-convo-spring), opacity .3s;
}
.apm-convo__pill {
  grid-row: 1; grid-column: 2; justify-self: start; display: inline-flex; align-items: center; gap: 10px;
  height: 36px; padding: 0 14px 0 8px; border-radius: 18px;
  background: color-mix(in oklch, var(--apm-convo-ink) 6%, transparent);
  box-shadow: inset 0 0 0 1px var(--apm-convo-line);
  font-size: 13px; font-weight: 550; color: var(--apm-convo-muted);
  transition: background-color .2s, color .2s, translate .35s var(--apm-convo-spring), opacity .25s, scale .35s var(--apm-convo-ease);
}
.apm-convo__pill:hover { background: color-mix(in oklch, var(--apm-convo-ink) 11%, transparent); color: var(--apm-convo-ink); translate: 0 -1px; }
.apm-convo__pill .apm-convo__stack .apm-convo__av { width: 22px; height: 22px; font-size: 8.5px; box-shadow: 0 0 0 2px var(--apm-convo-bg); }
.apm-convo__pill .apm-convo__stack .apm-convo__av + .apm-convo__av { margin-left: -6px; }
.apm-convo__pill svg { width: 15px; height: 15px; transition: rotate .4s var(--apm-convo-spring); }
.apm-convo__hidden { grid-column: 1 / -1; grid-row: 2; display: grid; grid-template-rows: 0fr; transition: grid-template-rows .6s var(--apm-convo-ease); }
.apm-convo__hidden > ol { min-height: 0; overflow: hidden; list-style: none; margin: 0; padding: 4px 0; display: grid; gap: 8px; }
.apm-convo__hidden .apm-convo__msg { opacity: 0; translate: 0 -10px; filter: blur(2px); transition: opacity .35s var(--apm-convo-ease), translate .5s var(--apm-convo-spring), filter .35s; }
.apm-convo__more[data-open] .apm-convo__hidden { grid-template-rows: 1fr; }
.apm-convo__more[data-open] .apm-convo__hidden .apm-convo__msg { opacity: 1; translate: 0 0; filter: none; transition-delay: calc(var(--i) * 45ms + 60ms); }
.apm-convo__more[data-open] > .apm-convo__knot { scale: 0; opacity: 0; }
.apm-convo__more[data-open] > .apm-convo__pill { opacity: 0; scale: .9; pointer-events: none; position: absolute; }

/* fresh messages arrive from below */
.apm-convo__msg[data-fresh] {
  transition: opacity .5s var(--apm-convo-ease), translate .7s var(--apm-convo-spring);
  @starting-style { opacity: 0; translate: 0 18px; }
}
.apm-convo__typing { display: grid; grid-template-columns: 36px auto; gap: 14px; align-items: center; color: var(--apm-convo-faint); font-size: 12.5px;
  transition: opacity .3s, translate .4s var(--apm-convo-ease);
  @starting-style { opacity: 0; translate: 0 8px; }
}
.apm-convo__typing .apm-convo__av { scale: .78; }
.apm-convo__dots { display: inline-flex; gap: 4px; align-items: center; height: 28px; padding: 0 12px; border-radius: 14px; background: var(--apm-convo-card); box-shadow: inset 0 0 0 1px var(--apm-convo-line); }
.apm-convo__dots i { width: 5px; height: 5px; border-radius: 50%; background: var(--apm-convo-muted); animation: apm-convo-dot 1.1s var(--apm-convo-ease) infinite; animation-delay: calc(var(--i) * 140ms); }

/* ---------- composer ---------- */
.apm-convo__composer {
  position: sticky; bottom: 0; z-index: 4;
  padding: 26px clamp(16px, 4cqi, 48px) 16px calc(clamp(16px, 4cqi, 48px) + 50px);
  background: linear-gradient(to bottom, transparent, var(--apm-convo-bg) 26px);
}
.apm-convo__cbox {
  display: grid; grid-template-rows: auto 0fr; border-radius: 14px;
  background: var(--apm-convo-card); box-shadow: inset 0 0 0 1px var(--apm-convo-line2), 0 18px 40px -20px black;
  transition: grid-template-rows .5s var(--apm-convo-ease), box-shadow .3s;
}
.apm-convo__composer[data-open] .apm-convo__cbox { grid-template-rows: auto 1fr; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apm-convo-accent) 50%, transparent), 0 24px 50px -22px black; }
.apm-convo__ctop { display: flex; align-items: center; gap: 10px; min-height: 46px; padding: 6px 8px 6px 14px; }
.apm-convo__cprompt { flex: 1; text-align: left; color: var(--apm-convo-faint); font-size: 13.5px; height: 34px; }
.apm-convo__composer[data-open] .apm-convo__cprompt { display: none; }
.apm-convo__mode { display: none; padding: 2px; border-radius: 8px; background: color-mix(in oklch, var(--apm-convo-ink) 7%, transparent); }
.apm-convo__composer[data-open] .apm-convo__mode { display: inline-flex; }
.apm-convo__mode button { height: 26px; padding: 0 10px; border-radius: 6px; font-size: 12px; color: var(--apm-convo-muted); transition: background-color .2s, color .2s; }
.apm-convo__mode button[aria-pressed="true"] { background: var(--apm-convo-ink); color: var(--apm-convo-bg); }
.apm-convo__rcpt { display: none; flex: 1; min-width: 0; gap: 4px; flex-wrap: wrap; font-size: 12px; color: var(--apm-convo-faint); }
.apm-convo__composer[data-open] .apm-convo__rcpt { display: flex; }
.apm-convo__rcpt span { padding: 2px 8px; border-radius: 10px; background: color-mix(in oklch, var(--apm-convo-ink) 7%, transparent); color: var(--apm-convo-muted); white-space: nowrap;
  transition: opacity .3s, scale .35s var(--apm-convo-spring);
  @starting-style { opacity: 0; scale: .7; }
}
.apm-convo__cmore { min-height: 0; overflow: hidden; }
.apm-convo__cmore textarea { display: block; width: 100%; min-height: 96px; resize: none; border: 0; outline: none; background: none; padding: 4px 16px 8px; font-size: 14px; line-height: 1.55; }
.apm-convo__cfoot { display: flex; align-items: center; gap: 8px; padding: 0 10px 10px 16px; font-size: 12px; color: var(--apm-convo-faint); }
.apm-convo__send {
  margin-left: auto; display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 14px; border-radius: 9px;
  background: var(--apm-convo-accent); color: var(--apm-convo-bg); font-weight: 650; font-size: 13px;
  transition: transform .3s var(--apm-convo-spring), filter .2s;
}
.apm-convo__send:hover { filter: brightness(1.07); }
.apm-convo__send:active { transform: scale(.96); }
.apm-convo__send kbd { background: color-mix(in oklch, var(--apm-convo-bg) 18%, transparent); color: inherit; box-shadow: none; }
.apm-convo__icon { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--apm-convo-muted); transition: background-color .15s, color .15s; }
.apm-convo__icon:hover { background: var(--apm-convo-hover); color: var(--apm-convo-ink); }

.apm-convo__toast {
  position: absolute; z-index: 30; left: 50%; top: 14px; display: flex; align-items: center; gap: 12px;
  padding: 8px 8px 8px 16px; border-radius: 12px; white-space: nowrap; font-size: 13px;
  background: var(--apm-convo-ink); color: var(--apm-convo-bg);
  box-shadow: 0 18px 40px -16px black;
  translate: -50% -160%; opacity: 0; pointer-events: none;
  transition: translate .5s var(--apm-convo-spring), opacity .25s;
}
.apm-convo__toast[data-show] { translate: -50% 0; opacity: 1; pointer-events: auto; }
.apm-convo__toast button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px 0 10px; border-radius: 7px; font-weight: 650; color: oklch(0.45 0.1 172); }
.apm-convo__toast button[hidden] { display: none; }
.apm-convo__toast kbd { background: color-mix(in oklch, var(--apm-convo-bg) 10%, transparent); color: inherit; }

/* scoped view transition (Element.startViewTransition) */
.apm-convo::view-transition-old(apm-convo-pane) { animation: apm-convo-vt-out .18s var(--apm-convo-out) both; }
.apm-convo::view-transition-new(apm-convo-pane) { animation: apm-convo-vt-in .42s var(--apm-convo-ease) both; }

@keyframes apm-convo-in { from { opacity: 0; translate: -10px 0; } }
@keyframes apm-convo-rail { from { scale: 1 0; } }
@keyframes apm-convo-dot { 0%, 60%, 100% { translate: 0 0; opacity: .45; } 30% { translate: 0 -4px; opacity: 1; } }
@keyframes apm-convo-condense { from { opacity: 0; translate: 0 -8px; pointer-events: none; } to { opacity: 1; translate: 0 0; pointer-events: auto; } }
@keyframes apm-convo-recede { to { opacity: .25; scale: .985; filter: blur(1.5px); } }
@keyframes apm-convo-vt-out { to { opacity: 0; translate: 0 -6px; } }
@keyframes apm-convo-vt-in { from { opacity: 0; translate: 0 14px; } }
@keyframes apm-convo-slide { from { opacity: 0; translate: 28px 0; } }

@container (width < 960px) {
  .apm-convo__app { grid-template-columns: minmax(240px, 280px) minmax(0, 1fr); }
  .apm-convo__legend { display: none; }
  .apm-convo__side { grid-template-rows: auto minmax(0, 1fr); }
  .apm-convo__tools .apm-convo__tool span { display: none; }
}
@container (width < 760px) {
  .apm-convo__app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .apm-convo__side, .apm-convo__pane { grid-area: main; border: 0; }
  .apm-convo[data-view="list"] .apm-convo__pane { display: none; }
  .apm-convo[data-view="thread"] .apm-convo__side { display: none; }
  .apm-convo[data-view="thread"] .apm-convo__pane { animation: apm-convo-slide .45s var(--apm-convo-ease) both; }
  .apm-convo__back { display: inline-flex; }
  .apm-convo__composer { padding-left: clamp(16px, 4cqi, 48px); }
}
@container (width < 440px) {
  .apm-convo__msg, .apm-convo__more { grid-template-columns: 28px minmax(0, 1fr); gap: 10px; }
  .apm-convo__av { width: 28px; height: 28px; font-size: 10px; }
  .apm-convo__more > .apm-convo__knot { width: 28px; height: 28px; }
  .apm-convo__msgs::before { left: calc(clamp(16px, 4cqi, 48px) + 13px); }
  .apm-convo__mhead { grid-template-columns: auto minmax(0, 1fr); }
  .apm-convo__mhead time { display: none; }
  .apm-convo__msg[data-open] .apm-convo__mhead { padding: 12px 14px 4px; }
  .apm-convo__body { padding: 6px 14px 14px; }
  .apm-convo__pill .apm-convo__stack { display: none; }
  .apm-convo__mode button { padding: 0 7px; }
}

@media (prefers-reduced-motion: reduce) {
  .apm-convo *, .apm-convo *::before, .apm-convo *::after {
    transition-duration: .01ms !important; transition-delay: 0s !important;
    animation-duration: .01ms !important; animation-iteration-count: 1 !important;
  }
  .apm-convo__minibar, .apm-convo__head { animation: none !important; }
  .apm-convo__dots i { animation: none !important; opacity: .7; }
}

