/* Patch fold state onto the DOM so CSS can transition between the two layouts. */
function sync() {
  const t = byId(S.cur); if (!t) return;
  $$('.apm-convo__msg', pane).forEach((el) => {
    const m = t.msgs[+el.dataset.i];
    el.toggleAttribute('data-open', !!m.open);
    el.toggleAttribute('data-quote', !!m.quoteOpen);
    $('.apm-convo__mhead', el).setAttribute('aria-expanded', !!m.open);
    const q = $('.apm-convo__qtoggle', el); if (q) q.setAttribute('aria-expanded', !!m.quoteOpen);
  });
  $$('.apm-convo__fold', pane).forEach((f) => { f.inert = !f.closest('.apm-convo__msg').hasAttribute('data-open'); });
  const more = $('.apm-convo__more', pane);
  if (more) {
    more.toggleAttribute('data-open', t.moreOpen);
    const pill = $('.apm-convo__pill', more);
    pill.setAttribute('aria-expanded', t.moreOpen); pill.inert = t.moreOpen;
    $('.apm-convo__hidden', more).inert = !t.moreOpen;
  }
