function openThread(id, opts = {}) {
  const t = byId(id); if (!t) return;
  const go = () => {
    S.cur = id; S.composer = false; S.draft = ''; S.replyTo = null;
    if (narrow() && opts.show !== false) root.dataset.view = 'thread';
    renderList(); renderThread();
    t.msgs.forEach((m) => { m.unread = false; });
    setTimeout(() => { if (!root.isConnected) return; renderList(); }, 1600);
  };
  if (opts.vt === false || id === S.cur) go(); else vt(go);
}
function stepThread(d) {
  const list = visibleThreads(); if (!list.length) return;
  let i = list.findIndex((t) => t.id === S.cur);
  i = i < 0 ? 0 : Math.max(0, Math.min(list.length - 1, i + d));
  openThread(list[i].id, { show: root.dataset.view === 'thread' });
  const el = $(`[data-id="${list[i].id}"]`, tlist); if (el) el.scrollIntoView({ block: 'nearest' });
}
function setAll(open) {
  const t = byId(S.cur); if (!t) return;
  t.msgs.forEach((m, i) => { m.open = open || i === t.msgs.length - 1; if (!open) m.quoteOpen = false; });
  if (t.msgs.length > 4) t.moreOpen = open;
  sync();
}
function stepMsg(d) {
  const heads = $$('.apm-convo__mhead, .apm-convo__pill', pane).filter((b) => !b.closest('[inert]') && !b.inert);
  if (!heads.length) return;
  let i = heads.indexOf(document.activeElement);
  i = i < 0 ? (d > 0 ? 0 : heads.length - 1) : Math.max(0, Math.min(heads.length - 1, i + d));
  heads[i].focus();
  heads[i].scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
}
function openComposer(mode, who) {
