  $('[data-act="close-composer"]', c).hidden = true;
  $('.apm-convo__cprompt', c).focus({ preventScroll: true });
}
function send() {
  const t = byId(S.cur); const ta = $('.apm-convo__composer textarea', pane);
  const text = ta.value.trim();
  if (!text) { ta.focus(); ta.animate([{ translate: '0 0' }, { translate: '-5px 0' }, { translate: '4px 0' }, { translate: '0 0' }], { duration: RM.matches ? 1 : 300 }); return; }
  t.msgs.forEach((m) => { m.open = false; m.unread = false; });
  t.msgs.push({ from: 'me', at: 'Oct 2, 10:04', body: text.split(/\n{2,}/), open: true, fresh: true });
  S.composer = false; S.draft = ''; ta.value = '';
  if (t.reply) S.typing = t.id;
  renderList(); renderThread();
  const sc = $('.apm-convo__scroll', pane);
  const last = $$('.apm-convo__msg', pane).pop();
  if (last) sc.scrollTo({ top: last.offsetTop - 70, behavior: RM.matches ? 'auto' : 'smooth' });
  showToast(`Sent to ${S.mode === 'all' ? t.people.length + ' people' : P[latestOther(t)].first}`, false);
  /* the other side answers once per thread, so the thread feels alive */
  if (t.reply) {
    const text2 = t.reply; t.reply = null;
    setTimeout(() => {
      if (!root.isConnected) return;
      S.typing = null;
      t.msgs.push({ from: latestOther(t), at: 'Oct 2, 10:06', body: [text2], open: true, unread: S.cur !== t.id, fresh: true });
      t.msgs.forEach((m, i) => { if (i < t.msgs.length - 2) m.open = false; });
      renderList();
      if (S.cur === t.id) {
        renderThread();
        const s2 = $('.apm-convo__scroll', pane); const l2 = $$('.apm-convo__msg', pane).pop();
        if (l2) s2.scrollTo({ top: l2.offsetTop - 70, behavior: RM.matches ? 'auto' : 'smooth' });
      }
    }, 2600);
  }
}
function toggleMute() {
  const t = byId(S.cur); if (!t) return;
  S.history.push({ id: t.id, muted: t.muted });
  t.muted = !t.muted;
  showToast(t.muted ? 'Conversation muted — new replies skip the inbox' : 'Conversation unmuted', true);
  const list = visibleThreads();
  if (!list.some((x) => x.id === t.id) && list.length) {
    vt(() => { renderList(); openThread(list[0].id, { vt: false, show: false }); if (narrow()) root.dataset.view = 'list'; });
  } else { renderList(); renderThread(); }
}
function undo() {
  const h = S.history.pop(); if (!h) return;
  const t = byId(h.id); t.muted = h.muted;
  vt(() => { renderList(); openThread(t.id, { vt: false, show: false }); });
  showToast('Undone', false);
}
function showToast(text, undoable) {
  $('span', toast).textContent = text;
  $('button', toast).hidden = !undoable;
  toast.setAttribute('data-show', '');
  clearTimeout(showToast.t);
  showToast.t = setTimeout(() => toast.removeAttribute('data-show'), 4600);
}

/* ---------- events ---------- */
tlist.addEventListener('click', (e) => { const li = e.target.closest('.apm-convo__thread'); if (li) openThread(li.dataset.id); });
$('.apm-convo__seg').addEventListener('click', (e) => {
  const b = e.target.closest('[data-tab]'); if (!b) return;
  S.tab = b.dataset.tab;
  const list = visibleThreads();
  renderList(true);
  if (!list.some((t) => t.id === S.cur) && list.length) openThread(list[0].id, { show: false });
});
$('.apm-convo__seg').addEventListener('keydown', (e) => {
  const tabs = $$('[role="tab"]', e.currentTarget); const i = tabs.indexOf(e.target);
  const d = { ArrowRight: 1, ArrowLeft: -1 }[e.key]; if (!d || i < 0) return;
  e.preventDefault(); e.stopPropagation();
  const n = tabs[(i + d + tabs.length) % tabs.length]; n.focus(); n.click();
});
pane.addEventListener('click', (e) => {
  const a = e.target.closest('[data-act], [data-mode]'); if (!a) return;
  const t = byId(S.cur);
  if (a.dataset.mode) { S.mode = a.dataset.mode; paintRecipients(); return; }
  const li = a.closest('.apm-convo__msg');
  const m = li && t ? t.msgs[+li.dataset.i] : null;
  switch (a.dataset.act) {
    case 'toggle': if (m) { m.open = !m.open; sync(); } break;
    case 'quote': if (m) { m.quoteOpen = !m.quoteOpen; sync(); } break;
    case 'more': t.moreOpen = true; sync(); { const first = $('.apm-convo__hidden .apm-convo__mhead', pane); if (first) first.focus({ preventScroll: true }); } break;
    case 'expand': setAll(true); break;
    case 'collapse': setAll(false); break;
    case 'mute': toggleMute(); break;
    case 'back': root.dataset.view = 'list'; tlist.focus({ preventScroll: true }); break;
    case 'compose': openComposer('reply'); break;
    case 'reply-to': openComposer('reply', a.dataset.from === 'me' ? null : a.dataset.from); break;
    case 'forward': openComposer('all'); { const ta = $('.apm-convo__composer textarea', pane); ta.value = `Forwarding “${t.subject}”.\n\n`; } break;
    case 'close-composer': closeComposer(); break;
    case 'send': send(); break;
  }
});
root.addEventListener('click', (e) => { if (e.target.closest('[data-act="undo"]')) undo(); });

root.addEventListener('keydown', (e) => {
  const tg = e.target;
  const typing = tg.closest('textarea, input');
  if (typing) {
    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { e.preventDefault(); send(); }
    else if (e.key === 'Escape') { e.preventDefault(); closeComposer(); }
    return;
  }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const onButton = tg.closest('button') && tg !== tlist;
  const k = e.key;
  const map = {
    j: () => stepThread(1), k: () => stepThread(-1),
    n: () => stepMsg(1), p: () => stepMsg(-1),
    ';': () => setAll(true), ':': () => setAll(false),
    r: () => openComposer('reply'), a: () => openComposer('all'),
    m: () => toggleMute(), z: () => undo(),
    Escape: () => { if (narrow() && root.dataset.view === 'thread') { root.dataset.view = 'list'; tlist.focus({ preventScroll: true }); } },
  };
  if (tg === tlist) { map.ArrowDown = map.j; map.ArrowUp = map.k; map.Enter = () => { if (narrow()) root.dataset.view = 'thread'; stepMsg(1); }; }
  if (onButton && (k === 'Enter' || k === ' ')) return;
  const fn = map[k]; if (!fn) return;
  e.preventDefault(); fn();
});

new ResizeObserver(() => { if (!root.isConnected) return; if (!narrow()) root.dataset.view = 'thread'; }).observe(root);

root.dataset.view = narrow() ? 'list' : 'thread';
renderList(true);
openThread('t1', { vt: false, show: false });
sync();

