/* Chip composer. Re-theme with --apm-compose-paper, -ink, -accent (and -h). */
@property --apm-compose-p { syntax: "<number>"; inherits: true; initial-value: 1; }

.apm-compose {
  --apm-compose-paper: oklch(0.972 0.007 205);
  --apm-compose-ink: oklch(0.25 0.03 235);
  --apm-compose-accent: oklch(0.52 0.1 186);
  --apm-compose-danger: oklch(0.57 0.19 27);

  --apm-compose-card: color-mix(in oklch, var(--apm-compose-paper) 30%, white);
  --apm-compose-line: color-mix(in oklch, var(--apm-compose-ink) 11%, transparent);
  --apm-compose-line2: color-mix(in oklch, var(--apm-compose-ink) 20%, transparent);
  --apm-compose-muted: color-mix(in oklch, var(--apm-compose-ink) 60%, var(--apm-compose-paper));
  --apm-compose-faint: color-mix(in oklch, var(--apm-compose-ink) 40%, var(--apm-compose-paper));
  --apm-compose-hover: color-mix(in oklch, var(--apm-compose-ink) 5%, transparent);
  --apm-compose-tint: color-mix(in oklch, var(--apm-compose-accent) 12%, var(--apm-compose-card));
  --apm-compose-ease: cubic-bezier(.2, .85, .25, 1);
  --apm-compose-spring: linear(0, 0.06 3%, 0.25 7%, 0.62 14%, 0.88 21%, 1.02 29%, 1.06 35%, 1.04 43%, 1.01 56%, 0.996 72%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apm-compose-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--apm-compose-paper);
  color: var(--apm-compose-ink);
  font: 400 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  outline: none;
  box-shadow: 0 0 0 1px var(--apm-compose-line);
}
:where(.apm-compose) *, :where(.apm-compose) *::before, :where(.apm-compose) *::after { box-sizing: border-box; }
:where(.apm-compose) :is(button, input) { font: inherit; color: inherit; }
:where(.apm-compose) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apm-compose) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apm-compose) :focus-visible { outline: 2px solid color-mix(in oklch, var(--apm-compose-accent) 75%, transparent); outline-offset: 2px; }
:where(.apm-compose) kbd {
  display: inline-block; min-width: 18px; padding: 3px 5px 2px; border-radius: 4px; text-align: center;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace;
  background: color-mix(in oklch, var(--apm-compose-ink) 6%, transparent); color: var(--apm-compose-muted);
  box-shadow: inset 0 -1px 0 var(--apm-compose-line);
}
.apm-compose [hidden] { display: none !important; }

.apm-compose__app {
  display: grid; height: 100%;
  grid-template-columns: 240px minmax(0, 1fr) 270px;
  grid-template-areas: "rail main ctx";
}
.apm-compose__rail { grid-area: rail; }
.apm-compose__main { grid-area: main; }
.apm-compose__ctx { grid-area: ctx; }

/* ---------- rail ---------- */
.apm-compose__rail { display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 18px 12px 12px; border-right: 1px solid var(--apm-compose-line); min-height: 0; }
.apm-compose__brand { display: flex; align-items: center; gap: 9px; padding: 0 8px; }
.apm-compose__brand svg { width: 22px; height: 22px; color: var(--apm-compose-accent); }
.apm-compose__brand b { font-weight: 700; letter-spacing: -0.015em; }
.apm-compose__new {
  display: flex; align-items: center; gap: 9px; height: 38px; padding: 0 10px 0 12px; border-radius: 10px;
  background: var(--apm-compose-card); box-shadow: 0 0 0 1px var(--apm-compose-line), 0 4px 12px -8px var(--apm-compose-ink);
  font-weight: 600; transition: box-shadow .2s, translate .3s var(--apm-compose-spring);
}
.apm-compose__new:hover { translate: 0 -1px; box-shadow: 0 0 0 1px var(--apm-compose-line2), 0 8px 18px -10px var(--apm-compose-ink); }
.apm-compose__new svg { color: var(--apm-compose-accent); }
.apm-compose__new kbd { margin-left: auto; }
.apm-compose__boxes { overflow: auto; min-height: 0; display: grid; align-content: start; grid-auto-rows: max-content; gap: 14px; scrollbar-width: thin; padding: 2px; }
.apm-compose__bh { display: flex; align-items: baseline; justify-content: space-between; margin: 4px 8px 4px; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--apm-compose-faint); }
.apm-compose__bh span { font-variant-numeric: tabular-nums; letter-spacing: 0; }
.apm-compose__blist { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.apm-compose__bitem {
  position: relative; display: grid; gap: 1px; width: 100%; text-align: left; padding: 8px 10px; border-radius: 9px;
  transition: background-color .2s;
}
.apm-compose__bitem:hover { background: var(--apm-compose-hover); }
.apm-compose__bitem[aria-current="true"] { background: var(--apm-compose-card); box-shadow: 0 0 0 1px var(--apm-compose-line), 0 4px 10px -8px var(--apm-compose-ink); }
.apm-compose__bitem[aria-current="true"]::before { content: ""; position: absolute; left: -2px; top: 10px; bottom: 10px; width: 3px; border-radius: 3px; background: var(--apm-compose-accent); }
.apm-compose__bitem b { font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-compose__bitem small { font-size: 12px; color: var(--apm-compose-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-compose__bitem[data-new] { animation: apm-compose-pop .6s var(--apm-compose-spring) both; }
.apm-compose__outrow { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; background: var(--apm-compose-card); box-shadow: 0 0 0 1px var(--apm-compose-line); }
.apm-compose__outrow[data-new] { animation: apm-compose-pop .6s var(--apm-compose-spring) both; }
.apm-compose__outrow b { display: block; font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-compose__outrow small { display: block; font-size: 11.5px; color: var(--apm-compose-muted); font-variant-numeric: tabular-nums; }
.apm-compose__outrow button { font-size: 12px; font-weight: 650; color: var(--apm-compose-accent); padding: 4px 6px; border-radius: 6px; }
.apm-compose__outrow button:hover { background: var(--apm-compose-tint); }
.apm-compose__ring {
  --apm-compose-p: 1;
  width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center;
  background: conic-gradient(var(--apm-compose-accent) calc(var(--apm-compose-p) * 360deg), var(--apm-compose-line) 0);
  font: 650 10px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
}
.apm-compose__ring::before { content: ""; grid-area: 1 / 1; width: 22px; height: 22px; border-radius: 50%; background: var(--apm-compose-card); }
.apm-compose__ring span { grid-area: 1 / 1; position: relative; }
.apm-compose__ring[data-run] { animation: apm-compose-drain 5s linear forwards; }
.apm-compose__ring svg { grid-area: 1 / 1; position: relative; width: 14px; height: 14px; color: var(--apm-compose-accent); }
.apm-compose__ring.is-sched { background: var(--apm-compose-tint); }

/* ---------- main ---------- */
.apm-compose__main { min-width: 0; min-height: 0; overflow: hidden; padding: clamp(14px, 2.4cqi, 28px); display: flex; flex-direction: column; gap: 12px; }
.apm-compose__tabs { display: none; }
.apm-compose__card {
  position: relative; display: flex; flex-direction: column; flex: 1 1 auto; min-width: 0; min-height: 0;
  border-radius: 16px; background: var(--apm-compose-card);
  box-shadow: 0 0 0 1px var(--apm-compose-line), 0 1px 2px color-mix(in oklch, var(--apm-compose-ink) 6%, transparent), 0 24px 50px -32px color-mix(in oklch, var(--apm-compose-ink) 45%, transparent);
  transition: opacity .35s var(--apm-compose-ease), translate .5s var(--apm-compose-ease), filter .35s;
  @starting-style { opacity: 0; translate: 0 12px; }
}
.apm-compose__card.is-fresh { animation: apm-compose-fresh .55s var(--apm-compose-ease) both; }
.apm-compose__chead { display: flex; align-items: center; gap: 10px; padding: 14px 12px 6px 20px; }
.apm-compose__title { margin: 0; font-size: clamp(1.05rem, .9rem + .7cqi, 1.3rem); font-weight: 680; letter-spacing: -0.02em; text-wrap: balance; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.apm-compose__saved { margin-left: auto; font-size: 12px; color: var(--apm-compose-faint); font-variant-numeric: tabular-nums; white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; }
.apm-compose__saved::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--apm-compose-accent); opacity: .8; }
.apm-compose__saved[data-busy]::before { background: var(--apm-compose-faint); animation: apm-compose-blink .8s ease-in-out infinite; }
.apm-compose__icon { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--apm-compose-muted); transition: background-color .15s, color .15s; flex: none; }
.apm-compose__icon:hover { background: var(--apm-compose-hover); color: var(--apm-compose-danger); }
.apm-compose__from { display: flex; align-items: baseline; gap: 10px; padding: 4px 20px 10px; font-size: 13px; border-bottom: 1px solid var(--apm-compose-line); }
.apm-compose__from span, .apm-compose__flabel { width: 52px; flex: none; font-size: 12.5px; color: var(--apm-compose-faint); }
.apm-compose__from b { font-weight: 600; }
.apm-compose__from small { color: var(--apm-compose-muted); font-size: 12.5px; }

.apm-compose__field {
  position: relative; display: flex; align-items: flex-start; gap: 10px;
  padding: 7px 14px 7px 20px; border-bottom: 1px solid var(--apm-compose-line);
  transition: background-color .25s;
  @starting-style { background: var(--apm-compose-tint); }
}
.apm-compose__field:focus-within { background: color-mix(in oklch, var(--apm-compose-accent) 4%, var(--apm-compose-card)); }
.apm-compose__field.is-drop { background: var(--apm-compose-tint); box-shadow: inset 3px 0 0 var(--apm-compose-accent); }
.apm-compose__flabel { padding-top: 7px; }
.apm-compose__chips { flex: 1; min-width: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 5px; min-height: 34px; cursor: text; }
.apm-compose__chipset { display: contents; }
.apm-compose__addr { flex: 1; min-width: 120px; height: 30px; border: 0; outline: none; background: none; font-size: 13.5px; }
.apm-compose__ccbtns { display: flex; gap: 2px; padding-top: 4px; }
.apm-compose__ccbtns button { height: 26px; padding: 0 8px; border-radius: 6px; font-size: 12.5px; color: var(--apm-compose-muted); }
.apm-compose__ccbtns button:hover { background: var(--apm-compose-hover); color: var(--apm-compose-ink); }

.apm-compose__chip {
  display: inline-flex; align-items: center; gap: 6px; max-width: 100%;
  height: 28px; padding: 0 4px 0 3px; border-radius: 14px;
  background: color-mix(in oklch, var(--apm-compose-ink) 5.5%, var(--apm-compose-card));
  box-shadow: inset 0 0 0 1px var(--apm-compose-line);
  font-size: 13px; cursor: grab; user-select: none;
  transition: background-color .2s, box-shadow .2s, scale .35s var(--apm-compose-spring), opacity .2s;
}
.apm-compose__chip[data-new] { transition: background-color .2s, box-shadow .2s, scale .5s var(--apm-compose-spring), opacity .25s; @starting-style { scale: .4; opacity: 0; } }
.apm-compose__chip:hover { box-shadow: inset 0 0 0 1px var(--apm-compose-line2); }
.apm-compose__chip[aria-selected="true"] { background: var(--apm-compose-accent); color: white; box-shadow: none; }
.apm-compose__chip[aria-selected="true"] .apm-compose__cav { background: color-mix(in oklch, white 25%, transparent); color: white; }
.apm-compose__chip[data-ext] .apm-compose__cname::after { content: "ext"; margin-left: 6px; padding: 1px 4px; border-radius: 4px; font: 600 9.5px/1.3 ui-monospace, Menlo, monospace; letter-spacing: .04em; background: oklch(0.93 0.06 75); color: oklch(0.45 0.1 65); vertical-align: 1px; }
.apm-compose__chip[aria-selected="true"] .apm-compose__cname::after { background: color-mix(in oklch, white 25%, transparent); color: white; }
.apm-compose__chip[data-bad] { background: color-mix(in oklch, var(--apm-compose-danger) 9%, var(--apm-compose-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apm-compose-danger) 40%, transparent); color: var(--apm-compose-danger); }
.apm-compose__chip[data-bad] .apm-compose__cname { text-decoration: underline wavy color-mix(in oklch, var(--apm-compose-danger) 70%, transparent); text-underline-offset: 3px; }
.apm-compose__chip.is-dragging { opacity: .35; }
.apm-compose__chip.is-pulse { animation: apm-compose-pulse .6s var(--apm-compose-ease); }
.apm-compose__cav { width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; font-size: 9.5px; font-weight: 700; background: oklch(0.9 0.05 var(--h)); color: oklch(0.38 0.09 var(--h)); flex: none; }
.apm-compose__chip[data-bad] .apm-compose__cav { background: color-mix(in oklch, var(--apm-compose-danger) 16%, transparent); color: var(--apm-compose-danger); }
.apm-compose__cname { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-compose__cx { width: 20px; height: 20px; display: grid; place-items: center; border-radius: 50%; color: inherit; opacity: .55; transition: opacity .15s, background-color .15s; }
.apm-compose__cx:hover { opacity: 1; background: color-mix(in oklch, currentColor 14%, transparent); }
.apm-compose__cx svg { width: 12px; height: 12px; stroke-width: 2.2; }

.apm-compose__warn { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--apm-compose-ease); }
.apm-compose__warn > div { min-height: 0; overflow: hidden; }
.apm-compose__warn[data-on] { grid-template-rows: 1fr; }
.apm-compose__warn p { margin: 0; display: flex; align-items: center; gap: 8px; padding: 8px 20px; font-size: 12.5px; background: oklch(0.96 0.04 80); color: oklch(0.42 0.09 65); border-bottom: 1px solid oklch(0.9 0.06 80); text-wrap: pretty; }
.apm-compose__warn svg { width: 15px; height: 15px; }

.apm-compose__subj { align-items: center; }
.apm-compose__subj .apm-compose__flabel { padding-top: 0; }
.apm-compose__subject { flex: 1; min-width: 0; height: 34px; border: 0; outline: none; background: none; font-size: 14px; font-weight: 600; }

.apm-compose__toolbar { display: flex; align-items: center; gap: 2px; flex-wrap: wrap; padding: 6px 14px; border-bottom: 1px solid var(--apm-compose-line); }
.apm-compose__toolbar button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-width: 32px; height: 30px; padding: 0 6px; border-radius: 7px; font-size: 14px; color: var(--apm-compose-muted); transition: background-color .15s, color .15s; }
.apm-compose__toolbar button:hover { background: var(--apm-compose-hover); color: var(--apm-compose-ink); }
.apm-compose__toolbar button[aria-pressed="true"] { background: var(--apm-compose-tint); color: var(--apm-compose-accent); }
.apm-compose__toolbar svg { width: 17px; height: 17px; }
.apm-compose__toolbar b, .apm-compose__toolbar i, .apm-compose__toolbar u { font-family: ui-serif, Georgia, serif; font-size: 15px; }
.apm-compose__sep { width: 1px; height: 18px; margin: 0 4px; background: var(--apm-compose-line2); }
.apm-compose__snip { margin-left: auto; font-size: 12.5px !important; }

.apm-compose__body { flex: 1 1 auto; min-height: 90px; overflow: auto; display: flex; flex-direction: column; scrollbar-width: thin; overscroll-behavior: contain; }
.apm-compose__editor {
  flex: 1 0 auto; min-height: 120px; padding: 18px 20px 10px; outline: none; font-size: 14.5px; line-height: 1.65; text-wrap: pretty;
  caret-color: var(--apm-compose-accent);
}
.apm-compose__editor:empty::before { content: "Write your message…"; color: var(--apm-compose-faint); }
.apm-compose__editor p, .apm-compose__editor div { margin: 0; }
.apm-compose__editor ul, .apm-compose__editor ol { margin: .4em 0; padding-left: 1.4em; }
.apm-compose__editor blockquote { margin: .5em 0; padding: 2px 0 2px 14px; border-left: 3px solid color-mix(in oklch, var(--apm-compose-accent) 50%, transparent); color: var(--apm-compose-muted); }
.apm-compose__editor a { color: var(--apm-compose-accent); text-underline-offset: 2px; }
