    `<section><h3 class="apm-compose__bh">Drafts <span>${D.length}</span></h3><ul class="apm-compose__blist">${D.map((d) => `<li><button type="button" class="apm-compose__bitem" data-draft="${d.id}" aria-current="${d.id === S.cur}" ${d.id === freshId ? 'data-new' : ''}><b>${esc(d.subject || '(no subject)')}</b><small>${esc(names(d.to))} · ${esc(d.saved)}</small></button></li>`).join('')}</ul></section>
