     <section><h3 class="apm-compose__bh">Sent <span>${SENT.length}</span></h3><ul class="apm-compose__blist">${SENT.map((s) => `<li class="apm-compose__bitem" ${s.id === freshId ? 'data-new' : ''}><b>${esc(s.subject || '(no subject)')}</b><small>${esc(names(s.to))} · ${esc(s.when)}</small></li>`).join('')}</ul></section>`;
  $('.apm-compose__tabn').textContent = D.length + OUT.length;
}

/* ---------- drafts ---------- */
function flush() { const d = cur(); if (d) { d.html = editor.innerHTML; d.subject = subj.value; } }
function load(id, fresh) {
  flush(); S.cur = id; const d = cur();
  subj.value = d.subject; editor.innerHTML = d.html;
  $('.apm-compose__title').textContent = d.subject.trim() || 'New message';
  $('.apm-compose__saved').textContent = 'Saved ' + d.saved;
  $('.apm-compose__alert').removeAttribute('data-on');
  S.focus = null; closeSugg(); closeMenu();
  renderAllChips(); renderFiles(); renderRail(); count();
  if (fresh && !RM.matches) { card.classList.remove('is-fresh'); void card.offsetWidth; card.classList.add('is-fresh'); }
}
function count() {
  const words = (editor.innerText.match(/[\p{L}\p{N}’'-]+/gu) || []).length;
  $('.apm-compose__count').textContent = `${words} word${words === 1 ? '' : 's'} · ${Math.max(1, Math.round(words / 220))} min read`;
}
function dirty() {
  const s = $('.apm-compose__saved'); s.textContent = 'Saving…'; s.setAttribute('data-busy', '');
  count();
  clearTimeout(dirty.t);
  dirty.t = setTimeout(() => {
    if (!root.isConnected) return;
    flush(); const d = cur(); if (!d) return; d.saved = clock();
    s.textContent = 'Saved ' + d.saved; s.removeAttribute('data-busy');
    renderRail();
  }, 650);
}
function newDraft() {
  flush();
  const d = { id: 'd' + S.nextId++, to: [], cc: [], bcc: [], subject: '', html: '', files: [], saved: clock() };
  D.unshift(d); load(d.id, true); renderRail(d.id);
  root.dataset.view = 'compose'; syncTabs();
  $('.apm-compose__field[data-kind="to"] .apm-compose__addr').focus();
}

/* ---------- sending ---------- */
function alertMsg(html, actions = []) {
  const a = $('.apm-compose__alert');
  a.innerHTML = `<div><p>${WARN}<span>${html}</span>${actions.map(([l, act]) => `<button type="button" data-act="${act}">${l}</button>`).join('')}</p></div>`;
  a.setAttribute('data-on', '');
  if (!RM.matches) card.animate([{ translate: '0 0' }, { translate: '-6px 0' }, { translate: '5px 0' }, { translate: '-3px 0' }, { translate: '0 0' }], { duration: 380, easing: 'cubic-bezier(.3,.7,.4,1)' });
}
function trySend(force, sched) {
  flush(); const d = cur();
  const all = allRcpt(d); const bad = all.filter((r) => !r.ok);
  if (!all.length) { alertMsg('Add at least one recipient.'); $('.apm-compose__addr').focus(); return; }
  if (bad.length) { alertMsg(`${bad.length} address${bad.length === 1 ? ' needs' : 'es need'} fixing: <b>${esc(bad.map((r) => r.a).join(', '))}</b>`, [['Remove invalid', 'drop-bad']]); return; }
  if (!force && !d.subject.trim()) { alertMsg('This message has no subject.', [['Send anyway', sched ? 'force-sched' : 'force']]); subj.focus(); S.pendingSched = sched; return; }
  if (!force && /\battach(ed|ment|ing)?\b/i.test(editor.innerText) && !d.files.length) { alertMsg('You mention an attachment, but nothing is attached.', [['Attach a file', 'attach'], ['Send anyway', sched ? 'force-sched' : 'force']]); S.pendingSched = sched; return; }
  $('.apm-compose__alert').removeAttribute('data-on');
  const go = () => {
    D = D.filter((x) => x.id !== d.id);
    const o = { id: 'o' + S.nextId++, to: d.to, subject: d.subject, draft: d };
    if (sched) { o.sched = true; o.when = sched; } else { o.due = performance.now() + 5000; }
    OUT.unshift(o);
    if (!D.length) D.unshift({ id: 'd' + S.nextId++, to: [], cc: [], bcc: [], subject: '', html: '', files: [], saved: clock() });
    S.cur = null; load(D[0].id, true); renderRail(o.id);
    toastMsg(sched ? `Scheduled for ${sched}` : 'Sending in 5 seconds', () => unsend(o.id), sched ? 'Edit' : 'Undo');
    if (!sched) tick();
  };
  flyOut(go);
}
function flyOut(done) {
  if (RM.matches) return done();
  const target = $('.apm-compose__outbox .apm-compose__bh');
  const cr = card.getBoundingClientRect();
  const tr = target && target.offsetParent ? target.getBoundingClientRect() : { left: cr.left + cr.width / 2, top: cr.top - 40, width: 0, height: 0 };
  const dx = tr.left + tr.width / 2 - (cr.left + cr.width / 2);
  const dy = tr.top + tr.height / 2 - (cr.top + cr.height / 2);
  const a = card.animate([
    { transform: 'none', opacity: 1, clipPath: 'inset(0 round 16px)' },
    { transform: 'translateY(6px) scale(.97)', opacity: 1, clipPath: 'inset(0 0 30% 0 round 16px)', offset: 0.3 },
    { transform: `translate(${dx}px, ${dy}px) scale(.08)`, opacity: 0, clipPath: 'inset(0 0 70% 0 round 60px)' },
