}
function tick() {
  if (S.timer) return;
  S.timer = setInterval(() => {
    if (!root.isConnected) { clearInterval(S.timer); return; }
    const now = performance.now(); let changed = false;
    OUT.filter((o) => !o.sched).forEach((o) => {
      const left = Math.ceil((o.due - now) / 1000);
      const el = root.querySelector(`[data-left="${o.id}"]`); if (el) el.textContent = Math.max(0, left);
      if (left <= 0) {
        OUT = OUT.filter((x) => x !== o);
        SENT.unshift({ id: 's' + S.nextId++, to: o.to, subject: o.subject, when: 'Today, ' + clock() });
        changed = true;
        toastMsg(`Sent to ${names(o.to)}`);
      }
    });
    if (changed) renderRail(SENT[0].id);
    if (!OUT.some((o) => !o.sched)) { clearInterval(S.timer); S.timer = null; }
