}
function unsend(id) {
  const o = OUT.find((x) => x.id === id); if (!o) return;
  OUT = OUT.filter((x) => x !== o);
  flush();
  const blank = D.find((d) => d.id === S.cur && !allRcpt(d).length && !d.subject && !editor.innerText.trim());
  if (blank) D = D.filter((d) => d !== blank);
  D.unshift(o.draft);
  load(o.draft.id, true); renderRail(o.draft.id);
