}

/* ---------- menus ---------- */
function openMenu(kind, anchor) {
  saveRange();
  S.menu = kind;
  if (kind === 'schedule') {
    menu.innerHTML = '<p>Schedule send</p>' + [['Tomorrow morning', 'Sat 3 Oct, 08:00'], ['Monday morning', 'Mon 5 Oct, 08:00'], ['Monday afternoon', 'Mon 5 Oct, 13:30']].map(([l, w]) => `<button type="button" role="menuitem" data-sched="${w}">${l}<small>${w}</small></button>`).join('');
  } else {
    menu.innerHTML = '<p>Insert snippet</p>' + SNIPS.map((s, i) => `<button type="button" role="menuitem" data-snip="${i}">${s[0]}<small>${esc(s[1].slice(0, 26))}…</small></button>`).join('');
  }
  menu.hidden = false;
  const rr = root.getBoundingClientRect(); const ar = anchor.getBoundingClientRect();
  const w = menu.offsetWidth, h = menu.offsetHeight;
  let x = ar.right - rr.left - w; x = Math.max(12, Math.min(x, rr.width - w - 12));
  let y = kind === 'schedule' ? ar.top - rr.top - h - 8 : ar.bottom - rr.top + 6;
  if (y < 8) y = ar.bottom - rr.top + 6;
  menu.style.left = x + 'px'; menu.style.top = y + 'px';
  $('button', menu).focus();
}
function closeMenu() { S.menu = null; menu.hidden = true; }
menu.addEventListener('click', (e) => {
  const b = e.target.closest('button'); if (!b) return;
  const kind = S.menu; closeMenu();
  if (b.dataset.sched) trySend(false, b.dataset.sched);
  else if (b.dataset.snip != null) { restoreRange(); document.execCommand('insertHTML', false, SNIPS[+b.dataset.snip][2]); dirty(); }
  void kind;
});
menu.addEventListener('keydown', (e) => {
  const items = $$('button', menu); const i = items.indexOf(document.activeElement);
  if (e.key === 'ArrowDown') { e.preventDefault(); items[(i + 1) % items.length].focus(); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); items[(i - 1 + items.length) % items.length].focus(); }
  else if (e.key === 'Escape' || e.key === 'Tab') { e.preventDefault(); closeMenu(); restoreRange(); }
});

/* ---------- toast ---------- */
function toastMsg(text, undo, label = 'Undo') {
  $('span', toast).textContent = text;
  const b = $('button', toast); b.hidden = !undo; b.textContent = label;
  S.undo = undo || null;
  toast.setAttribute('data-show', '');
  clearTimeout(toastMsg.t);
  toastMsg.t = setTimeout(() => toast.removeAttribute('data-show'), 4800);
}

/* ---------- wiring ---------- */
function syncTabs() { $$('.apm-compose__tabs [role="tab"]').forEach((b) => b.setAttribute('aria-selected', b.dataset.view === root.dataset.view)); }
root.addEventListener('click', (e) => {
  const t = e.target;
  if (S.menu && !t.closest('.apm-compose__menu') && !t.closest('[data-act="schedule"], [data-act="snippets"]')) closeMenu();
  if (!linkpop.hidden && !t.closest('.apm-compose__linkpop') && !t.closest('[data-cmd="link"]')) linkpop.hidden = true;
  const tab = t.closest('.apm-compose__tabs [role="tab"]');
  if (tab) { root.dataset.view = tab.dataset.view; syncTabs(); return; }
  const dr = t.closest('[data-draft]');
  if (dr) { if (dr.dataset.draft !== S.cur) load(dr.dataset.draft, true); root.dataset.view = 'compose'; syncTabs(); return; }
  const a = t.closest('[data-act]'); if (!a) return;
  const d = cur();
  switch (a.dataset.act) {
    case 'new': newDraft(); break;
    case 'cc': case 'bcc': { const k = a.dataset.act; d['show' + k[0].toUpperCase() + k.slice(1)] = true; renderChips(k); $(`.apm-compose__field[data-kind="${k}"] .apm-compose__addr`).focus(); break; }
    case 'attach': addFiles([SAMPLES[S.sampleI++ % SAMPLES.length]]); $('.apm-compose__alert').removeAttribute('data-on'); break;
    case 'unfile': { const i = +a.dataset.i; const [f] = d.files.splice(i, 1); renderFiles(); dirty(); toastMsg(`Removed ${f.n}`, () => { cur().files.splice(i, 0, f); renderFiles(); }); break; }
    case 'schedule': S.menu === 'schedule' ? closeMenu() : openMenu('schedule', a); break;
    case 'snippets': S.menu === 'snippets' ? closeMenu() : openMenu('snippets', a); break;
    case 'force': trySend(true, S.pendingSched); break;
    case 'force-sched': trySend(true, S.pendingSched); break;
    case 'drop-bad': ['to', 'cc', 'bcc'].forEach((k) => { d[k] = d[k].filter((r) => r.ok); }); renderAllChips(); $('.apm-compose__alert').removeAttribute('data-on'); dirty(); break;
    case 'focus': S.focus = a.dataset.a; renderCtx(); break;
    case 'wake': trySend(false, 'Today, ' + a.dataset.when); break;
    case 'unsend': case 'unschedule': unsend(a.dataset.id); break;
    case 'toast-undo': if (S.undo) { const u = S.undo; S.undo = null; toast.removeAttribute('data-show'); u(); } break;
    case 'discard': {
