      if (!D.length) D.push({ id: 'd' + S.nextId++, to: [], cc: [], bcc: [], subject: '', html: '', files: [], saved: clock() });
      S.cur = null; load(D[Math.min(idx, D.length - 1)].id, true);
      toastMsg('Draft discarded', () => { D.splice(idx, 0, gone); load(gone.id, true); });
      break;
    }
  }
});
card.addEventListener('submit', (e) => { e.preventDefault(); trySend(false); });

card.addEventListener('dragover', (e) => {
  const field = e.target.closest('.apm-compose__field[data-kind]');
  if (dragChip && field) { e.preventDefault(); $$('.apm-compose__field.is-drop').forEach((f) => f !== field && f.classList.remove('is-drop')); field.classList.add('is-drop'); return; }
  if (!dragChip && e.dataTransfer && Array.from(e.dataTransfer.types).includes('Files')) { e.preventDefault(); card.classList.add('is-over'); }
});
card.addEventListener('dragleave', (e) => { if (!card.contains(e.relatedTarget)) { card.classList.remove('is-over'); $$('.apm-compose__field.is-drop').forEach((f) => f.classList.remove('is-drop')); } });
card.addEventListener('drop', (e) => {
  card.classList.remove('is-over');
