css:
/* Split inbox. Re-theme with --apm-split-bg, -ink and the four lane hues (and -h). */
@property --apm-split-p { syntax: "<number>"; inherits: false; initial-value: 0; }

.apm-split {
  --apm-split-bg: oklch(0.19 0.007 65);
  --apm-split-ink: oklch(0.95 0.008 80);
  --apm-split-priority: oklch(0.72 0.17 32);
  --apm-split-people: oklch(0.82 0.17 132);
  --apm-split-updates: oklch(0.76 0.11 232);
  --apm-split-news: oklch(0.83 0.1 84);

  --apm-split-panel: color-mix(in oklch, var(--apm-split-ink) 4%, var(--apm-split-bg));
  --apm-split-card: color-mix(in oklch, var(--apm-split-ink) 7.5%, var(--apm-split-bg));
  --apm-split-line: color-mix(in oklch, var(--apm-split-ink) 10%, transparent);
  --apm-split-line2: color-mix(in oklch, var(--apm-split-ink) 18%, transparent);
  --apm-split-muted: color-mix(in oklch, var(--apm-split-ink) 62%, var(--apm-split-bg));
  --apm-split-faint: color-mix(in oklch, var(--apm-split-ink) 40%, var(--apm-split-bg));
  --apm-split-ease: cubic-bezier(.2, .85, .2, 1);
  --apm-split-spring: linear(0, 0.06 3%, 0.25 7%, 0.62 14%, 0.89 21%, 1.03 29%, 1.07 35%, 1.05 43%, 1.01 56%, 0.995 72%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apm-split-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--apm-split-bg);
  color: var(--apm-split-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  outline: none;
}
:where(.apm-split) *, :where(.apm-split) *::before, :where(.apm-split) *::after { box-sizing: border-box; }
:where(.apm-split) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apm-split) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apm-split) :focus-visible { outline: 2px solid var(--apm-split-ink); outline-offset: 2px; }
:where(.apm-split) kbd {
  display: inline-block; min-width: 18px; padding: 3px 5px 2px; border-radius: 4px; text-align: center;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace;
  background: color-mix(in oklch, var(--apm-split-ink) 9%, transparent); color: var(--apm-split-muted);
  box-shadow: inset 0 -1px 0 var(--apm-split-line);
}
.apm-split [hidden] { display: none !important; }

.apm-split__app {
  display: grid; height: 100%;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  grid-template-areas: "top" "screener" "tabs" "board" "keys";
}
.apm-split__top { grid-area: top; }
.apm-split__screener { grid-area: screener; }
.apm-split__tabs { grid-area: tabs; }
.apm-split__board { grid-area: board; }
.apm-split__keys { grid-area: keys; }

.apm-split__top { display: flex; align-items: center; gap: 12px; padding: 14px 18px 10px; }
.apm-split__brand { display: flex; align-items: center; gap: 10px; min-width: 0; }
.apm-split__brand svg { width: 24px; height: 24px; color: var(--apm-split-priority); }
.apm-split__brand b { display: block; font-size: clamp(1rem, .9rem + .5cqi, 1.2rem); font-weight: 700; letter-spacing: -0.02em; line-height: 1.1; }
.apm-split__sum { display: block; font-size: 12px; color: var(--apm-split-muted); font-variant-numeric: tabular-nums; }
.apm-split__actions { margin-left: auto; display: flex; gap: 6px; }
.apm-split__btn {
  display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 9px; font-size: 13px; font-weight: 560;
  box-shadow: inset 0 0 0 1px var(--apm-split-line2); transition: background-color .2s, transform .3s var(--apm-split-spring);
}
.apm-split__btn:hover { background: color-mix(in oklch, var(--apm-split-ink) 7%, transparent); }
.apm-split__btn:active { transform: scale(.96); }
.apm-split__btn svg { width: 16px; height: 16px; }
.apm-split__btn--pri { background: var(--apm-split-ink); color: var(--apm-split-bg); box-shadow: none; }
.apm-split__btn--pri:hover { background: color-mix(in oklch, var(--apm-split-ink) 88%, var(--apm-split-bg)); }
.apm-split__btn--pri kbd { background: color-mix(in oklch, var(--apm-split-bg) 14%, transparent); color: inherit; box-shadow: none; }
.apm-split__btn.is-spin svg { animation: apm-split-spin .7s var(--apm-split-ease); }
.apm-split__rulen { min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; display: grid; place-items: center; font-size: 11px; background: color-mix(in oklch, var(--apm-split-ink) 12%, transparent); font-variant-numeric: tabular-nums; }

/* ---------- screener ---------- */
.apm-split__screener { margin: 0 18px 12px; padding: 12px 12px 12px 14px; border-radius: 14px; background: repeating-linear-gradient(-45deg, var(--apm-split-panel) 0 10px, color-mix(in oklch, var(--apm-split-ink) 5.5%, var(--apm-split-bg)) 10px 20px); box-shadow: inset 0 0 0 1px var(--apm-split-line); display: grid; grid-template-columns: 200px minmax(0, 1fr); gap: 14px; align-items: center; }
.apm-split__screener:not(:has(.apm-split__scard)) { display: none; }
.apm-split__shead b { display: block; font-size: 13px; font-weight: 700; letter-spacing: -0.005em; }
.apm-split__shead span { display: block; font-size: 12px; color: var(--apm-split-muted); text-wrap: pretty; }
.apm-split__slist { list-style: none; margin: 0; padding: 2px; display: flex; gap: 10px; overflow-x: auto; scrollbar-width: none; scroll-snap-type: x mandatory; }
.apm-split__scard {
  flex: 0 0 min(352px, 86%); scroll-snap-align: start; display: grid; gap: 8px; padding: 10px 10px 10px 12px; border-radius: 11px;
  background: var(--apm-split-card); box-shadow: 0 0 0 1px var(--apm-split-line), 0 10px 24px -16px black;
  transition: opacity .3s, scale .45s var(--apm-split-spring), translate .45s var(--apm-split-ease);
  @starting-style { opacity: 0; scale: .9; }
}
.apm-split__scard.is-out { opacity: 0; scale: .85; translate: 0 10px; }
