.apm-split__schoose .apm-split__block:hover { color: oklch(0.72 0.17 25); background: color-mix(in oklch, oklch(0.6 0.2 25) 18%, transparent); box-shadow: inset 0 0 0 1px oklch(0.6 0.2 25 / .6); }

/* ---------- board ---------- */
.apm-split__board {
