.apm-split__card::before { content: ""; position: absolute; left: 0; top: 12px; bottom: 12px; width: 2px; border-radius: 2px; background: var(--c); opacity: 0; transition: opacity .2s; }
.apm-split__card[data-unread]::before { opacity: 1; }
