.apm-split__av { grid-row: span 2; width: 28px; height: 28px; border-radius: 9px; display: grid; place-items: center; font-size: 10.5px; font-weight: 700; background: oklch(0.36 0.06 var(--h)); color: oklch(0.92 0.06 var(--h)); }
.apm-split__from { font-size: 12.5px; font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-split__time { font-size: 11px; color: var(--apm-split-faint); font-variant-numeric: tabular-nums; white-space: nowrap; }
.apm-split__subj { grid-column: 2 / -1; font-size: 13px; line-height: 1.35; color: var(--apm-split-muted); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; text-wrap: pretty; }
