.apm-split__why { grid-column: 2 / -1; justify-self: start; margin-top: 4px; padding: 2px 7px; border-radius: 6px; font-size: 10.5px; font-weight: 600; background: color-mix(in oklch, var(--c) 18%, transparent); color: var(--c); }
.apm-split__lempty { padding: 26px 12px; text-align: center; font-size: 12.5px; color: var(--apm-split-faint); border-radius: 11px; border: 1.5px dashed var(--apm-split-line2); text-wrap: balance; }

.apm-split__ghost {
  position: absolute; z-index: 40; left: 0; top: 0; margin: 0; pointer-events: none; cursor: grabbing;
  box-shadow: 0 0 0 1px var(--apm-split-line2), 0 30px 60px -20px black, 0 0 0 1px color-mix(in oklch, var(--c) 50%, transparent);
  will-change: transform; transition: none;
}

.apm-split__keys { display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 10px 20px 12px; font-size: 11.5px; color: var(--apm-split-faint); user-select: none; }
.apm-split__keys kbd { margin-right: 2px; }
.apm-split__hint { margin-left: auto; }

.apm-split__tabs { display: none; }

/* ---------- reader drawer ---------- */
.apm-split__reader {
  position: absolute; z-index: 30; top: 10px; right: 10px; bottom: 10px; width: min(440px, calc(100% - 20px));
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto; border-radius: 16px; overflow: hidden;
  background: color-mix(in oklch, var(--apm-split-ink) 6%, var(--apm-split-bg));
