}
.apm-split__reader[hidden] { translate: 105% 0; opacity: 0; }
.apm-split__rhead { display: flex; align-items: center; gap: 10px; padding: 14px 12px 12px 18px; border-bottom: 1px solid var(--apm-split-line); }
.apm-split__rhead .apm-split__dot { flex: none; }
