.apm-split__x { margin-left: auto; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--apm-split-muted); }
.apm-split__x:hover { background: color-mix(in oklch, var(--apm-split-ink) 8%, transparent); color: var(--apm-split-ink); }
.apm-split__rbody { overflow: auto; padding: 18px 20px; display: grid; align-content: start; grid-auto-rows: max-content; gap: 12px; scrollbar-width: thin; }
.apm-split__rbody h2 { margin: 0; font-size: clamp(1.1rem, 1rem + .5cqi, 1.35rem); line-height: 1.2; font-weight: 680; letter-spacing: -0.02em; text-wrap: balance; }
.apm-split__rfrom { display: flex; align-items: center; gap: 10px; font-size: 12.5px; color: var(--apm-split-muted); }
.apm-split__rfrom b { color: var(--apm-split-ink); font-weight: 650; }
.apm-split__rbody p { margin: 0; font-size: 14px; line-height: 1.6; text-wrap: pretty; color: color-mix(in oklch, var(--apm-split-ink) 88%, var(--apm-split-bg)); }
.apm-split__rfoot { display: grid; gap: 8px; padding: 12px 14px 14px; border-top: 1px solid var(--apm-split-line); }
.apm-split__rfoot small { font-size: 11px; color: var(--apm-split-faint); letter-spacing: .08em; text-transform: uppercase; font-weight: 650; }
.apm-split__moves { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.apm-split__moves button { --c: var(--apm-split-ink); display: flex; align-items: center; justify-content: center; gap: 6px; height: 34px; border-radius: 8px; font-size: 12px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--apm-split-line2); transition: background-color .15s, box-shadow .15s; }
.apm-split__moves button::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
.apm-split__moves button:hover, .apm-split__moves button[aria-current="true"] { background: color-mix(in oklch, var(--c) 18%, transparent); box-shadow: inset 0 0 0 1px var(--c); }
.apm-split__moves kbd { padding: 2px 4px; min-width: 0; }
.apm-split__rarch { display: flex; gap: 6px; }
.apm-split__rarch button { flex: 1; height: 34px; border-radius: 8px; font-size: 12.5px; font-weight: 600; background: var(--apm-split-ink); color: var(--apm-split-bg); display: inline-flex; align-items: center; justify-content: center; gap: 8px; }
.apm-split__rarch kbd { background: color-mix(in oklch, var(--apm-split-bg) 14%, transparent); color: inherit; box-shadow: none; }

/* ---------- rules popover, prompt, toast ---------- */
.apm-split__rules {
  position: absolute; z-index: 35; top: 56px; right: 18px; width: min(360px, calc(100% - 36px)); padding: 14px; border-radius: 14px;
  background: color-mix(in oklch, var(--apm-split-ink) 8%, var(--apm-split-bg));
  box-shadow: 0 0 0 1px var(--apm-split-line2), 0 30px 60px -24px black;
