  @starting-style { opacity: 0; scale: .94; }
}
.apm-split__rules[hidden] { opacity: 0; scale: .96; }
.apm-split__rules h3 { margin: 0 0 4px; font-size: 14px; font-weight: 700; }
.apm-split__rules > p { margin: 0 0 10px; font-size: 12px; color: var(--apm-split-muted); text-wrap: pretty; }
.apm-split__rules ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
.apm-split__rules li { --c: var(--apm-split-ink); display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 8px; padding: 8px 6px 8px 10px; border-radius: 9px; background: color-mix(in oklch, var(--apm-split-ink) 5%, transparent); font-size: 12.5px;
  transition: opacity .3s, translate .4s var(--apm-split-spring); @starting-style { opacity: 0; translate: 0 -6px; } }
.apm-split__rules li span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-split__rules li i { font-style: normal; font-size: 11px; font-weight: 650; padding: 2px 7px; border-radius: 6px; color: var(--c); background: color-mix(in oklch, var(--c) 16%, transparent); }
.apm-split__rules li button { width: 24px; height: 24px; border-radius: 6px; display: grid; place-items: center; color: var(--apm-split-faint); }
.apm-split__rules li button:hover { color: var(--apm-split-ink); background: color-mix(in oklch, var(--apm-split-ink) 10%, transparent); }
.apm-split__rules li button svg { width: 14px; height: 14px; }
.apm-split__rules .apm-split__none { display: block; padding: 14px; text-align: center; color: var(--apm-split-faint); background: none; }

.apm-split__prompt {
  --c: var(--apm-split-ink);
  position: absolute; z-index: 32; left: 50%; bottom: 52px; width: max-content; max-width: calc(100% - 32px);
  display: flex; align-items: center; flex-wrap: wrap; gap: 8px 12px; padding: 10px 10px 10px 16px; border-radius: 14px;
  background: color-mix(in oklch, var(--apm-split-ink) 12%, var(--apm-split-bg)); box-shadow: 0 0 0 1px color-mix(in oklch, var(--c) 45%, transparent), 0 24px 50px -20px black;
