.apm-split__toast button[hidden] { display: none; }
.apm-split__toast kbd { background: color-mix(in oklch, var(--apm-split-bg) 12%, transparent); color: inherit; box-shadow: none; }

@keyframes apm-split-spin { to { rotate: 360deg; } }
@keyframes apm-split-arrive {
  0% { opacity: 0; translate: 0 -14px; box-shadow: 0 0 0 2px var(--c), 0 0 34px -4px var(--c); }
  30% { opacity: 1; translate: 0 0; box-shadow: 0 0 0 2px var(--c), 0 0 34px -4px var(--c); }
  100% { box-shadow: 0 0 0 1px var(--apm-split-line), 0 0 0 0 transparent; }
}

@container (width < 1060px) {
  .apm-split__screener { grid-template-columns: minmax(0, 1fr); gap: 8px; }
  .apm-split__shead span { display: inline; margin-left: 8px; }
  .apm-split__shead b { display: inline; }
}
@container (width < 960px) {
  .apm-split__board { grid-template-columns: none; grid-auto-flow: column; grid-auto-columns: minmax(250px, 42%); overflow-x: auto; scroll-snap-type: x mandatory; scroll-padding: 0 18px; scrollbar-width: thin; padding-bottom: 8px; }
  .apm-split__lane { scroll-snap-align: start; }
