  .apm-split__btn--pri kbd { display: none; }
  .apm-split__screener { margin: 0 12px 10px; }
  .apm-split__shead span { display: none; }
  .apm-split__tabs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; margin: 0 12px 10px; padding: 3px; border-radius: 11px; background: color-mix(in oklch, var(--apm-split-ink) 6%, transparent); }
  .apm-split__tabs button { --c: var(--apm-split-ink); height: 32px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--apm-split-muted); display: flex; align-items: center; justify-content: center; gap: 5px; transition: background-color .2s, color .2s; min-width: 0; }
  .apm-split__tabs button::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--c); flex: none; }
  .apm-split__tabs button[aria-selected="true"] { background: color-mix(in oklch, var(--c) 20%, var(--apm-split-bg)); color: var(--apm-split-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 50%, transparent); }
  .apm-split__tabs span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .apm-split__tabs i { font-style: normal; font-size: 10.5px; color: var(--apm-split-faint); font-variant-numeric: tabular-nums; }
  .apm-split__board { display: block; overflow: hidden; padding: 0 12px 4px; }
  .apm-split__lane { height: 100%; }
  .apm-split__card { touch-action: auto; cursor: pointer; }
  .apm-split__lane:not([data-active]) { display: none; }
  .apm-split__keys { display: none; }
  .apm-split__reader { top: 0; right: 0; bottom: 0; width: 100%; border-radius: 0; }
}
@container (width < 440px) {
  .apm-split__tabs button { font-size: 11px; gap: 4px; }
  .apm-split__tabs button::before { display: none; }
  .apm-split__moves { grid-template-columns: repeat(2, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  .apm-split *, .apm-split *::before, .apm-split *::after {
    transition-duration: .01ms !important; transition-delay: 0s !important;
    animation-duration: .01ms !important; animation-iteration-count: 1 !important;
  }
  .apm-split__card:hover { translate: none; }
}

