const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = CSS.supports('transition-timing-function', 'linear(0, 1)')
  ? 'linear(0, 0.06 3%, 0.25 7%, 0.62 14%, 0.89 21%, 1.03 29%, 1.07 35%, 1.05 43%, 1.01 56%, 0.995 72%, 1)'
  : 'cubic-bezier(.2, .9, .25, 1.12)';
const X = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>';
