/* Kiln & Co, a two-person ceramics studio. Every sender has an address so rules can match it. */
const M = {
  1: { from: 'Imogen Hart', a: 'imogen@larderandloom.co.uk', subj: 'PO for 60 Speckle mugs — need them by 20 Oct', time: '9:51', unread: true, body: ['We’d like 60 Speckle mugs for the Marylebone shop: 40 in Oat, 20 in Moss. Can you deliver by the 20th?', 'Same terms as spring — 50% on order, balance on delivery.'] },
