  3: { from: 'Dev Patel', a: 'dev@patel-accounts.co', subj: 'VAT return due 7 Oct — two receipts missing', time: 'Thu', unread: false, body: ['Nearly there. I’m missing the receipt for the kiln shelves (€486) and the clay order from 12 Sept (€312).', 'Snap them and reply here — I’ll file on Monday.'] },
  4: { from: 'Glazeworks Supply', a: 'orders@glazeworks.eu', subj: 'Order GW-55120 is delayed — cobalt oxide back in stock 9 Oct', time: 'Wed', unread: false, body: ['Two of the five lines on GW-55120 are waiting on cobalt oxide. Everything else ships today; the rest follows on the 9th at no extra charge.'] },
  5: { from: 'Oskar Lind', a: 'oskar@kilnandco.studio', subj: 'Kiln 2 firing log — cone 6 hit at 11:40', time: '8:20', unread: true, body: ['Clean firing. Cone 6 bent at 11:40, held 15 minutes, cooling now. Shelf 3 had one crawl on a Moss bowl — I’ll photograph it.'] },
  6: { from: 'Chiara Rinaldi', a: 'chiara.rinaldi@postmail.it', subj: 'Sunday lunch? Mamma is making the lasagne', time: 'Thu', unread: false, body: ['Sunday at 1? Bring the blue serving bowl back if you can.'] },
  7: { from: 'Nadia Bose', a: 'nadia@nadiabose.photo', subj: 'Photos from the market stall are up', time: 'Wed', unread: false, body: ['42 edited shots in the shared folder. The ones with the morning light on the Oat range are my favourites.'] },
  8: { from: 'Felix Amann', a: 'felix@bergenresidency.no', subj: 'Re: Residency in Bergen — dates for March', time: 'Tue', unread: false, body: ['We can offer 2–30 March. Studio, a shared gas kiln and accommodation are included; you cover travel.'] },
