  const mv = t.closest('[data-move]'); if (mv && S.open != null) { const id = S.open; moveCard(id, mv.dataset.move, 0); openReader(id); return; }
  const tab = t.closest('[data-tab]'); if (tab) { S.tab = tab.dataset.tab; paint(); const f = L[S.tab][0]; if (f != null) focusCard(f, false); return; }
  const un = t.closest('[data-unrule]'); if (un) { snapshot(); S.rules.splice(+un.dataset.unrule, 1); renderRules(); paint(); return; }
  const a = t.closest('[data-act]'); if (!a) return;
  switch (a.dataset.act) {
    case 'fetch': fetchMail(); break;
    case 'rules': rulesEl.hidden = !rulesEl.hidden; if (!rulesEl.hidden) renderRules(); break;
    case 'close': closeReader(); break;
    case 'archive': if (S.open != null) archive(S.open); break;
    case 'undo': undo(); break;
    case 'always': if (S.prompt) { snapshot(); const p = S.prompt; addRule(p.a, p.from, p.lane); prompt.removeAttribute('data-show'); S.prompt = null; showToast(`Rule saved: ${p.from} → ${LN[p.lane].name}`, true); } break;
    case 'once': prompt.removeAttribute('data-show'); S.prompt = null; break;
  }
});
root.addEventListener('keydown', (e) => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key;
  if (k === 'Escape') {
    if (!rulesEl.hidden) rulesEl.hidden = true;
    else if (!reader.hidden) closeReader();
    else if (prompt.hasAttribute('data-show')) { prompt.removeAttribute('data-show'); S.prompt = null; }
    else return;
    e.preventDefault(); return;
  }
  const onCard = e.target.closest('.apm-split__card');
  const inReader = !reader.hidden && reader.contains(e.target);
  if (k === 'z' || k === 'Z') { e.preventDefault(); undo(); return; }
  if (k === 'n' || k === 'N') { e.preventDefault(); fetchMail(); return; }
  if (inReader && S.open != null) {
    const lane = LANES.find((l) => l.key === k);
    if (lane) { e.preventDefault(); const id = S.open; moveCard(id, lane.id, 0); openReader(id); }
    else if (k === 'e') { e.preventDefault(); archive(S.open); }
    return;
  }
  if (!onCard) {
    if (k.startsWith('Arrow') && e.target === root) { e.preventDefault(); focusCard(S.focus); }
    return;
  }
  const id = +onCard.dataset.id; const lane = laneOf(id); const li = LANES.findIndex((l) => l.id === lane);
  const idx = L[lane].indexOf(id);
  if (k === 'ArrowDown') { e.preventDefault(); focusCard(L[lane][Math.min(idx + 1, L[lane].length - 1)]); }
  else if (k === 'ArrowUp') { e.preventDefault(); focusCard(L[lane][Math.max(idx - 1, 0)]); }
  else if (k === 'ArrowRight' || k === 'ArrowLeft') {
    e.preventDefault();
    const d = k === 'ArrowRight' ? 1 : -1;
    for (let j = li + d; j >= 0 && j < LANES.length; j += d) {
      const ids = L[LANES[j].id]; if (!ids.length) continue;
      focusCard(ids[Math.min(idx, ids.length - 1)]); break;
    }
  }
  else if (k === 'Enter' || k === ' ') { e.preventDefault(); openReader(id); }
  else if (k === 'e' || k === 'E') { e.preventDefault(); archive(id); }
  else { const tgt = LANES.find((l) => l.key === k); if (tgt) { e.preventDefault(); moveCard(id, tgt.id, 0); focusCard(id); } }
});

new ResizeObserver(() => { if (!root.isConnected) return; if (drag && drag.started) { drag.rr = root.getBoundingClientRect(); } }).observe(root);
paint();

