/* Operator search. Re-theme with --apm-query-paper, -ink, -accent, -mark (and -h). */
.apm-query {
  --apm-query-paper: oklch(0.992 0.003 95);
  --apm-query-ink: oklch(0.21 0.012 265);
  --apm-query-accent: oklch(0.52 0.17 258);
  --apm-query-mark: oklch(0.93 0.15 102);

  --apm-query-side: color-mix(in oklch, var(--apm-query-paper) 94%, var(--apm-query-ink));
  --apm-query-line: color-mix(in oklch, var(--apm-query-ink) 10%, transparent);
  --apm-query-line2: color-mix(in oklch, var(--apm-query-ink) 18%, transparent);
  --apm-query-muted: color-mix(in oklch, var(--apm-query-ink) 58%, var(--apm-query-paper));
  --apm-query-faint: color-mix(in oklch, var(--apm-query-ink) 38%, var(--apm-query-paper));
  --apm-query-hover: color-mix(in oklch, var(--apm-query-ink) 4.5%, transparent);
  --apm-query-tint: color-mix(in oklch, var(--apm-query-accent) 9%, var(--apm-query-paper));
  --apm-query-ease: cubic-bezier(.2, .85, .25, 1);
  --apm-query-spring: linear(0, 0.06 3%, 0.25 7%, 0.62 14%, 0.88 21%, 1.02 29%, 1.05 35%, 1.04 43%, 1.01 56%, 0.996 72%, 1);
  /* operator hues: tokens, chips and facets share them */
  --apm-query-k-from: oklch(0.52 0.14 152);
  --apm-query-k-subject: oklch(0.5 0.17 305);
  --apm-query-k-label: oklch(0.58 0.15 52);
  --apm-query-k-is: oklch(0.55 0.2 352);
  --apm-query-k-date: oklch(0.52 0.16 250);
  --apm-query-k-size: oklch(0.52 0.1 200);
  --apm-query-k-bad: oklch(0.56 0.21 27);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apm-query-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--apm-query-paper);
  color: var(--apm-query-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  outline: none;
  box-shadow: 0 0 0 1px var(--apm-query-line), 0 30px 60px -40px color-mix(in oklch, var(--apm-query-ink) 50%, transparent);
}
:where(.apm-query) *, :where(.apm-query) *::before, :where(.apm-query) *::after { box-sizing: border-box; }
:where(.apm-query) :is(button, input) { font: inherit; color: inherit; }
:where(.apm-query) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apm-query) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apm-query) :focus-visible { outline: 2px solid color-mix(in oklch, var(--apm-query-accent) 70%, transparent); outline-offset: 2px; }
:where(.apm-query) kbd { display: inline-block; min-width: 18px; padding: 3px 5px 2px; border-radius: 4px; text-align: center; font: 500 10.5px/1 ui-monospace, Menlo, monospace; background: color-mix(in oklch, var(--apm-query-ink) 6%, transparent); color: var(--apm-query-muted); box-shadow: inset 0 -1px 0 var(--apm-query-line); }
.apm-query [hidden] { display: none !important; }
.apm-query mark { background: var(--apm-query-mark); color: inherit; border-radius: 3px; box-shadow: 0 0 0 1.5px var(--apm-query-mark); }

.apm-query__app {
  display: grid; height: 100%;
  grid-template-columns: 236px minmax(0, 1fr) minmax(320px, 400px);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "bar bar bar" "side results preview";
}
.apm-query__bar { grid-area: bar; }
.apm-query__side { grid-area: side; }
.apm-query__results { grid-area: results; }
.apm-query__preview { grid-area: preview; }

/* ---------- search bar with a syntax-highlighted mirror ---------- */
.apm-query__bar { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 10px 8px; align-items: center; padding: 16px 18px 12px; border-bottom: 1px solid var(--apm-query-line); }
.apm-query__field {
  display: flex; align-items: center; gap: 10px; height: 48px; padding: 0 10px 0 14px; border-radius: 13px;
  background: white; box-shadow: 0 0 0 1px var(--apm-query-line2), 0 1px 2px color-mix(in oklch, var(--apm-query-ink) 8%, transparent);
  transition: box-shadow .25s var(--apm-query-ease);
}
.apm-query__field:focus-within { box-shadow: 0 0 0 2px var(--apm-query-accent), 0 10px 30px -14px color-mix(in oklch, var(--apm-query-accent) 50%, transparent); }
.apm-query__field > svg { color: var(--apm-query-muted); }
.apm-query__wrap { position: relative; flex: 1; min-width: 0; height: 100%; }
.apm-query__input, .apm-query__mirror {
  position: absolute; inset: 0; margin: 0; padding: 0; border: 0;
  font: 450 15px/48px ui-monospace, Menlo, monospace; letter-spacing: 0; white-space: pre; tab-size: 2;
}
.apm-query__input { width: 100%; background: transparent; outline: none; color: transparent; caret-color: var(--apm-query-ink); }
.apm-query__input::placeholder { color: var(--apm-query-faint); font-family: system-ui, -apple-system, "Segoe UI", sans-serif; font-size: 14px; }
.apm-query__input::selection { background: color-mix(in oklch, var(--apm-query-accent) 22%, transparent); color: transparent; }
.apm-query__mirror { overflow: hidden; pointer-events: none; color: var(--apm-query-ink); }
.apm-query__mirror > div { will-change: transform; }
.apm-query__mirror span { border-radius: 4px; }
.apm-query__mirror [data-t] { --c: var(--apm-query-ink); }
.apm-query__mirror [data-t="op"] { background: color-mix(in oklch, var(--c) 9%, transparent); box-shadow: 0 0 0 2px color-mix(in oklch, var(--c) 9%, transparent); }
.apm-query__mirror [data-t="op"] .apm-query__k { color: var(--c); }
.apm-query__mirror [data-t="phrase"] { background: color-mix(in oklch, var(--apm-query-mark) 70%, transparent); box-shadow: 0 0 0 2px color-mix(in oklch, var(--apm-query-mark) 70%, transparent); }
.apm-query__mirror [data-t="or"] { color: var(--apm-query-accent); }
.apm-query__mirror [data-neg] .apm-query__n { color: var(--apm-query-k-bad); }
.apm-query__mirror [data-neg] { text-decoration: line-through color-mix(in oklch, var(--apm-query-k-bad) 45%, transparent); }
.apm-query__mirror [data-t="unknown"], .apm-query__mirror [data-t="opbad"] { color: var(--apm-query-k-bad); text-decoration: underline wavy var(--apm-query-k-bad); text-underline-offset: 5px; text-decoration-skip-ink: none; }
.apm-query__mirror [data-k="from"], .apm-query__mirror [data-k="to"] { --c: var(--apm-query-k-from); }
.apm-query__mirror [data-k="subject"] { --c: var(--apm-query-k-subject); }
.apm-query__mirror [data-k="label"] { --c: var(--apm-query-k-label); }
.apm-query__mirror [data-k="has"], .apm-query__mirror [data-k="is"] { --c: var(--apm-query-k-is); }
.apm-query__mirror [data-k="before"], .apm-query__mirror [data-k="after"] { --c: var(--apm-query-k-date); }
.apm-query__mirror [data-k="larger"], .apm-query__mirror [data-k="smaller"] { --c: var(--apm-query-k-size); }
.apm-query__clear { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--apm-query-muted); opacity: 0; pointer-events: none; transition: opacity .2s, background-color .15s; }
.apm-query__field:has(.apm-query__input:not(:placeholder-shown)) .apm-query__clear { opacity: 1; pointer-events: auto; }
.apm-query__field:has(.apm-query__input:not(:placeholder-shown)) .apm-query__slash { display: none; }
.apm-query__clear:hover { background: var(--apm-query-hover); color: var(--apm-query-ink); }
.apm-query__savebtn, .apm-query__filters {
  display: inline-flex; align-items: center; gap: 7px; height: 48px; padding: 0 16px; border-radius: 13px; font-weight: 600; font-size: 13.5px;
  background: var(--apm-query-ink); color: var(--apm-query-paper);
  transition: transform .3s var(--apm-query-spring), filter .2s;
}
.apm-query__savebtn:hover { filter: brightness(1.25); }
.apm-query__savebtn:active { transform: scale(.96); }
.apm-query__savebtn svg { width: 16px; height: 16px; }
.apm-query__savebtn[data-saved] svg { fill: currentColor; }
.apm-query__filters { display: none; padding: 0; width: 48px; justify-content: center; background: var(--apm-query-side); color: var(--apm-query-ink); box-shadow: inset 0 0 0 1px var(--apm-query-line2); }
.apm-query__chips { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 6px; min-height: 26px; align-items: center; }
.apm-query__chip {
  --c: var(--apm-query-ink);
  display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 4px 0 9px; border-radius: 8px; font-size: 12px;
  background: color-mix(in oklch, var(--c) 9%, var(--apm-query-paper)); color: color-mix(in oklch, var(--c) 85%, var(--apm-query-ink));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 25%, transparent);
  transition: opacity .3s, scale .4s var(--apm-query-spring);
  @starting-style { opacity: 0; scale: .85; }
}
.apm-query__chip b { font-weight: 650; }
.apm-query__chip button { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 5px; opacity: .6; }
.apm-query__chip button:hover { opacity: 1; background: color-mix(in oklch, var(--c) 18%, transparent); }
.apm-query__chip button svg { width: 11px; height: 11px; stroke-width: 2.4; }
.apm-query__chip[data-bad] { --c: var(--apm-query-k-bad); }
.apm-query__chip[data-bad] button { opacity: 1; width: auto; padding: 0 7px; font-weight: 650; text-decoration: underline; text-underline-offset: 2px; }
.apm-query__chips > small { font-size: 12px; color: var(--apm-query-faint); }

/* ---------- side: saved searches + facets ---------- */
.apm-query__side { min-height: 0; overflow: auto; padding: 16px 12px 16px 14px; background: var(--apm-query-side); border-right: 1px solid var(--apm-query-line); display: grid; align-content: start; grid-auto-rows: max-content; gap: 22px; scrollbar-width: thin; }
.apm-query__side h3, .apm-query__facets h4 { margin: 0 0 6px 6px; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--apm-query-faint); }
.apm-query__saved ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.apm-query__saved li { position: relative;
  transition: opacity .3s, translate .4s var(--apm-query-spring); @starting-style { opacity: 0; translate: -8px 0; } }
.apm-query__sv { width: 100%; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 8px; padding: 7px 30px 7px 8px; border-radius: 9px; text-align: left; transition: background-color .15s; }
.apm-query__sv:hover { background: var(--apm-query-hover); }
.apm-query__sv[aria-current="true"] { background: white; box-shadow: 0 0 0 1px var(--apm-query-line), 0 3px 10px -6px color-mix(in oklch, var(--apm-query-ink) 40%, transparent); }
.apm-query__sv b { font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-query__sv i { font-style: normal; font-size: 12px; color: var(--apm-query-muted); font-variant-numeric: tabular-nums; }
.apm-query__sv code { grid-column: 1 / -1; font: 11px/1.4 ui-monospace, Menlo, monospace; color: var(--apm-query-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-query__unsave { position: absolute; right: 4px; top: 6px; width: 22px; height: 22px; border-radius: 6px; display: grid; place-items: center; color: var(--apm-query-faint); opacity: 0; transition: opacity .15s; }
.apm-query__saved li:hover .apm-query__unsave, .apm-query__unsave:focus-visible { opacity: 1; }
.apm-query__unsave:hover { background: var(--apm-query-hover); color: var(--apm-query-k-bad); }
.apm-query__unsave svg { width: 12px; height: 12px; stroke-width: 2.2; }
.apm-query__namer { display: flex; gap: 6px; margin-top: 6px; padding: 6px; border-radius: 10px; background: white; box-shadow: 0 0 0 1.5px var(--apm-query-accent);
  transition: opacity .25s, translate .35s var(--apm-query-spring); @starting-style { opacity: 0; translate: 0 -6px; } }
.apm-query__namer input { flex: 1; min-width: 0; height: 30px; padding: 0 8px; border: 0; outline: none; background: none; font-size: 13px; }
.apm-query__namer button { height: 30px; padding: 0 10px; border-radius: 7px; background: var(--apm-query-accent); color: white; font-size: 12.5px; font-weight: 650; }
.apm-query__facets { display: grid; gap: 16px; }
.apm-query__fgroup ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; }
.apm-query__f {
  --c: var(--apm-query-ink);
  position: relative; width: 100%; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 8px;
  padding: 6px 8px; border-radius: 8px; font-size: 13px; text-align: left; overflow: hidden; isolation: isolate;
  transition: background-color .15s;
}
.apm-query__f::before { content: ""; position: absolute; z-index: -1; left: 0; top: 3px; bottom: 3px; width: 100%; border-radius: 6px; background: color-mix(in oklch, var(--c) 11%, transparent); transform-origin: left; scale: var(--v, 0) 1; transition: scale .6s var(--apm-query-ease); }
.apm-query__f:hover { background: var(--apm-query-hover); }
.apm-query__f span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-query__f i { font-style: normal; font-size: 12px; color: var(--apm-query-muted); font-variant-numeric: tabular-nums; }
.apm-query__f[aria-pressed="true"] { box-shadow: inset 0 0 0 1.5px var(--c); }
.apm-query__f[aria-pressed="true"] span::after { content: " ✓"; color: var(--c); }
.apm-query__f[data-zero] { opacity: .45; }

/* ---------- results ---------- */
.apm-query__results { display: grid; grid-template-rows: auto minmax(0, 1fr); min-width: 0; min-height: 0; }
.apm-query__meta { display: flex; align-items: center; gap: 12px; padding: 12px 18px 8px; }
.apm-query__count { margin: 0; font-size: 12.5px; color: var(--apm-query-muted); font-variant-numeric: tabular-nums; }
.apm-query__count b { color: var(--apm-query-ink); font-size: 15px; font-weight: 700; letter-spacing: -0.01em; }
.apm-query__sort { margin-left: auto; display: inline-flex; padding: 2px; border-radius: 9px; background: color-mix(in oklch, var(--apm-query-ink) 5%, transparent); }
.apm-query__sort button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 550; color: var(--apm-query-muted); transition: background-color .2s, color .2s; }
.apm-query__sort button[aria-checked="true"] { background: white; color: var(--apm-query-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--apm-query-ink) 15%, transparent); }
.apm-query__list { list-style: none; margin: 0; padding: 0 8px 14px; overflow: auto; min-height: 0; outline: none; scrollbar-width: thin; overscroll-behavior: contain; }
.apm-query__row {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 12px; padding: 10px 12px; border-radius: 11px; cursor: pointer;
  transition: background-color .15s;
}
.apm-query__list[data-enter] .apm-query__row { animation: apm-query-in .42s var(--apm-query-ease) both; animation-delay: calc(var(--i) * 22ms); }
.apm-query__row:hover { background: var(--apm-query-hover); }
.apm-query__row[aria-selected="true"] { background: var(--apm-query-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apm-query-accent) 30%, transparent); }
.apm-query__list:focus-visible .apm-query__row[aria-selected="true"] { box-shadow: inset 0 0 0 2px var(--apm-query-accent); }
.apm-query__rfrom { font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 7px; min-width: 0; }
.apm-query__rfrom > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-query__row[data-unread] .apm-query__rfrom::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--apm-query-accent); flex: none; }
.apm-query__rdate { font-size: 12px; color: var(--apm-query-muted); font-variant-numeric: tabular-nums; white-space: nowrap; display: flex; align-items: center; gap: 6px; }
.apm-query__rdate svg { width: 13px; height: 13px; color: var(--apm-query-faint); }
.apm-query__rsubj { grid-column: 1 / -1; font-size: 13.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-query__row[data-unread] .apm-query__rsubj { font-weight: 650; }
.apm-query__rsnip { grid-column: 1 / -1; font-size: 12.5px; color: var(--apm-query-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apm-query__rlabels { grid-column: 1 / -1; display: flex; gap: 4px; margin-top: 4px; }
.apm-query__pill { --c: var(--apm-query-k-label); font-size: 11px; font-weight: 600; padding: 1px 7px; border-radius: 5px; background: color-mix(in oklch, var(--c) 12%, var(--apm-query-paper)); color: color-mix(in oklch, var(--c) 80%, var(--apm-query-ink)); }
.apm-query__none { padding: 50px 24px; text-align: center; color: var(--apm-query-muted); display: grid; justify-items: center; gap: 8px; }
.apm-query__none b { color: var(--apm-query-ink); font-size: 15px; text-wrap: balance; }
.apm-query__none p { margin: 0; max-width: 38ch; font-size: 13px; text-wrap: pretty; }
.apm-query__none svg { width: 44px; height: 44px; stroke-width: 1.3; color: var(--apm-query-faint); }

/* ---------- preview ---------- */
.apm-query__preview { min-width: 0; min-height: 0; overflow: auto; padding: 22px 22px 30px; border-left: 1px solid var(--apm-query-line); scrollbar-width: thin; background: white; }
.apm-query__pv { display: grid; gap: 12px;
  transition: opacity .35s var(--apm-query-ease), translate .45s var(--apm-query-ease); @starting-style { opacity: 0; translate: 0 8px; } }
