/* Swipe triage. Re-theme with --apm-swipe-bg, -ink and the three action colours (and -h). */
@property --apm-swipe-p { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --apm-swipe-a { syntax: "<angle>"; inherits: false; initial-value: 0deg; }

.apm-swipe {
  --apm-swipe-bg: oklch(0.175 0.014 52);
  --apm-swipe-ink: oklch(0.95 0.012 78);
  --apm-swipe-archive: oklch(0.73 0.15 152);
  --apm-swipe-snooze: oklch(0.81 0.14 74);
  --apm-swipe-delete: oklch(0.66 0.2 26);

  --apm-swipe-card: color-mix(in oklch, var(--apm-swipe-ink) 6%, var(--apm-swipe-bg));
  --apm-swipe-side: color-mix(in oklch, var(--apm-swipe-bg) 82%, black);
  --apm-swipe-line: color-mix(in oklch, var(--apm-swipe-ink) 10%, transparent);
  --apm-swipe-line2: color-mix(in oklch, var(--apm-swipe-ink) 18%, transparent);
  --apm-swipe-muted: color-mix(in oklch, var(--apm-swipe-ink) 60%, var(--apm-swipe-bg));
  --apm-swipe-faint: color-mix(in oklch, var(--apm-swipe-ink) 38%, var(--apm-swipe-bg));
  --apm-swipe-ease: cubic-bezier(.2, .85, .25, 1);
