@container (width < 960px) {
  .apm-swipe__app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .apm-swipe__side { grid-area: main; border: 0; padding-top: 86px; background: var(--apm-swipe-bg); }
  .apm-swipe__main { position: relative; z-index: 1; }
