/* Newsletter digest. Re-theme with --apm-digest-paper, -ink, -accent (and -h). */
.apm-digest {
  --apm-digest-paper: oklch(0.968 0.019 86);
  --apm-digest-ink: oklch(0.23 0.025 45);
  --apm-digest-accent: oklch(0.47 0.15 25);
  --apm-digest-fs: 17px;

  --apm-digest-sheet: color-mix(in oklch, var(--apm-digest-paper) 55%, white);
  --apm-digest-rail: color-mix(in oklch, var(--apm-digest-paper) 93%, var(--apm-digest-ink));
  --apm-digest-line: color-mix(in oklch, var(--apm-digest-ink) 13%, transparent);
  --apm-digest-rule: color-mix(in oklch, var(--apm-digest-ink) 70%, transparent);
  --apm-digest-muted: color-mix(in oklch, var(--apm-digest-ink) 60%, var(--apm-digest-paper));
  --apm-digest-faint: color-mix(in oklch, var(--apm-digest-ink) 40%, var(--apm-digest-paper));
  --apm-digest-hover: color-mix(in oklch, var(--apm-digest-ink) 5%, transparent);
  --apm-digest-serif: ui-serif, "New York", "Iowan Old Style", Georgia, serif;
  --apm-digest-ease: cubic-bezier(.2, .8, .2, 1);
  --apm-digest-spring: linear(0, 0.06 3%, 0.25 7%, 0.62 14%, 0.88 21%, 1.02 29%, 1.05 35%, 1.04 43%, 1.01 56%, 0.996 72%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apm-digest-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 14px;
  background: var(--apm-digest-paper);
  color: var(--apm-digest-ink);
  font: 400 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  outline: none;
  box-shadow: 0 0 0 1px var(--apm-digest-line);
}
:where(.apm-digest) *, :where(.apm-digest) *::before, :where(.apm-digest) *::after { box-sizing: border-box; }
:where(.apm-digest) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apm-digest) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apm-digest) :focus-visible { outline: 2px solid var(--apm-digest-accent); outline-offset: 3px; }
:where(.apm-digest) kbd { display: inline-block; min-width: 18px; padding: 3px 5px 2px; border-radius: 4px; text-align: center; font: 500 10.5px/1 ui-monospace, Menlo, monospace; background: color-mix(in oklch, var(--apm-digest-ink) 7%, transparent); color: var(--apm-digest-muted); }
.apm-digest [hidden] { display: none !important; }

.apm-digest__app { display: grid; height: 100%; grid-template-columns: 250px minmax(0, 1fr); grid-template-areas: "rail main"; }
.apm-digest__rail { grid-area: rail; }
.apm-digest__main { grid-area: main; }

/* ---------- rail ---------- */
.apm-digest__rail { display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto; min-height: 0; padding: 18px 12px 14px; background: var(--apm-digest-rail); border-right: 1px solid var(--apm-digest-line); }
