.apm-digest__x { display: none; margin-left: auto; width: 32px; height: 32px; place-items: center; border-radius: 8px; color: var(--apm-digest-muted); }
.apm-digest__railh { margin: 0 8px 8px; font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--apm-digest-faint); }
.apm-digest__subs { list-style: none; margin: 0; padding: 0; overflow: auto; min-height: 0; display: grid; align-content: start; grid-auto-rows: max-content; gap: 2px; scrollbar-width: thin; }
.apm-digest__sub { display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; align-items: center; gap: 0 10px; padding: 7px 8px; border-radius: 10px; transition: background-color .15s, opacity .3s;
  @starting-style { opacity: 0; } }
.apm-digest__sub:hover { background: var(--apm-digest-hover); }
