.apm-digest__subtools { grid-column: 3; grid-row: 1 / span 2; display: flex; align-items: center; gap: 2px; }
.apm-digest__switch { position: relative; width: 30px; height: 18px; border-radius: 9px; background: color-mix(in oklch, var(--apm-digest-ink) 18%, transparent); transition: background-color .25s; }
.apm-digest__switch::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0 1px 3px color-mix(in oklch, var(--apm-digest-ink) 30%, transparent); transition: translate .35s var(--apm-digest-spring); }
