.apm-digest__unsub:hover { color: var(--apm-digest-accent); background: color-mix(in oklch, var(--apm-digest-accent) 10%, transparent); }
.apm-digest__unsub svg { width: 14px; height: 14px; }
.apm-digest__railfoot { margin: 10px 8px 0; padding-top: 12px; border-top: 1px solid var(--apm-digest-line); font-size: 12px; color: var(--apm-digest-muted); text-wrap: pretty; font-variant-numeric: tabular-nums; }

/* ---------- edition ---------- */
