.apm-digest__allread { margin-left: auto; display: inline-flex; align-items: center; gap: 8px; height: 30px; padding: 0 10px; border-radius: 8px; font-size: 12.5px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--apm-digest-line); transition: background-color .15s; }
