.apm-digest__title { margin: 16px 0 6px; font: 700 clamp(2.1rem, 1rem + 4.2cqi, 3.6rem)/0.95 var(--apm-digest-serif); letter-spacing: -0.035em; text-wrap: balance; }
.apm-digest__summary { margin: 0; font: italic 400 15px/1.4 var(--apm-digest-serif); color: var(--apm-digest-muted); font-variant-numeric: tabular-nums; }
.apm-digest__bar { width: min(240px, 60%); height: 3px; margin: 12px auto 0; border-radius: 3px; background: var(--apm-digest-line); overflow: hidden; }
.apm-digest__bar i { display: block; height: 100%; background: var(--apm-digest-accent); transform-origin: left; scale: var(--p, 0) 1; transition: scale .8s var(--apm-digest-ease); }
