  position: absolute; right: 8px; top: 54px; padding: 6px 12px; border: 2.5px solid var(--apm-digest-accent); border-radius: 8px;
  font: 800 15px/1 var(--apm-digest-serif); letter-spacing: .2em; text-transform: uppercase; color: var(--apm-digest-accent);
