.apm-digest__pub i { width: 8px; height: 8px; border-radius: 2px; background: currentColor; }
.apm-digest__hl { margin: 0; font: 700 clamp(1.2rem, .95rem + .8cqi, 1.5rem)/1.15 var(--apm-digest-serif); letter-spacing: -0.02em; text-wrap: balance; transition: color .2s; }
.apm-digest__card[data-lead] .apm-digest__hl { font-size: clamp(1.6rem, 1rem + 2.2cqi, 2.4rem); line-height: 1.05; }
.apm-digest__card:hover .apm-digest__hl { color: var(--apm-digest-accent); }
.apm-digest__dek { margin: 0; font: 400 15px/1.45 var(--apm-digest-serif); color: var(--apm-digest-muted); text-wrap: pretty; }
.apm-digest__meta { display: flex; align-items: center; gap: 4px; margin-top: 4px; font-size: 12px; color: var(--apm-digest-muted); font-variant-numeric: tabular-nums; }
.apm-digest__meta span { margin-right: auto; }
.apm-digest__tool { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--apm-digest-faint); transition: color .15s, background-color .15s, scale .3s var(--apm-digest-spring); }
.apm-digest__tool:hover { color: var(--apm-digest-ink); background: var(--apm-digest-hover); }
.apm-digest__tool:active { scale: .85; }
.apm-digest__tool[aria-pressed="true"] { color: var(--apm-digest-accent); }
.apm-digest__tool[aria-pressed="true"] svg { fill: currentColor; }
.apm-digest__tool[data-k="done"][aria-pressed="true"] svg { fill: none; stroke-width: 2.4; }
.apm-digest__card[data-done] { opacity: .5; }
.apm-digest__card[data-done] .apm-digest__hl { text-decoration: line-through 1.5px color-mix(in oklch, var(--apm-digest-ink) 35%, transparent); }
@supports (animation-timeline: view()) {
  .apm-digest__card { animation: apm-digest-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 55%; }
}
