.apm-digest__next { display: grid; gap: 4px; width: 100%; margin-top: 30px; padding: 18px 20px; border-radius: 12px; text-align: left; background: var(--apm-digest-paper); box-shadow: inset 0 0 0 1px var(--apm-digest-line); transition: box-shadow .2s, translate .3s var(--apm-digest-spring); }
