  .apm-digest__app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .apm-digest__rail {
    position: absolute; z-index: 9; inset: 0 auto 0 0; width: min(300px, 86%);
    translate: -105% 0; visibility: hidden; transition: translate .45s var(--apm-digest-spring), visibility 0s .45s;
    box-shadow: 24px 0 60px -24px color-mix(in oklch, var(--apm-digest-ink) 45%, transparent);
  }
  .apm-digest[data-rail] .apm-digest__rail { translate: 0 0; visibility: visible; transition-delay: 0s; }
  .apm-digest[data-rail] .apm-digest__scrim { opacity: 1; pointer-events: auto; }
  .apm-digest__subsbtn, .apm-digest__x { display: grid; }
  .apm-digest__allread kbd { display: none; }
  .apm-digest__stamp { top: 64px; }
  .apm-digest__unsub { width: 24px; opacity: 1; }
}
@container (width < 440px) {
  .apm-digest__allread { font-size: 0; padding: 0; width: 34px; justify-content: center; }
  .apm-digest__allread::before { content: "✓"; font-size: 14px; }
  .apm-digest__rbar small { display: none; }
  .apm-digest__dateline { letter-spacing: .1em; }
}

@media (prefers-reduced-motion: reduce) {
  .apm-digest *, .apm-digest *::before, .apm-digest *::after {
    transition-duration: .01ms !important; transition-delay: 0s !important;
    animation-duration: .01ms !important; animation-iteration-count: 1 !important;
  }
  .apm-digest__card { animation: none !important; }
  .apm-digest__progress { animation: none !important; }
  .apm-digest[data-all] .apm-digest__stamp { animation: none; opacity: .9; scale: 1; }
}

