const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const I = {
  save: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4h12v17l-6-4-6 4z"/></svg>',
  done: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m8 12.5 3 3 5-6"/></svg>',
  back: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg>',
  up: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 15 6-6 6 6"/></svg>',
  down: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>',
};

const PUBS = [
  { id: 'form', name: 'Field Notes on Form', mono: 'FN', h: 25, cadence: 'Weekly · Fridays', topic: 'Design' },
  { id: 'thaw', name: 'The Thaw', mono: 'Th', h: 215, cadence: 'Weekly · Thursdays', topic: 'Climate' },
  { id: 'margin', name: 'Margin Call', mono: 'MC', h: 150, cadence: 'Weekdays', topic: 'Money' },
  { id: 'latency', name: 'Latency', mono: 'La', h: 265, cadence: 'Weekly · Fridays', topic: 'Engineering' },
  { id: 'ground', name: 'Common Ground', mono: 'CG', h: 60, cadence: 'Every other Friday', topic: 'Culture' },
  { id: 'table', name: 'The Long Table', mono: 'LT', h: 40, cadence: 'Weekly · Fridays', topic: 'Culture' },
  { id: 'signal', name: 'Signal & Noise', mono: 'SN', h: 305, cadence: 'Weekly · Wednesdays', topic: 'Engineering' },
  { id: 'paper', name: 'Paper Route', mono: 'PR', h: 85, cadence: 'Weekly · Fridays', topic: 'Money' },
  { id: 'allot', name: 'Tidings from the Allotment', mono: 'TA', h: 120, cadence: 'Monthly', topic: 'Culture' },
];
const L = [
  { id: 1, pub: 'form', by: 'Oona Reyes', title: 'Why every good chair is a little bit wrong', dek: 'The best furniture builds in small errors on purpose. Here is where to look for them.',
    quote: 'We read form with our bodies first and our rulers second.',
    body: ['Sit in a chair you love and run your hand along the back rail. Odds are it is not quite straight. Furniture makers call it relief: a few millimetres taken off where the eye expects a line, so that the line reads as straight once a body is in the picture.',
      'The same trick runs through architecture. Old columns swell slightly in the middle so they do not look pinched from below. Stair treads that are perfectly level feel as if they tip forward. Floors are laid with a whisper of crown so they never look sunken.',
      'We read form with our bodies first and our rulers second.',
      'This week I measured six chairs in my flat. The two I sit in most had the biggest deliberate deviations: a seat that falls nine millimetres toward the back, and arms that splay outward by four degrees. The one I never use is the most accurate object in the room.',
      'If you design screens, the lesson travels. Optical alignment beats mathematical alignment. Nudge a play icon to the right, let round shapes overshoot the baseline, and trust the squint test over the inspector panel.'] },
  { id: 2, pub: 'thaw', by: 'Kwame Asante', title: 'The heat pumps are winning, quietly', dek: 'Sales figures are noisy. Installer queues are not.',
    body: ['Every few months a headline declares heat pumps either finished or triumphant. Both are usually reading a single quarter of sales. A steadier signal is the queue: how long a household waits between signing a contract and having a unit on the wall.',
      'In the three regions we track, the median wait fell from eleven weeks last autumn to six weeks this September. That is not because demand fell — signed contracts are up 14% — but because the number of certified installers grew by a third.',
      'Training is the unglamorous bottleneck in most of the energy transition. When it loosens, everything downstream speeds up. Watch the queues, not the quarterly headlines.'] },
  { id: 3, pub: 'margin', by: 'Helena Voss', title: 'Three numbers on what the rate cuts did, and didn’t, do', dek: 'Mortgages moved fast. Business lending barely moved at all.',
    body: ['Mortgage rates are down 0.6 points since June, and approvals are up 9%. Households noticed the cuts within weeks, mostly through fixed-rate deals repricing.',
      'Business loans tell a different story. Rates fell 0.4 points, but volumes are flat. Owners we spoke to are waiting for demand, not cheaper money.',
      'Savers lost out first: deposit rates fell faster than loan rates, by about 0.2 points. If you have cash sitting in an easy-access account, this is the week to look at it.'] },
  { id: 4, pub: 'latency', by: 'Tobias Wren', title: 'The case for boring deploys', dek: 'If shipping feels like an event, you are shipping too much at once.',
    body: ['The most reliable teams I know deploy dozens of times a day, and none of those deploys is memorable. That is the point. A deploy should be as interesting as saving a file.',
      'Small changes are easy to review, easy to roll back and easy to reason about when something breaks at two in the morning. Large changes are none of those things, no matter how good the test suite is.',
      'Start by measuring the size of what you ship, not just how often. Then make the smallest batch the easiest path: feature flags by default, deploys that need no announcement, and a rollback that anyone on the team can run.'] },
  { id: 5, pub: 'ground', by: 'Ines Okoro', title: 'What a city learns by closing one street', dek: 'A six-week trial on a single high street produced numbers nobody expected.',
    body: ['For six weeks this summer, one high street closed to cars between 10:00 and 19:00. Shop owners braced for a slump. Instead, footfall rose 22% and the average visit grew from 19 to 31 minutes.',
      'The surprise was the side streets. Traffic there rose for the first week, then settled 8% below where it started, as drivers found other routes or simply stopped making short trips.',
      'The council votes next month on making the closure permanent. Whatever happens, the trial changed the argument: it is no longer about guesses, but about six weeks of counted footsteps.'] },
  { id: 6, pub: 'table', by: 'Marguerite Lau', title: 'A season of tomatoes, and what comes after', dek: 'The last good week of tomatoes is the best week to cook them.',
    body: ['The final tomatoes of the year are split, sun-tired and cheap. They are also the sweetest. Roast them slowly with garlic and a spoon of sugar, and they keep for a week under oil.',
      'When they are gone, turn to squash and the first bitter leaves. A warm salad of roasted squash, radicchio and toasted seeds is the bridge from one season to the next.'] },
  { id: 7, pub: 'signal', by: 'Dev Raman', title: 'Your dashboard is lying to you by averaging', dek: 'The mean hides the customers who are having a terrible day.',
    body: ['An average page load of 1.2 seconds sounds healthy. But if nine requests take 0.8 seconds and one takes 4.8, the average is still 1.2 — and one in ten people is waiting six times longer than everyone else.',
      'Percentiles tell the truth averages blur. Chart the 50th, the 95th and the 99th together, and the slow tail stops hiding behind the crowd.',
      'Better still, slice by the dimension that matters: region, device or plan. The worst experience is usually concentrated in one place, and that place is usually where you are not looking.'] },
  { id: 8, pub: 'paper', by: 'Sol Martínez', title: 'Small newsletters are the new trade press', dek: 'Niche publications with a few thousand readers are out-earning magazines.',
    body: ['A newsletter about cold-chain logistics with 4,000 subscribers can charge more for a single sponsorship than a general business magazine charges for a page. The readers are the buyers.',
      'The economics are simple: a focused audience, an open rate above 60%, and an editor whose judgement readers trust. Advertisers pay for the trust, not the reach.',
      'Expect more of them. The tools are cheap, the margins are good, and every industry has someone who knows it better than anyone writing about it today.'] },
  { id: 9, pub: 'allot', by: 'Agnes Pryor', title: 'Putting the beds to sleep for winter', dek: 'Cover the soil, leave the seed heads, and let the worms do the digging.',
    body: ['Bare soil is a winter casualty. Cover every empty bed with a thick layer of compost or leaf mould, and the worms will pull it down for you by spring.',
      'Leave the seed heads standing for the birds, and resist the urge to tidy. A slightly untidy plot in November is a busier, healthier one in April.'] },
];
const ORDER = L.map((l) => l.id);
/* reading time comes from the actual text at 230 words a minute, so every total adds up */
const words = (l) => l.body.join(' ').split(/\s+/).length;
const minutes = (l) => Math.max(1, Math.round(words(l) / 230));
const mins = (w) => Math.max(1, Math.round(w / 230));
const num = (n) => n.toLocaleString('en-GB');
const S = { subs: Object.fromEntries(PUBS.map((p) => [p.id, { on: true, digest: true }])), done: new Set(), saved: new Set(), topic: 'All', open: null, focus: 1, fs: 17, undo: null };
const pub = (id) => PUBS.find((p) => p.id === id);
const inEdition = (l) => S.subs[l.pub] && S.subs[l.pub].on && S.subs[l.pub].digest;

const grid = $('.apm-digest__grid');
const reader = $('.apm-digest__reader');
const edition = $('.apm-digest__edition');
