      <button class="apm-digest__tool" type="button" data-k="save" aria-pressed="${S.saved.has(l.id)}" title="Save for later (S)" aria-label="Save for later">${I.save}</button>
      <button class="apm-digest__tool" type="button" data-k="done" aria-pressed="${S.done.has(l.id)}" title="Mark read (M)" aria-label="Mark read">${I.done}</button></div>
