    const s = S.subs[p.id]; const l = L.find((x) => x.pub === p.id); const unread = l && !S.done.has(l.id) ? 1 : 0;
    return `<li class="apm-digest__sub" ${s.digest ? '' : 'data-off'}><span class="apm-digest__mono" style="--h:${p.h}">${p.mono}</span><b>${esc(p.name)}</b><small>${s.digest ? esc(p.cadence) : 'Arrives in your inbox'}${unread && s.digest ? ' · 1 new' : ''}</small>
