  $('.apm-digest__railfoot').textContent = `${subs.length} subscriptions · ${subs.filter((p) => S.subs[p.id].digest).length} bundled · about ${mins(total)} min of reading today`;
  /* masthead */
  const read = inEd.filter((l) => S.done.has(l.id)).length;
  const left = inEd.filter((l) => !S.done.has(l.id)).reduce((s, l) => s + words(l), 0);
  $('.apm-digest__summary').textContent = inEd.length ? `${inEd.length} letters · ${num(total)} words · about ${mins(total)} min${read ? ` · ${read} read${left ? `, ${mins(left)} min left` : ''}` : ''}` : 'Nothing bundled today';
  $('.apm-digest__bar i').style.setProperty('--p', inEd.length ? (read / inEd.length).toFixed(3) : 0);
  root.toggleAttribute('data-all', inEd.length > 0 && read === inEd.length);
  /* topics with live counts */
  const topics = ['All', 'Design', 'Climate', 'Money', 'Engineering', 'Culture', 'Saved'];
  $('.apm-digest__topics').innerHTML = topics.map((t) => {
    const n = t === 'All' ? inEd.length : t === 'Saved' ? inEd.filter((l) => S.saved.has(l.id)).length : inEd.filter((l) => pub(l.pub).topic === t).length;
    return (n || t === 'All' || t === S.topic) ? `<button class="apm-digest__topic" type="button" role="tab" data-topic="${t}" aria-selected="${S.topic === t}">${t}<i>${n}</i></button>` : '';
  }).join('');
  /* grid */
  const vis = visible();
  if (!vis.some((l) => l.id === S.focus) && vis.length) S.focus = vis[0].id;
  grid.innerHTML = vis.map((l, i) => cardHTML(l, i === 0 && S.topic === 'All')).join('') || `<p class="apm-digest__empty">${S.topic === 'Saved' ? 'Nothing saved yet. Press S on a letter to keep it.' : 'No letters in this section today.'}</p>`;
