  $('.apm-digest__end').textContent = out.length ? `That’s the edition. ${out.length === 1 ? '1 letter was' : out.length + ' letters were'} delivered to your inbox instead: ${out.map((l) => pub(l.pub).name).join(', ')}.` : 'That’s the edition. See you on Monday.';
}

/* ---------- reader with a shared-element transition on the headline ---------- */
function vt(update, pre) {
  const start = !RM.matches && (root.startViewTransition ? root.startViewTransition.bind(root) : document.startViewTransition ? document.startViewTransition.bind(document) : null);
