  return `<div class="apm-digest__rbar">
      <button class="apm-digest__back" type="button" data-act="close">${I.back}Edition</button>
      <small>${i + 1} of ${vis.length}</small>
      <button class="apm-digest__tool apm-digest__sp" type="button" data-act="prev" title="Previous (←)" aria-label="Previous letter" ${i <= 0 ? 'disabled' : ''}>${I.up}</button>
      <button class="apm-digest__tool" type="button" data-act="next" title="Next (→)" aria-label="Next letter" ${next ? '' : 'disabled'}>${I.down}</button>
      <button class="apm-digest__size" type="button" data-act="smaller" title="Smaller text ([)" aria-label="Smaller text">A</button>
      <button class="apm-digest__size" type="button" data-act="bigger" data-big title="Larger text (])" aria-label="Larger text">A</button>
      <button class="apm-digest__tool" type="button" data-k="save" data-id="${l.id}" aria-pressed="${S.saved.has(l.id)}" title="Save (S)" aria-label="Save for later">${I.save}</button>
      <i class="apm-digest__progress" aria-hidden="true"></i>
    </div>
    <div class="apm-digest__article" style="--h:${p.h}">
      <p class="apm-digest__pub"><i></i>${esc(p.name)}</p>
      <h1>${esc(l.title)}</h1>
      <p class="apm-digest__dek">${esc(l.dek)}</p>
      <div class="apm-digest__byline"><span>By <b>${esc(l.by)}</b></span><span>·</span><span>${num(words(l))} words · ${minutes(l)} min</span><span>·</span><span>${esc(p.cadence)}</span></div>
      <div class="apm-digest__body">${l.body.map((t) => (t === l.quote ? `<blockquote>${esc(t)}</blockquote>` : `<p>${esc(t)}</p>`)).join('')}</div>
      ${next ? `<button class="apm-digest__next" type="button" data-act="next"><small>Next in the edition · ${words(next)} words</small><b>${esc(next.title)}</b></button>` : `<button class="apm-digest__next" type="button" data-act="close"><small>End of the edition</small><b>Back to the front page</b></button>`}
    </div>`;
}
function openLetter(id) {
  const l = L.find((x) => x.id === id); if (!l) return;
  const card = $(`.apm-digest__card[data-id="${id}"] .apm-digest__hl`);
  const fromEdition = reader.hidden;
  const update = () => {
    if (card) card.style.viewTransitionName = '';
    S.open = id; S.focus = id; S.done.add(id);
    reader.innerHTML = readerHTML(l);
