  if (n) openLetter(n.id);
}
/* progress fallback for engines without scroll-driven animations */
reader.addEventListener('scroll', () => {
  const max = reader.scrollHeight - reader.clientHeight;
  const bar = $('.apm-digest__progress', reader); if (bar) bar.style.setProperty('--p', max > 0 ? (reader.scrollTop / max).toFixed(3) : 1);
}, { passive: true });

