  $$('.apm-digest__card').forEach((c) => { c.tabIndex = +c.dataset.id === id ? 0 : -1; });
  const c = $(`.apm-digest__card[data-id="${id}"]`); if (c) { c.focus({ preventScroll: true }); c.scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' }); }
