    return;
  }
  const tp = t.closest('[data-topic]'); if (tp) { S.topic = tp.dataset.topic; render(); edition.scrollTo({ top: 0, behavior: RM.matches ? 'auto' : 'smooth' }); return; }
  const sw = t.closest('[data-digest]');
  if (sw) { const s = S.subs[sw.dataset.digest]; s.digest = !s.digest; render(); showToast(s.digest ? `${pub(sw.dataset.digest).name} is back in the edition` : `${pub(sw.dataset.digest).name} will arrive in your inbox`); return; }
  const un = t.closest('[data-unsub]');
  if (un) {
    const id = un.dataset.unsub; const prev = S.subs[id];
    delete S.subs[id]; render();
    showToast(`Unsubscribed from ${pub(id).name}`, () => { S.subs[id] = prev; render(); });
    return;
  }
