    e.preventDefault(); return;
  }
  if (onBtn && (k === 'Enter' || k === ' ')) return;
  if (k === 'M') { e.preventDefault(); $('[data-act="all"]').click(); return; }
  if (!reader.hidden) {
    const map = { ArrowRight: () => stepLetter(1), ArrowLeft: () => stepLetter(-1), j: () => stepLetter(1), k: () => stepLetter(-1), '[': () => setFont(-1), ']': () => setFont(1),
      s: () => $('[data-k="save"]', reader).click(), m: () => { toggle(S.done, S.open); render(); } };
    if (map[k]) { e.preventDefault(); map[k](); }
