/* Keyboard-first mail. Re-theme with --apm-keys-bg, -ink, -accent (and -h). */
@property --apm-keys-score { syntax: "<number>"; inherits: true; initial-value: 0; }

.apm-keys {
  --apm-keys-bg: oklch(0.165 0.007 120);
  --apm-keys-ink: oklch(0.94 0.012 110);
  --apm-keys-accent: oklch(0.9 0.19 122);

  --apm-keys-panel: color-mix(in oklch, var(--apm-keys-ink) 4%, var(--apm-keys-bg));
  --apm-keys-raise: color-mix(in oklch, var(--apm-keys-ink) 8%, var(--apm-keys-bg));
  --apm-keys-line: color-mix(in oklch, var(--apm-keys-ink) 9%, transparent);
  --apm-keys-line2: color-mix(in oklch, var(--apm-keys-ink) 17%, transparent);
  --apm-keys-muted: color-mix(in oklch, var(--apm-keys-ink) 58%, var(--apm-keys-bg));
  --apm-keys-faint: color-mix(in oklch, var(--apm-keys-ink) 36%, var(--apm-keys-bg));
  --apm-keys-glow: color-mix(in oklch, var(--apm-keys-accent) 22%, transparent);
  --apm-keys-ease: cubic-bezier(.2, .9, .2, 1);
  --apm-keys-spring: linear(0, 0.07 3%, 0.28 7%, 0.66 14%, 0.92 21%, 1.04 28%, 1.07 34%, 1.05 42%, 1.01 55%, 0.996 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apm-keys-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--apm-keys-bg);
  color: var(--apm-keys-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  outline: none;
  box-shadow: inset 0 0 0 1px var(--apm-keys-line);
  transition: box-shadow .3s;
}
.apm-keys:focus-visible { box-shadow: inset 0 0 0 1px var(--apm-keys-line), 0 0 0 2px var(--apm-keys-accent); }
:where(.apm-keys) *, :where(.apm-keys) *::before, :where(.apm-keys) *::after { box-sizing: border-box; }
:where(.apm-keys) :is(button, input, textarea) { font: inherit; color: inherit; }
:where(.apm-keys) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apm-keys) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apm-keys) :focus-visible { outline: 2px solid var(--apm-keys-accent); outline-offset: 2px; }
:where(.apm-keys) kbd {
  display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 5px; border-radius: 5px;
  font: 600 11px/1 ui-monospace, Menlo, monospace; text-transform: uppercase;
  background: linear-gradient(color-mix(in oklch, var(--apm-keys-ink) 12%, var(--apm-keys-bg)), color-mix(in oklch, var(--apm-keys-ink) 7%, var(--apm-keys-bg)));
  box-shadow: inset 0 -1.5px 0 color-mix(in oklch, black 45%, transparent), 0 0 0 1px var(--apm-keys-line2);
  color: var(--apm-keys-ink);
}
.apm-keys [hidden] { display: none !important; }

.apm-keys__app {
  display: grid; height: 100%;
  grid-template-columns: minmax(330px, 0.95fr) minmax(0, 1.05fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top" "list reader" "hints hints";
}
.apm-keys__top { grid-area: top; }
.apm-keys__list { grid-area: list; }
.apm-keys__reader { grid-area: reader; }
.apm-keys__hints { grid-area: hints; }

/* ---------- top ---------- */
.apm-keys__top { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border-bottom: 1px solid var(--apm-keys-line); }
.apm-keys__tabs { display: flex; gap: 2px; min-width: 0; overflow-x: auto; scrollbar-width: none; }
.apm-keys__tab { position: relative; display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 12px; border-radius: 8px; font-size: 13px; font-weight: 600; color: var(--apm-keys-muted); white-space: nowrap; transition: color .2s, background-color .2s; }
.apm-keys__tab:hover { color: var(--apm-keys-ink); background: color-mix(in oklch, var(--apm-keys-ink) 5%, transparent); }
.apm-keys__tab[aria-current="true"] { color: var(--apm-keys-bg); background: var(--apm-keys-accent); }
.apm-keys__tab b { font-size: 11.5px; font-weight: 700; font-variant-numeric: tabular-nums; opacity: .75; }
.apm-keys__tab small { font: 500 10px/1 ui-monospace, Menlo, monospace; opacity: .55; letter-spacing: .04em; }
.apm-keys__tab[aria-current="true"] small { opacity: .7; }
.apm-keys__cmdbtn { margin-left: auto; display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 8px 0 12px; border-radius: 9px; font-size: 13px; color: var(--apm-keys-muted); box-shadow: inset 0 0 0 1px var(--apm-keys-line2); transition: color .2s, box-shadow .2s, background-color .2s; flex: none; }
.apm-keys__cmdbtn:hover { color: var(--apm-keys-ink); background: color-mix(in oklch, var(--apm-keys-ink) 5%, transparent); }
.apm-keys__cmdbtn svg { width: 15px; height: 15px; }
.apm-keys__score { --apm-keys-score: 0; display: flex; align-items: center; gap: 8px; flex: none; transition: --apm-keys-score .8s var(--apm-keys-ease); }
.apm-keys__score svg { width: 34px; height: 34px; rotate: -90deg; }
.apm-keys__score circle { fill: none; stroke: var(--apm-keys-line2); stroke-width: 3; }
.apm-keys__score .apm-keys__arc { stroke: var(--apm-keys-accent); stroke-linecap: round; stroke-dasharray: calc(var(--apm-keys-score) * 94.25) 100; filter: drop-shadow(0 0 4px var(--apm-keys-glow)); }
.apm-keys__score b { display: block; font: 700 14px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
.apm-keys__score small { font-size: 10.5px; color: var(--apm-keys-faint); letter-spacing: .04em; }

/* ---------- list with a sliding cursor ---------- */
.apm-keys__list { position: relative; min-height: 0; min-width: 0; border-right: 1px solid var(--apm-keys-line); }
.apm-keys__rows { position: absolute; inset: 0; list-style: none; margin: 0; padding: 6px 8px 12px; overflow: auto; outline: none; scrollbar-width: thin; overscroll-behavior: contain; z-index: 1; }
.apm-keys__cursor {
  position: absolute; z-index: 0; left: 8px; right: 8px; top: 0; height: var(--ch, 0px); border-radius: 10px; pointer-events: none;
  background: color-mix(in oklch, var(--apm-keys-accent) 9%, var(--apm-keys-bg));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apm-keys-accent) 35%, transparent), 0 0 24px -8px var(--apm-keys-glow);
  translate: 0 var(--cy, 0px); opacity: var(--co, 0);
  transition: translate .38s var(--apm-keys-spring), height .3s var(--apm-keys-ease), opacity .2s;
}
.apm-keys__cursor::before { content: ""; position: absolute; left: 0; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--apm-keys-accent); box-shadow: 0 0 10px var(--apm-keys-accent); }
.apm-keys__row {
  position: relative; z-index: 1;
  display: grid; grid-template-columns: 8px minmax(0, 150px) minmax(0, 1fr) auto; align-items: baseline; gap: 10px;
  padding: 11px 12px 11px 10px; border-radius: 10px; cursor: pointer; font-size: 13.5px;
}
.apm-keys__rows[data-enter] .apm-keys__row { animation: apm-keys-in .4s var(--apm-keys-ease) both; animation-delay: calc(var(--i) * 22ms); }
.apm-keys__row::before { content: ""; width: 6px; height: 6px; border-radius: 50%; align-self: center; }
.apm-keys__row[data-unread]::before { background: var(--apm-keys-accent); box-shadow: 0 0 8px var(--apm-keys-accent); }
.apm-keys__who { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--apm-keys-muted); }
.apm-keys__row[data-unread] .apm-keys__who { color: var(--apm-keys-ink); }
.apm-keys__line { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--apm-keys-faint); }
.apm-keys__line b { font-weight: 550; color: var(--apm-keys-muted); }
.apm-keys__row[data-unread] .apm-keys__line b { color: var(--apm-keys-ink); font-weight: 650; }
.apm-keys__when { font-size: 12px; color: var(--apm-keys-faint); font-variant-numeric: tabular-nums; display: flex; align-items: center; gap: 6px; }
.apm-keys__when svg { width: 13px; height: 13px; color: var(--apm-keys-accent); fill: currentColor; }
.apm-keys__row[aria-selected="true"] .apm-keys__who, .apm-keys__row[aria-selected="true"] .apm-keys__line b { color: var(--apm-keys-ink); }
.apm-keys__none { display: grid; place-items: center; align-content: center; gap: 10px; height: 100%; text-align: center; color: var(--apm-keys-muted); padding: 30px; }
.apm-keys__none b { font-size: 18px; color: var(--apm-keys-ink); letter-spacing: -0.01em; }
.apm-keys__none p { margin: 0; font-size: 13px; text-wrap: pretty; }

/* ---------- reader ---------- */
.apm-keys__reader { min-width: 0; min-height: 0; overflow: auto; scrollbar-width: thin; overscroll-behavior: contain; }
.apm-keys__rtools { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; gap: 4px; padding: 10px 18px; background: color-mix(in oklch, var(--apm-keys-bg) 88%, transparent); backdrop-filter: blur(10px); border-bottom: 1px solid var(--apm-keys-line); }
.apm-keys__act { display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 8px; border-radius: 8px; font-size: 12.5px; color: var(--apm-keys-muted); transition: background-color .15s, color .15s; }
.apm-keys__act:hover { background: color-mix(in oklch, var(--apm-keys-ink) 7%, transparent); color: var(--apm-keys-ink); }
.apm-keys__act kbd { height: 18px; min-width: 18px; font-size: 10px; }
.apm-keys__act[aria-pressed="true"] { color: var(--apm-keys-accent); }
.apm-keys__act--back { display: none; }
.apm-keys__doc { padding: clamp(20px, 3cqi, 36px) clamp(18px, 3cqi, 40px) 40px; max-width: 720px;
  transition: opacity .35s var(--apm-keys-ease), translate .45s var(--apm-keys-ease); @starting-style { opacity: 0; translate: 0 8px; } }
.apm-keys__doc h2 { margin: 0 0 14px; font-size: clamp(1.2rem, 1rem + 1cqi, 1.65rem); line-height: 1.18; font-weight: 680; letter-spacing: -0.025em; text-wrap: balance; }
.apm-keys__from { display: flex; align-items: center; gap: 12px; margin-bottom: 20px; font-size: 13px; color: var(--apm-keys-muted); }
.apm-keys__av { width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; font-size: 13px; font-weight: 700; background: oklch(0.34 0.06 var(--h)); color: oklch(0.93 0.07 var(--h)); flex: none; }
.apm-keys__from b { display: block; color: var(--apm-keys-ink); font-weight: 650; }
.apm-keys__doc p { margin: 0 0 1em; font-size: 14.5px; line-height: 1.65; text-wrap: pretty; color: color-mix(in oklch, var(--apm-keys-ink) 90%, var(--apm-keys-bg)); }
.apm-keys__replied { margin: 6px 0 18px; padding: 12px 14px; border-radius: 10px; background: var(--apm-keys-panel); box-shadow: inset 2px 0 0 var(--apm-keys-accent); font-size: 13.5px; white-space: pre-wrap; text-wrap: pretty;
  transition: opacity .4s, translate .5s var(--apm-keys-spring); @starting-style { opacity: 0; translate: 0 10px; } }
.apm-keys__replied small { display: block; font-size: 11.5px; color: var(--apm-keys-faint); margin-bottom: 4px; }
.apm-keys__compose { margin-top: 18px; display: grid; gap: 8px; padding: 12px; border-radius: 12px; background: var(--apm-keys-panel); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apm-keys-accent) 40%, transparent);
  transition: opacity .3s, translate .45s var(--apm-keys-spring); @starting-style { opacity: 0; translate: 0 10px; } }
.apm-keys__compose small { font-size: 12px; color: var(--apm-keys-faint); }
.apm-keys__compose textarea { width: 100%; min-height: 100px; resize: vertical; border: 0; outline: none; background: none; font-size: 14px; line-height: 1.55; }
.apm-keys__compose footer { display: flex; align-items: center; gap: 10px; font-size: 12px; color: var(--apm-keys-faint); }
.apm-keys__send { margin-left: auto; display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 12px; border-radius: 8px; background: var(--apm-keys-accent); color: var(--apm-keys-bg); font-weight: 700; font-size: 12.5px; }
.apm-keys__send kbd { background: color-mix(in oklch, var(--apm-keys-bg) 15%, transparent); box-shadow: none; color: inherit; height: 18px; }
.apm-keys__empty { display: grid; place-items: center; align-content: center; gap: 14px; height: 100%; padding: 30px; text-align: center; color: var(--apm-keys-faint); }
.apm-keys__empty div { display: flex; gap: 6px; }

/* ---------- hints bar: keycaps that light up when pressed ---------- */
.apm-keys__hints { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 16px; padding: 9px 16px; border-top: 1px solid var(--apm-keys-line); font-size: 11.5px; color: var(--apm-keys-faint); }
.apm-keys__hints span { display: inline-flex; align-items: center; gap: 6px; }
.apm-keys__hints kbd { transition: background .2s, color .2s, box-shadow .2s, translate .15s; }
.apm-keys__hints kbd.is-hit { animation: apm-keys-hit .5s var(--apm-keys-ease); }
.apm-keys__hints .apm-keys__more { margin-left: auto; }

/* ---------- chord HUD ---------- */
.apm-keys__chord {
  position: absolute; z-index: 25; left: 50%; top: 64px; display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-radius: 12px;
  background: var(--apm-keys-raise); box-shadow: 0 0 0 1px var(--apm-keys-line2), 0 20px 40px -18px black; font-size: 12.5px; color: var(--apm-keys-muted); white-space: nowrap;
  translate: -50% -10px; opacity: 0; pointer-events: none; transition: translate .35s var(--apm-keys-spring), opacity .2s;
}
.apm-keys__chord[data-show] { translate: -50% 0; opacity: 1; }
.apm-keys__chord b { color: var(--apm-keys-ink); }

/* ---------- palette ---------- */
.apm-keys__palette { position: absolute; inset: 0; z-index: 40; display: grid; justify-items: center; align-items: start; padding: 70px 16px 16px; background: color-mix(in oklch, black 45%, transparent); backdrop-filter: blur(2px);
  transition: opacity .2s, display .25s allow-discrete; @starting-style { opacity: 0; } }
.apm-keys__pbox { width: min(560px, 100%); border-radius: 16px; overflow: hidden; background: var(--apm-keys-raise); box-shadow: 0 0 0 1px var(--apm-keys-line2), 0 40px 80px -30px black, 0 0 0 1px color-mix(in oklch, var(--apm-keys-accent) 20%, transparent);
  transition: scale .35s var(--apm-keys-spring), translate .35s var(--apm-keys-spring); @starting-style { scale: .96; translate: 0 -10px; } }
.apm-keys__pfield { display: flex; align-items: center; gap: 10px; padding: 0 16px; border-bottom: 1px solid var(--apm-keys-line); }
.apm-keys__pfield svg { color: var(--apm-keys-accent); }
.apm-keys__pfield input { flex: 1; min-width: 0; height: 52px; border: 0; outline: none; background: none; font-size: 16px; caret-color: var(--apm-keys-accent); }
.apm-keys__pfield input::placeholder { color: var(--apm-keys-faint); }
.apm-keys__plist { list-style: none; margin: 0; padding: 6px; max-height: 330px; overflow: auto; scrollbar-width: thin; }
.apm-keys__plist p { margin: 8px 10px 4px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apm-keys-faint); }
.apm-keys__cmd { display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 9px; cursor: pointer; font-size: 13.5px; }
.apm-keys__cmd svg { width: 16px; height: 16px; color: var(--apm-keys-muted); }
.apm-keys__cmd mark { background: none; color: var(--apm-keys-accent); font-weight: 700; }
.apm-keys__cmd span:last-child { display: flex; gap: 3px; }
.apm-keys__cmd[aria-selected="true"] { background: color-mix(in oklch, var(--apm-keys-accent) 12%, transparent); }
.apm-keys__cmd[aria-selected="true"] svg { color: var(--apm-keys-accent); }
.apm-keys__pfoot { display: flex; gap: 14px; margin: 0; padding: 9px 14px; border-top: 1px solid var(--apm-keys-line); font-size: 11.5px; color: var(--apm-keys-faint); }
.apm-keys__pfoot span { display: inline-flex; align-items: center; gap: 4px; }

/* ---------- cheat sheet ---------- */
.apm-keys__sheet { position: absolute; inset: 0; z-index: 40; display: grid; place-items: center; padding: 16px; background: color-mix(in oklch, black 50%, transparent);
  transition: opacity .2s, display .25s allow-discrete; @starting-style { opacity: 0; } }
.apm-keys__sheetbox { width: min(720px, 100%); max-height: 100%; overflow: auto; padding: 22px 24px; border-radius: 18px; background: var(--apm-keys-raise); box-shadow: 0 0 0 1px var(--apm-keys-line2), 0 40px 80px -30px black;
  transition: scale .4s var(--apm-keys-spring); @starting-style { scale: .95; } }
.apm-keys__sheetbox h3 { margin: 0 0 4px; font-size: 18px; letter-spacing: -0.02em; }
.apm-keys__sheetbox > p { margin: 0 0 18px; font-size: 13px; color: var(--apm-keys-muted); }
.apm-keys__groups { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 18px 28px; }
.apm-keys__groups h4 { margin: 0 0 8px; font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--apm-keys-accent); }
.apm-keys__groups dl { margin: 0; display: grid; grid-template-columns: 1fr auto; gap: 7px 12px; font-size: 13px; }
.apm-keys__groups dd { margin: 0; display: flex; gap: 3px; justify-content: end; }
.apm-keys__groups dt { color: var(--apm-keys-muted); }

/* ---------- coach ---------- */
.apm-keys__coach {
  position: absolute; z-index: 30; right: 16px; bottom: 52px; display: flex; align-items: center; gap: 12px; padding: 10px 14px; border-radius: 12px;
  background: var(--apm-keys-raise); box-shadow: 0 0 0 1px color-mix(in oklch, var(--apm-keys-accent) 35%, transparent), 0 24px 50px -20px black; font-size: 13px; white-space: nowrap;
  translate: 0 14px; opacity: 0; pointer-events: none; transition: translate .45s var(--apm-keys-spring), opacity .25s;
}
.apm-keys__coach[data-show] { translate: 0 0; opacity: 1; }
.apm-keys__coach kbd { height: 26px; min-width: 26px; font-size: 13px; color: var(--apm-keys-bg); background: var(--apm-keys-accent); box-shadow: inset 0 -2px 0 color-mix(in oklch, black 30%, transparent); animation: apm-keys-tap 1.2s var(--apm-keys-ease) .2s 2; }
.apm-keys__coach span { color: var(--apm-keys-muted); }
.apm-keys__coach b { color: var(--apm-keys-ink); }

@keyframes apm-keys-in { from { opacity: 0; translate: -6px 0; } }
@keyframes apm-keys-hit { 0% { translate: 0 2px; background: var(--apm-keys-accent); color: var(--apm-keys-bg); box-shadow: 0 0 0 1px var(--apm-keys-accent), 0 0 14px var(--apm-keys-accent); } 100% { translate: 0 0; } }
@keyframes apm-keys-tap { 0%, 100% { translate: 0 0; } 20% { translate: 0 2px; box-shadow: inset 0 0 0 transparent, 0 0 12px var(--apm-keys-accent); } 40% { translate: 0 0; } }

@container (width < 960px) {
  .apm-keys__app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main" "hints"; }
  .apm-keys__list, .apm-keys__reader { grid-area: main; border: 0; }
  .apm-keys[data-view="list"] .apm-keys__reader { display: none; }
  .apm-keys[data-view="reader"] .apm-keys__list { display: none; }
  .apm-keys[data-view="reader"] .apm-keys__reader { animation: apm-keys-push .4s var(--apm-keys-ease) both; }
  .apm-keys__act--back { display: inline-flex; }
}
.apm-keys[data-split="off"] .apm-keys__app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main" "hints"; }
.apm-keys[data-split="off"] .apm-keys__list, .apm-keys[data-split="off"] .apm-keys__reader { grid-area: main; border: 0; }
.apm-keys[data-split="off"][data-view="list"] .apm-keys__reader { display: none; }
.apm-keys[data-split="off"][data-view="reader"] .apm-keys__list { display: none; }
.apm-keys[data-split="off"] .apm-keys__act--back { display: inline-flex; }
@keyframes apm-keys-push { from { opacity: 0; translate: 20px 0; } }
@container (width < 640px) {
  .apm-keys__cmdbtn span { display: none; }
  .apm-keys__score small { display: none; }
  .apm-keys__tab small { display: none; }
  .apm-keys__row { grid-template-columns: 8px minmax(0, 1fr) auto; grid-template-rows: auto auto; gap: 2px 10px; }
  .apm-keys__row::before { grid-row: span 2; }
  .apm-keys__line { grid-column: 2 / -1; grid-row: 2; }
  .apm-keys__who { grid-column: 2; grid-row: 1; }
  .apm-keys__when { grid-column: 3; grid-row: 1; }
  .apm-keys__rtools { overflow-x: auto; scrollbar-width: none; padding: 8px 10px; }
  .apm-keys__hints span:not(.apm-keys__more) { display: none; }
  .apm-keys__act span { display: none; }
}
@container (width < 440px) {
  .apm-keys__top { padding: 10px; gap: 6px; }
  .apm-keys__tab { padding: 0 9px; }
  .apm-keys__tab b { display: none; }
  .apm-keys__score { display: none; }
  .apm-keys__act kbd { display: none; }
  .apm-keys__act { padding: 0 6px; }
  .apm-keys__coach { left: 12px; right: 12px; white-space: normal; }
}

@media (prefers-reduced-motion: reduce) {
  .apm-keys *, .apm-keys *::before, .apm-keys *::after {
    transition-duration: .01ms !important; transition-delay: 0s !important;
    animation-duration: .01ms !important; animation-iteration-count: 1 !important;
  }
}

