  pList.innerHTML = items.map((x, i) => {
    const head = x.g !== g ? `<p>${esc(x.g)}</p>` : ''; g = x.g;
    return `${head}<li class="apm-keys__cmd" role="option" id="apm-keys-${UID}-c${i}" data-i="${i}" aria-selected="${i === S.pal.i}">${ic(x.c.icon)}<span>${hl(x.c.label, x.hits)}</span><span>${x.c.keys.map((k) => `<kbd>${esc(k)}</kbd>`).join('')}</span></li>`;
  }).join('') || `<li class="apm-keys__cmd" role="option" aria-disabled="true"><span></span><span>No command matches “${esc(q)}”</span><span></span></li>`;
  pInput.setAttribute('aria-activedescendant', `apm-keys-${UID}-c${S.pal.i}`);
}
function paintPalSel() {
  $$('.apm-keys__cmd', pList).forEach((el) => el.setAttribute('aria-selected', +el.dataset.i === S.pal.i));
  pInput.setAttribute('aria-activedescendant', `apm-keys-${UID}-c${S.pal.i}`);
  const el = $(`.apm-keys__cmd[data-i="${S.pal.i}"]`, pList); if (el) el.scrollIntoView({ block: 'nearest' });
}
pInput.addEventListener('input', () => { S.pal.i = 0; paintPalette(); });
pInput.addEventListener('keydown', (e) => {
  e.stopPropagation();
  const n = S.pal.items.length;
  if (e.key === 'ArrowDown') { e.preventDefault(); S.pal.i = (S.pal.i + 1) % Math.max(1, n); paintPalSel(); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); S.pal.i = (S.pal.i - 1 + n) % Math.max(1, n); paintPalSel(); }
  else if (e.key === 'Enter') { e.preventDefault(); const x = S.pal.items[S.pal.i]; if (x) { closePalette(); run(x.c.id, 'kb'); } }
  else if (e.key === 'Escape' || ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k')) { e.preventDefault(); closePalette(); }
});
pList.addEventListener('click', (e) => { const li = e.target.closest('.apm-keys__cmd[data-i]'); if (li) { const x = S.pal.items[+li.dataset.i]; closePalette(); run(x.c.id, 'kb'); } });
palette.addEventListener('click', (e) => { if (e.target === palette) closePalette(); });

/* ---------- cheat sheet, chord HUD, coach ---------- */
function openSheet() {
  const groups = ['Actions', 'Go to', 'View'];
  sheet.innerHTML = `<div class="apm-keys__sheetbox"><h3>Keyboard shortcuts</h3><p>Everything here is also in the command palette. Press <kbd>?</kbd> or <kbd>esc</kbd> to close.</p>
    <div class="apm-keys__groups">${groups.map((g) => `<div><h4>${g}</h4><dl>${CMDS.filter((c) => c.group === g && c.keys.length).map((c) => `<dt>${esc(c.label)}</dt><dd>${c.keys.map((k) => `<kbd>${esc(k)}</kbd>`).join('')}</dd>`).join('')}</dl></div>`).join('')}
      <div><h4>Move</h4><dl><dt>Next / previous</dt><dd><kbd>J</kbd><kbd>K</kbd></dd><dt>Open</dt><dd><kbd>↵</kbd></dd><dt>Back</dt><dd><kbd>esc</kbd></dd><dt>Command palette</dt><dd><kbd>⌘K</kbd></dd></dl></div></div></div>`;
  sheet.hidden = false;
}
function closeSheet() { sheet.hidden = true; root.focus({ preventScroll: true }); }
sheet.addEventListener('click', (e) => { if (e.target === sheet) closeSheet(); });
function showChord() {
  chordEl.innerHTML = `<kbd>G</kbd><span>then</span>${TABS.map((t) => `<span><kbd>${t.keys.split(' ')[1].toUpperCase()}</kbd> <b>${t.name}</b></span>`).join('')}`;
  chordEl.setAttribute('data-show', '');
}
function showCoach(c) {
  coach.innerHTML = `<span>Faster:</span>${c.keys.map((k) => `<kbd>${esc(k)}</kbd>`).join('')}<span><b>${esc(c.label)}</b></span>`;
  coach.setAttribute('data-show', ''); clearTimeout(showCoach.t);
  showCoach.t = setTimeout(() => coach.removeAttribute('data-show'), 3200);
}
function showCoachText(t) {
  coach.innerHTML = `<span>${esc(t)}</span>`;
  coach.setAttribute('data-show', ''); clearTimeout(showCoach.t);
  showCoach.t = setTimeout(() => coach.removeAttribute('data-show'), 2600);
}

/* ---------- input ---------- */
rowsEl.addEventListener('click', (e) => {
  const r = e.target.closest('.apm-keys__row'); if (!r) return;
  S.mouse++; paintScore();
  select(+r.dataset.id, true);
  if (single()) showCoach({ keys: ['↵'], label: 'Open the selected conversation' });
});
root.addEventListener('click', (e) => {
  const tab = e.target.closest('[data-tab]'); if (tab) { run('go-' + tab.dataset.tab, 'mouse'); return; }
  const b = e.target.closest('[data-cmd]');
  if (b) { if (b.dataset.cmd === 'back') { root.dataset.view = 'list'; S.reply = null; return; } run(b.dataset.cmd, 'mouse'); return; }
  if (e.target.closest('[data-act="palette"]')) { S.mouse++; paintScore(); showCoach({ keys: ['⌘', 'K'], label: 'Open the command palette' }); openPalette(); }
});
root.addEventListener('submit', (e) => { e.preventDefault(); sendReply(); });
root.addEventListener('keydown', (e) => {
  if (!palette.hidden) return;
  const k = e.key; const mod = e.metaKey || e.ctrlKey;
  if (!sheet.hidden) { if (k === 'Escape' || k === '?') { e.preventDefault(); closeSheet(); } return; }
  if (e.target.closest('textarea')) {
    if (mod && k === 'Enter') { e.preventDefault(); S.kb++; paintScore(); sendReply(); }
    else if (k === 'Escape') { e.preventDefault(); S.reply = null; paintReader(); root.focus({ preventScroll: true }); }
    return;
  }
  if (mod && k.toLowerCase() === 'k') { e.preventDefault(); S.kb++; paintScore(); flash(['⌘K']); openPalette(); return; }
  if (mod || e.altKey) return;
  if (e.target.closest('button') && (k === 'Enter' || k === ' ')) return;
  if (S.chord) {
    clearTimeout(S.chord); S.chord = null; chordEl.removeAttribute('data-show');
    const t = TABS.find((x) => x.keys.split(' ')[1] === k.toLowerCase());
    if (t) { e.preventDefault(); run('go-' + t.id, 'kb'); }
    return;
  }
  if (k === 'g') { e.preventDefault(); flash(['G']); showChord(); S.chord = setTimeout(() => { if (!root.isConnected) return; S.chord = null; chordEl.removeAttribute('data-show'); }, 1600); return; }
  const simple = { j: () => { step(1); flash(['J']); }, ArrowDown: () => step(1), k: () => { step(-1); flash(['K']); }, ArrowUp: () => step(-1),
    Enter: () => { if (S.cur != null) { S.kb++; paintScore(); flash(['↵']); select(S.cur, true); if (!single()) reader.scrollTop = 0; } }, o: () => S.cur != null && select(S.cur, true),
    Escape: () => { if (single() && root.dataset.view === 'reader') root.dataset.view = 'list'; }, '.': () => openPalette() };
  if (simple[k]) { e.preventDefault(); simple[k](); return; }
  const keyMap = { e: 'done', s: 'star', u: 'unread', '#': 'trash', h: 'snooze1', r: 'reply', a: 'replyall', z: 'undo', '\\': 'split', '?': 'help' };
  const id = keyMap[k];
  if (id) { e.preventDefault(); run(id, 'kb'); }
});
new ResizeObserver(() => { if (!root.isConnected) return; if (!single()) root.dataset.view = 'list'; moveCursor(true); }).observe(root);

